quests[24946] = { id = 24946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrockpulver", description = "Eines muss man diesen Pygmäen ja lassen… Sie wissen, wie man Partys feiert! Aber sie sind nicht besonders klug. Ich glaube, ich kenne jetzt die Quelle ihrer Abrockkräfte: Abrockpulver!\n\nUnd wie sich herausstellt verwandelt dieses Zeug sie nicht nur in Weltklasse-Rocker, sondern ist auch noch hochgradig explosiv. Wir müssen es einfach haben!\n\nAlso, wenn Ihr in Oostan im Osten seid, sammelt so viel von dem Zeug, wie Ihr tragen könnt. Vertraut mir, Ihr werdet es bald schon brauchen!", sourceObjective = "Sammelt 5 Handvoll Abrockpulver.", progress = "Hmm, mal sehen, wie viel Ihr schon habt.", completion = "Das wird reichen. Es ist sogar mehr, als wir brauchen. Ich habe eine geniale Idee für eine Waffe, in die wir diese Stiefel verwandeln können, sobald Ihr sie Hobart gebracht habt.\n\nGebt mir das Pulver, damit ich die Superträgerraketenstiefel damit aufladen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24947] = { id = 24947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momentum", description = "Wir können uns noch nicht auf unseren Lorbeeren ausruhen, Schätzchen. Wir müssen das Momentum beibehalten! Die Leute sprechen schon über uns.\n\nLeider sprechen sie aber auch über diese hohle Gnomin Kelsey, die wohl auch Arbeiten wie wir verrichtet. Wenn wir sie aus dieser Stadt, die rechtsmäßig den Goblins zusteht, vertreiben wollen, so müssen wir es richtig tun.\n\nWir werden uns dem Seeräuberproblem widmen, in dem sich Gadgetzan befindet, und dem Problem ein Ende bereiten, ein für alle Mal. Begebt Euch zur Mast- und Schotbucht; ich werde Euch dort treffen.", sourceObjective = "Trefft Megs Schredderschreck in der Mast- und Schotbucht.", completion = "Gut, dass Ihr hier seid! Ich werde Eure Hilfe benötigen, wenn wir diesen Gnomen zuvorkommen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24948] = { id = 24948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belagerung aufheben", description = "Wir werden die Mauern der Feste nie wieder sichern können, solange Donnerschrei und seine Schläger Zugang zu Artillerie haben. Ihr müsst Euch durch diesen Abgrund kämpfen und seine großen Kanonen unbrauchbar machen.\n\nOrcs lagern ihr schweres Gerät in Kohlenteer, wodurch dieses leicht entzündlich wird. Nehmt meine Fackel und verbrennt alle Katapulte, die Ihr nördlich von Nordwacht seht.\n\nDann zündet diese großen Klingenwerfer in Donnerschreis Hauptlager an! Diese Dinger haben genug unserer Männer getötet.", sourceObjective = "Benutzt Paxtons Fackel um 3 Katapulte von Donnerschrei und 1 Klingenwerfer von Donnerschrei zu verbrennen.", progress = "Fackelt alles ab, {class}. Verbrennt es zu Asche!", completion = "Gut! Ohne schweres Gerät, muss die Horde sich zurückziehen, um sich neu zu formieren. Wir haben uns etwas Zeit verschafft, um die Feste wieder zu sichern. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[24949] = { id = 24949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beutepflicht", description = "Wir sollten hier nichts verschwenden, Schätzchen. Diese Seeräuber haben tonnenweise wertvollen Humbug herumliegen, der nur eingesammelt werden will. Könnt Ihr es fassen, dass sie es einfach nur besitzen und nichts damit machen?\n\nIch meine, warum machen sie sich denn erst die Mühe, es zu erlangen, wenn sie nur darum herumsitzen? Gestohlene Ware sollte so schnell wie möglich verkauft werden, um mit dem Erlös tolle neue Sachen kaufen zu können.\n\nNaja - seid ein Schatz und sammelt so viel Ihr könnt von ihrer Beute, während Ihr ihnen die Köpfe einschlagt. Ciao!", sourceObjective = "Sammelt 10 Stück Piratenbeute.", progress = "Mal sehen, was Ihr gefunden habt. Ihr habt nichts für Euch selbst einbehalten, oder? Ohne mich werdet Ihr keine Käufer finden, ich hoffe, Ihr seid Euch dessen bewusst.", completion = "Wunderschön! Und der Gedanke, dass sie nur darauf herumgesessen sind... Idioten.\n\nHier habt Ihr Euren Vorschuss; über die Boni der Gewinnteilung unterhalten wir uns später.", sourceObjectiveStatus = "unverified-source-field" }
quests[24950] = { id = 24950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän Schreckensbart", description = "Nun gut, Schätzchen, jetzt habe ich etwas Größeres für Euch.\n\nWir haben den Kapitän der Südmeerfreibeuter auf einem seiner Boote südlich von hier entdeckt. Südlich, NICHT da, wo wir für mehrere Stunden lebensmüde Rausschmeißer gespielt haben. Er sitzt auf seinem Boot, eingebildet und stoisch, und sieht uns beim Krieg führen zu.\n\nSeine Witze zur \"feindlichen Übernahme\" erspare ich Euch. Begebt Euch zu seinem Schiff, prügelt den Seemann aus ihm heraus und dann sind wir auch schon fertig hier!", sourceObjective = "Tötet Kapitän Schreckensbart.", completion = "Meeresriesen? Ihr meint, er hat sie absichtlich auf Gadgetzan abgerichtet?\n\nEgal, den sind wir erstmal los. Und Gadgetzan ist uns auch wirklich etwas schuldig! Ich kann den Blick auf Marins Gesicht gar nicht erwarten!\n\nHier ist Euer Anteil, Schätzchen. Ihr macht noch richtig Karriere!", sourceObjectiveStatus = "unverified-source-field" }
quests[24951] = { id = 24951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine großartige Idee", description = "Diesen Haufen Frischfleisch müssen wir jetzt nur nach an dem Seil befestigen... und dann könnt Ihr mir auch schon ein paar Silithiden fangen.\n\nWie? Schaut mich nicht so an, es ist wirklich sicher. Ziemlich sicher. Sterben könnt Ihr schon. Auch einen schmerzvollen Tod. Aber es ist einfach! Werft das Fleisch dort runter, wartet, bis eines der Ungeziefer darauf anspringt, und zieht es dann mit dem Seil hier hoch!\n\nVersucht es bei den Schwärmern. Bei den anderen weiß ich nicht, ob sie Hyäne mögen, aber Schwärmer gibt es um die Ecke der Schlucht genug.", sourceObjective = "Benutzt den Käferköder der Schmuggler, um einen Schwärmer der Hazzali zu ködern.", completion = "Seht nur, wie groß es ist! Es ist wunderbar. Dieser eklige Schwärmer wird uns dabei helfen, den ganzen Schwarm zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[24952] = { id = 24952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenstiefelkick", description = "Ihr müsst diese Stiefel in die Caldera zu Hobart Wurfhammer bringen.\n\nJetzt, da sie mit dem übrigen Abrockpulver verstärkt wurden, sollten sie genügend Schubkraft haben, um Euch in einem Schuss bis ganz nach unten zu bringen.\n\nWenn Ihr bereit seid, aktiviert einfach die Stiefel. Keine Sorge, sie sind so eingestellt, dass sie Euch automatisch sanft auf den Boden bringen.\n\nGlaube ich zumindest.", sourceObjective = "Benutzt die abrockpulververstärkten Raketenstiefel und bringt sie zu Hobart Wurfhammer.", progress = "Ah, da seid Ihr ja!", completion = "Wir haben keine Zeit zu verschwenden, Junge!\n\nWas ist denn mit dem Regler am linken Stiefel los?!", sourceObjectiveStatus = "unverified-source-field" }
quests[24953] = { id = 24953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeziefer ausmerzen", description = "Jetzt geht es mit meinem Plan erst richtig los. Wir haben den Schwärmer gefesselt und mit so viel Sprengstoff eingekleidet, wie er wohl tragen kann. Und nun werden wir dank Pfauentraums unfassbar toller mentaler Kräfte dieses Ungeziefer direkt in die Mitte der unterirdischen Höhle befehligen.\n\nUnd dann... KABUMM! Ungeziefer weg!\n\nIhr erhaltet die Ehre, das Ding kontrollieren zu dürfen. Sprecht mit Narain und macht Euch und Euren Ungezieferfreund startklar.", sourceObjective = "Sprecht mit Narain Pfauentraum, um den gedankenkontrollierten Schwärmer in den Bau der Klaffenden Schlucht zu befehligen.", progress = "Ich habe keine Höhlenexplosion gehört! Versucht es nochmal!", completion = "Oh Mann, das war genial! Ihr hättet die Flammen sehen sollen, die aus dem Bau kamen!\n\nHier ist Eure Belohnung, für die Unterhaltung, die Ihr mir beschert habt und natürlich auch für die Räumung des Ungezieferbaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[24954] = { id = 24954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Schildkrötengottes Kinder", description = "Volcanoth ist der Schildkrötengott in der Höhle, den diese Primitiven verehren.\n\nEr ist nicht wirklich ein Gott.\n\n<Hobart verdreht die Augen.>\n\nAber er ist hart genug, damit ich Euch aus dem letzten funktionierenden Stiefel eine neue Waffe basteln muss.\n\nIch glaube, das alte Motto \"Feuer mit Feuer bekämpfen\" passt hier ganz gut. Und außerdem mag ich Feuer!\n\nUnd jetzt sammelt mir ein paar Feuerdrüsen von den Abkömmlingen von Volcanoth. Das sollte mir genug Zeit verschaffen, um den Raketenstiefel in etwas Passenderes zu verwandeln.", sourceObjective = "Sammelt 5 Feuerdrüsen.", progress = "Wann ließe sich diese einfache Aufgabe besser erledigen, als jetzt, {name}?", completion = "Seid vorsichtig mit diesen Drüsen, {name}, vorsichtig!\n\n\n\nUnd jetzt ladet den umgebauten Raketenstiefel damit. Ich bin mir sicher, dass meine geniale Erfindung Euch aus den Socken hauen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[24955] = { id = 24955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-satzung", description = "Ich habe ja bereits erwähnt, dass ich versuche, die Oger der Dünenbrecher in die Horde zu bringen... und für das Bilgewasserkartell billige Arbeit vor Ort zu verrichten.\n\nUm das zu schaffen, müssen wir ein Bekenntnis zum Einführungsprozess ablegen, oder ich bekomme später richtig Ärger. Deswegen habe ich diese Satzung verfasst und die Initiationsriten unserem zeitlich begrenztem Arbeitsvertrag beigefügt.\n\nIch habe auch eine Verkleidung für Euch, also macht Euch an die Arbeit und besorgt mir die Unterschriften.", sourceObjective = "Erhaltet 10 Unterschriften der Satzung von Ogern der Dünenbrecher.", completion = "Wow, gute Arbeit! Es ist ja schon toll, dass Ihr sie dazu gebracht habt, die Stifte zu halten und NICHT zu essen.\n\nDen Anzug könnt Ihr ablegen. Da drüben hin. Weg von mir. Ins Feuer.", sourceObjectiveStatus = "unverified-source-field" }
quests[24956] = { id = 24956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerschrei zum Schweigen bringen", description = "Ich bin dem Donnerschreiklan früher schon begegnet, {name}. Er wird nicht von einem Orc angeführt, sondern von einem Monster - einem kriegsbesessenen Unhold, der keinerlei Anstand oder Mitleid besitzt. Er und seine Leutnants müssen sterben - nicht nur, um Nordwacht zu retten, sondern zum Wohle von ganz Azeroth.\n\nKarga Donnerschrei trägt einen Helm. Richtet ihn hin, {class} und bringt mir diesen Helm. Er ist von ... besonderer Wichtigkeit.\n\nDonnerschrei hat sein Lager auf der anderen Seite des Abgrunds östlich von hier aufgeschlagen.", sourceObjective = "Tötet 4 Leutnants von Donnerschrei und nehmt Donnerschreis Helm an Euch, nachdem Ihr Karga Donnerschrei getötet habt.", progress = "Ist er tot? Habt Ihr seinen ... Helm?", completion = "<Tolliver greift ehrfürchtig mit zitternden Händen nach dem Helm.>\n\nDonnerschreis Kampfschiffe brachten unsere Schiffe auf, als wir aus Gilneas flohen. Wir sollten als Trophäen hierher zum Kriegshäuptling gebracht werden. Als wir uns der Küste näherten, haben sich einige von uns zur Wehr gesetzt. Donnerschrei begann, wahllos zu töten und brüllte vor Lachen. Unser Schiff kenterte und er befahl seinen Leuten, auf uns zu schießen, während wir ertrinkend im Wasser schwammen. Nur wenige von uns schafften es an Land.\n\nAnschließend fand ich heraus, dass er den Skalp meines Bruders als ... als Trophäe trug.\n\n<Er schließt seine Augen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24957] = { id = 24957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Centipaarty", description = "OK, Schätzchen. Wie gesagt, die Oger sind zu dumm, um zu wissen, was ihre Unterschrift bedeutet hat. Jetzt müssen wir sie dazu bringen, zu uns zu kommen, und das stellen wir mit Hilfe eines anscheinend in der Region sehr geliebten Geschmack an.\n\nZumindest von sabbernden Idioten sehr geliebt.\n\nBegebt Euch zum Giftigen Unterschlupf westlich von hier - eine große, schreckliche Grube voller gefährlicher Silithiden. Tötet ein paar der Centipaar und bringt mir ihre Stücke zurück, damit wir sie verteilen können, ja? Ciao.", sourceObjective = "Sammelt 20 Centipaartikel von Silithiden der Centipaar.", progress = "Habt Ihr genug? Ich glaube nicht, dass die Oger kleine Portionen mögen.", completion = "Uff, das ganze Lager riecht wie ein Grundkurs für schlimme Gerüche.\n\nWir sollten mit diesen Dingern nicht länger etwas zu tun haben als unbedingt sein muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[24958] = { id = 24958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volcanoth!", description = "Es hat viel Blut, Schweiß und Tränen gebraucht, aber die Schuhzooka, zum Patent angemeldet, ist einsatzbereit!\n\nDiese nichtsnutzigen Pygmäen verfüttern unsere Leute an ihren \"Gott\" Volcanoth und wollen ihn sogar auf unser Dorf loslassen!\n\nIhr müsst in seine Höhle gehen und das Ding töten, bevor es zu spät ist!", sourceObjective = "Benutzt die Schuhzooka, um Volcanoth zu töten.", completion = "Ich konnte alle sicher in die Stadt zurückbringen.\n\nSpringt auf! Wir müssen hier raus, bevor der Vulkan ein für alle Mal in die Luft geht!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24959] = { id = 24959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch aus dem Grab", description = "{name}!\n\nErhebt Euch, {name}!\n\nWillkommen zurück im Reich der Lebenden. Ich habe Euch mit dem Segen unserer Dunklen Fürstin aus der Umarmung des Todes befreit.\n\nIhr seid niemandes <Sklave/Sklavin>, {name}. Der Weg, den Ihr von hier aus einschlagt, ist ganz Eure Entscheidung. Wenn Ihr Euch dafür entscheidet, der Dunklen Fürstin Sylvanas zu dienen, empfehle ich Euch, mit Totengräber Mordo zu sprechen. Ihr könnt ihn hinter mir auf dem Friedhof finden.", sourceObjective = "Meldet Euch bei Totengräber Mordo an den Gräbern von Todesend in Tirisfal.", completion = "Hallo. Ihr seid sicher... {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24960] = { id = 24960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erwachen", description = "König, Bauer, oder {class}... mir ist egal, was Ihr früher wart. Ich brauche nur jemanden mit einer funktionstüchtigen Zunge.\n\nVon den Toten erweckt zu werden ist strapaziös. Nicht jeder steckt es so gut weg wie Ihr. Um zum Punkt zu kommen, es gibt drei frisch erweckte Untote, die sich schwer tun.\n\nIch möchte, dass Ihr sie aufsucht und mit ihnen sprecht. Vielleicht brauchen sie einfach nur jemanden, mit dem sie sich identifizieren können.\n\nIhr findet sie hier auf dem Friedhof.", sourceObjective = "Sprecht mit Marschall Rotpfad, Lilian Voss und Valdred Moray.", completion = "Ihr habt gute Arbeit geleistet, {class}. Wie Ihr sehen könnt, haben wir uns nicht alle unserem Schicksal ergeben. Ich bin froh zu sehen, dass Ihr wenigstens bereit seid, zu arbeiten.\n\nValdred wird den Verlassenen eine wertvolle Bereicherung sein. Was die anderen beiden angeht... nun, es gibt nicht viel, was wir da tun können. Wir können sie nicht zwingen, sich uns anzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24961] = { id = 24961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahrheit des Grabes", description = "Vorhin sah ich eine junge Verlassene, die um ihr Leben schreiend zum alten Gasthaus gelaufen ist, bittend, wieder nach Hause zurückkehren zu können.\n\nNicht alle sind so bestimmt wie die anderen, {name}. Und doch müssen wir unser Schicksal als Untote akzeptieren, wenn wir gegen jene vorgehen wollen, die uns unterdrücken wollen.\n\nNehmt meinen Handspiegel und zeigt ihn der jungen Frau. Sie muss sehen, was sie wirklich ist, und sich uns anschließen. Außerdem... wir können wirklich alles brauchen, was wir kriegen.", sourceObjective = "Macht Lilian Voss im großen Gasthaus von Todesend ausfindig und zeigt ihr Elreths Handspiegel.", completion = "Sie ist weggerannt? Eine Schande.\n\nNun gut. Sie hat noch ihren freien Willen, also gibt es auch noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[24962] = { id = 24962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die mitgenommene Schriftrolle", description = "Oh, während Ihr Euch mit der Geißel geschlagen habt, kam eine Schriftrolle für Euch an. Es scheint sich um eine wichtige Angelegenheit zu handeln; ich glaube, das Siegel ist das von Jägerlehrer Xavier. Nehmt Euch die Zeit, seine Nachricht zu lesen, bevor Ihr Euch auf den Weg macht.", sourceObjective = "Lest die mitgenommene Schriftrolle und sprecht mit Xavier dem Jäger in Todesend.", progress = "Ah, da seid Ihr ja. Gut. Ich habe mitbekommen, dass ein paar andere dem 'Tod' entkommen und in die Stadt geflüchtet sind. Vielleicht wird sich auch dieser Widerstand in der Zukunft auszahlen.\n\nIhr solltet Sylvanas für Eure Freiheit danken... Freiheit von Eurem Körper und Geist. Auch wenn Ihr weiterhin von der Seuche und ihren Auswirkungen befallen seid, so könnt Ihr Euch nun doch frei bewegen.", completion = "Ich werde hier sein, um Euch zu unterrichten, während Ihr Erfahrungen sammelt... Sucht mich auf, wann immer Euch danach ist. Ich verlange ein kleines Entgelt, aber Ihr werdet es für das Gelernte nicht bereuen.\n\nGeht nun und testet Eure Fähigkeiten. Je mehr Erfahrung Ihr sammelt, umso mehr Wissen wird sich Euch erschließen. Ich kann nicht alles mit Euch hier besprechen. Ihr solltet Euch jedoch darüber im Klaren sein, dass Sylvanas für Jäger mit Eurer Raffinesse auch zukünftig Bedarf hat.\n\nIhr werdet das Rückgrat unserer Rettung darstellen. Vergesst das nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24963] = { id = 24963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermalmt sie sanft", description = "OK, Schätzchen, hört mir zu. Es gibt immer zwei Wege, um andere dazu zu bringen, das zu tun, was man von ihnen möchte. Man kann Güter und Dienstleistungen anbieten, Sachen, die die Leute wollen... oder sie einfach richtig ordentlich verprügeln.\n\nIch finde es oft nützlich, beides zur gleichen Zeit zu machen und auch Ihr seid mit beiden Methoden schon gut vertraut. Nehmt diese Silithidhäppchen, schlagt ein paar Oger, bis sie Sternchen sehen, gebt ihnen die Häppchen und schlagt sie dann tot - in Ordnung?", sourceObjective = "Schwächt 8 Oger der Dünenbrecher und gebt ihnen dann die Werbedelikatesshäppchen des Bilgewasserkartells.", completion = "Gute Arbeit, jetzt habt Ihr den Ogern hier beigebracht, alles, was ansatzweise nach {race} aussieht zu fürchten und zu respektieren.\n\nFaszinierend, was eine kleine Belohnung anrichten kann, um Leute für einen arbeiten zu lassen, nicht wahr? Oh, hier ist auch Eure Bezahlung.\n\n...was soll dieser Blick?", sourceObjectiveStatus = "unverified-source-field" }
quests[24964] = { id = 24964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Jagdfieber", description = "Mir wurde gesagt, ich solle Euch die Fähigkeiten der Jäger lehren. Schön und gut, aber meiner Meinung nach lernt man in der Wildnis mehr als man jemals mit theoretischem Wissen erlernen könnte.\n\ngeht, sammelt Erfahrungen und seht, ob Ihr ein paar neue Tricks lernen könnt. Kommt dann zu mir zurück und zeigt sie mir.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen und übt die Fähigkeit 'Zuverlässiger Schuss' 5-mal an einer Trainingsattrappe.", completion = "Ihr scheint eine Art Begabung zu haben, {name}. Das ist gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[24965] = { id = 24965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magielehren", description = "Also, fangen wir mit der Arbeit an, ja?\n\nWenn Ihr an Macht gewinnt, wird sich Eure Verbindung zum Arkanen vertiefen und Ihr werdet Zugang zu neuen Zaubern und Fähigkeiten erhalten.\n\nIhr werdet es sehen. Geht, sammelt Erfahrungen, und kommt dann zurück und demonstriert mir, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen von Isabella in Todesend und übt die Fähigkeit 2-mal an einer Trainingsattrappe.", completion = "Erfreut Euch an Eurer neugefundenen Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24966] = { id = 24966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Licht und Schatten", description = "Priester der Verlassenen, mutige Biester;\nunübliche Wege schlägt <der Priester/die Priesterin> ein,\nSchattenriten - kein Licht - so muss <sein/ihr> Quell' finsterer sein.\n\nNicht nur die Welt hat uns verlassen, {name}... auch das Licht hat sich von uns abgewandt. Wie man aus dem kleinen Gedicht jedoch erkennen kann sind wir nicht ganz ohne Macht.\n\nGeht, sammelt mehr Erfahrungen, sammelt mehr Macht. Kehrt dann zu mir zurück und demonstriert mir, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Schattenwort. Schmerz' zu erlernen und übt die Fähigkeit 5-mal an Trainingsattrappen.", completion = "Ihr lernt schnell, {name}. Ihr werdet weit kommen. Wenn Ihr mehr erlernen möchtet, so kommt zu mir zurück. Ich werde Euch gerne mehr unterrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24967] = { id = 24967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stich!", description = "Leise! Ich will nicht, dass die Novizen hören, was wir hier besprechen.\n\nHört zu... {name}, nicht wahr? Ich habe eine Technik, die Eure Vorgehensweise als Schurke verändern kann. Ihr werdet Eure Angriffe mit einem tödlichen Abschluss verbessern können. Vielleicht Euren Dolch sogar zwischen die Wirbel des Gegners stechen.\n\nUm das zu lernen müsst Ihr nur ein bisschen Erfahrung sammeln. Keine Angst, das kriegt Ihr schon hin.", sourceObjective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen und übt die Fähigkeit 3-mal an einer Trainingsattrappe.", completion = "Ihr könnt mir glauben, das wird Euch mal den… das Leben retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24968] = { id = 24968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Taten", description = "Wenn Ihr Eurer Laufbahn als Hexenmeister folgt, werdet Ihr beginnen, die Stimmen der Teufelskraft zu hören… sie werden Euch ihre Geheimnisse offenbaren und Euch neue Zauber lehren.\n\nIch will sehen, dass Ihr einen Zauber erlernt und ihn an einer der Trainingsattrappen hier ausprobiert.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen und übt die Fähigkeit 5-mal an einer Trainingsattrappe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24969] = { id = 24969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Kampf stürmen", description = "Wenn Ihr ein stärkerer Krieger sein möchtet, so müsst Ihr Eure Waffen anpassen. Ihr werdet auf Euren Abenteuern viele stärkere Schwerter und größere Schilde finden, davon bin ich überzeugt.\n\nEs ist aber nicht nur die Rüstung, die stärker wird - Ihr werdet auch neue Techniken erlernen. Geht, sammelt Erfahrungen, erlernt etwas Neues und kommt dann zu mir zurück und zeigt es mir.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen und übt die Fähigkeit an einer Trainingsattrappe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24970] = { id = 24970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch nicht besser als die Zombies", description = "Während Ihr in der Höhle wart, ist Euer großer Freund Darnell vorbeigekommen und hat uns beunruhigende Nachrichten gebracht.\n\nSeit die Val'kyr angekommen sind, haben sich immer mehr Untote dagegen entschlossen, sich den Rängen unter dem Banner der Dunklen Fürstin anzuschließen. Sie haben sich in einem kleinen Lager hier im Tal versammelt und stellen eine Streitmacht auf.\n\nSie planen einen Angriff auf Todesend, {class}.\n\nDarnell ist nicht weit von hier, entlang der Straße, die nach Osten führt. Nehmt Euch in Acht, {name}. Zwar sind diese Untoten nicht völlig hirnlos, aber das heißt noch nicht, dass sie bei klarem Verstand sind.", sourceObjective = "Meldet Euch bei Darnell in Todesend in Tirisfal.", completion = "{name}. Ihr habt es geschafft.\n\nSeht Ihr die Zelte dort? Dorthin führt unser Weg. Die Schlacht hat wahrscheinlich schon begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24971] = { id = 24971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das Lager der Moderhirne", description = "Während Ihr Euch um Exekutor Arrens Aufträge gekümmert habt, habe ich selbst auch eine Aufgabe übernommen. Schattenpriester Sarvis hat mich gebeten, das Lager der Moderhirne zu erkunden.\n\nSie heißen nicht ohne Grund Moderhirne...\n\nIhr Anführer ist Marschall Rotpfad, ein absolutes Ungetüm.\n\nSeht, {name}... der Angriff hat begonnen. Ihr seid besser im Kampf als ich. Geht und helft unseren Truppen!\n\nWenn Ihr fertig seid, sucht Schattenpriester Sarvis in der Kapelle auf. Viel Glück, {name}.", sourceObjective = "Tötet Marschall Rotpfad und 8 untote Moderhirne.", completion = "Unter der Macht der Val'kyr wiedergeboren zu werden ist ein sehr aufreibender Prozess. Viele überleben den Schock nicht und werden zu Zombies oder Ghulen.\n\nAndere behalten etwas Menschliches bei und scheinen Außenstehenden ganz normal zu sein... und doch sind sie im Inneren erkrankt. Wir hätten die Moderhirne an dem Tag töten sollen, an dem sie wiedererweckt wurden.\n\nIhr... Ihr seid ein starker {class}, {name}. Ich wusste, dass Ihr Euch gut schlagen würdet. Ihr werdet Todesend bald verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24972] = { id = 24972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidende Informationen", description = "<Sarvis holt ein Stück Papier aus seiner Robe hervor.>\n\nDie hier müssen zu meinem Außenagenten, Todeswache Simmer gebracht werden. Diese Informationen betreffen den Aufenthaltsort der letzten verbleibenden Starrköpfe des Scharlachroten Kreuzzugs. Wir werden diese Kreuzzügler ein für alle Mal ausradieren. Und wenn mich mein Gefühl nicht täuscht, werdet Ihr eine Schlüsselrolle in unseren Bemühungen spielen, {name}.\n\nNehmt die Straße die nach Norden aus Todesend herausführt. Kurz nachdem Ihr nach Tirisfal hineinkommt, solltet Ihr auf ein großes Pfarrhaus treffen. Simmer sollte dort zu finden sein.", sourceObjective = "Bringt die Dokumente des Scharlachroten Kreuzzugs zu Todeswache Simmer auf dem Calstonanwesen in Tirisfal.", progress = "Ja, was wollt Ihr?", completion = "Ja, das ist sehr gut. Diese Informationen zu beschaffen, war gute Arbeit, {name}. Hmm... Die Namen der Offiziere des Scharlachroten Kreuzzuges in Tirisfal... \n\nStellt Euch nur vor, welchen Schlag wir der Moral dieser verfluchten Fanatiker verpassen könnten, wenn wir es schaffen, all ihre Anführer auf einen Schlag zu töten. Ich werde diese Informationen weiterleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24973] = { id = 24973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtweber", description = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.\n\nEs gibt eine Goldmine im Westen, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.\n\nBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, {name}.", sourceObjective = "Tötet 8 junge Nachtweber und 5 Nachtweber.", completion = "Hmm, nun ja, es ist ein Anfang. Es wird ein paar Wochen oder Monate dauern, das Ungeziefer gänzlich auszumerzen. Danach müssen wir mit ein paar Fackeln da runtergehen und die Netze niederbrennen.\n\nIhr habt Eure Pflicht gut erfüllt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24974] = { id = 24974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So schrecklich allein", description = "Da arbeitet man sein ganzes Leben lang, und was ist der Dank? Von einer Seuche dahingerafft. Dann arbeitet man als Untoter noch viel härter, und was ist der Dank? Geld, ja, ein kleines Zuhause mit ein paar Mitläufern, aber Glück? Nicht wirklich.\n\nIch werde auf meine alten Tage einsam, {name}. Ich brauche einen Gefährten. Benutzt diese Leine mit einem der Murlocs an der Flüsternden Küste im Nordwesten. Ihr müsst ihn wahrscheinlich erst schwächen, bevor er sich die Leine anlegen lässt. Bringt ihn dann zu mir.", sourceObjective = "Benutzt die Murlocleine an einem Finsterflossenmurloc an der Flüsternden Küste, dann kehrt mit ihm zu Sedrick Calston am Calstonanwesen zurück.", progress = "Oh, der Schmerz der Einsamkeit ist unerträglich!", completion = "Oh, seht ihn Euch nur an! Ist er nicht das niedlichste, was Ihr je gesehen habt? Ich danke Euch, {name}. Ich fühle mich schon viel energiegeladener.", sourceObjectiveStatus = "unverified-source-field" }
quests[24975] = { id = 24975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felder des Kummers", description = "Was haben wir denn hier? Ihr seht wie ein Neuling aus, {class}. Wenn Ihr darauf hofft, Euch der Dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.\n\nIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.\n\nSobald Ihr 10 beisammen habt, bringt sie zu mir.", sourceObjective = "Stehlt 10 Kürbisse von Sollidens Bauernhof in Tirisfal.", progress = "Habt Ihr bereits 10 Kürbisse gesammelt, {name}?", completion = "Ihr habt Eure Befehle gut ausgeführt, {class}. Ihr habt Euch als eine echte Hilfe für die Armee der Dunklen Fürstin erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24976] = { id = 24976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwechslung ist die Würze des Todes", description = "Diese Kürbisse erfüllen einen Zweck, {class}. Sie sind der Träger für meine neueste Seuche, die dieses Mal aus einer besonders schmerzvollen und ansteckenden Mischung besteht. Für die Seuche brauche ich jedoch einige sehr seltene Zutaten.\n\nWir brauchen Markblatt, das nur am Grund des Stillwassertümpels östlich von hier wächst. Außerdem noch Xavrens Dorn, das an den felsigen Klippen im Nordwesten zu finden ist. Und schließlich noch salzige Seegurken aus der Brandung an der Flüsternden Küste.", sourceObjective = "Besorgt 4 Markblätter, 4 Xavrens Dorn und 8 salzige Seegurken.", progress = "Das wird meine bisher beste Versuchsreihe. Ich habe es im Gefühl, mein lieber {class}.", completion = "Ausgezeichnete Arbeit, {name}. Und jetzt zum spaßigen Teil.", sourceObjectiveStatus = "unverified-source-field" }
quests[24977] = { id = 24977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Johaans Experiment", description = "Harmlose Kürbisse, ja? Wenigstens scheint es so. Wenn wir den Vormarsch der Geißel aus dem Norden und den Menschenbefall im Süden zurückschlagen wollen, müssen wir uns über die Möglichkeiten klar werden, die das Geschenk des Untot-Seins für uns bedeutet.\n\nMit ein wenig Einfallsreichtum kann aus einem einfachen Kürbis ein Mitarbeiter unserer Dunklen Fürstin werden. Dieser Kürbis wurde mit meiner neuesten Formel getränkt und wird sich als ziemlicher Leckerbissen erweisen.\n\nEin weiterer scharlachroter Zelot wurde gefangen genommen und wird draußen bei dem Pavillon gefangen gehalten. Bringt diesen Kürbis zu dem Narren.", sourceObjective = "Bringt den getränkten Kürbis zu dem gefangenen scharlachroten Zeloten beim Pavillon auf dem Calstonanwesen.", progress = "Bleibt weg von mir, grässliche, unheilige Kreatur! Möge das Licht mich beschützen! Der Scharlachrote Kreuzzug soll das Antlitz Azeroths von Euresgleichen...\n\n... Moment mal. Ist das Essen für mich? Ich habe solchen Hunger...", completion = "Dem Licht sei Dank! Endlich etwas zu essen! Süßer, süßer Kürbis...", sourceObjectiveStatus = "unverified-source-field" }
quests[24978] = { id = 24978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnitter der Ernter", description = "Menschen sind von Natur aus wankelmütige Kreaturen. Die Bauern im Westen bilden keine Ausnahme. Natürlich, im Moment scheinen sie friedlich ihre Felder zu pflügen, aber vielleicht erheben sie schon morgen ihre Sensen gegen uns. Die Allianz lauert in der Nähe, in Gilneas, und die Macht von Sturmwind im Süden... beide könnten diese Ackerbauern rekrutieren und sie wie einen Keil zwischen uns treiben.\n\nIch will, dass sie sterben. Sorgt dafür, dass das geschieht.", sourceObjective = "Tötet 10 Bauern von Tirisfal oder Landarbeiter von Tirisfal.", completion = "Ihr habt die Voraussetzungen, ein mächtiger {class} zu werden, {race}. Ich habe die Schreie dieser Menschen bis hierher gehört. Vielleicht sind wir diese Menschenplage bald los.", sourceObjectiveStatus = "unverified-source-field" }
quests[24979] = { id = 24979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Scharlachroter Brief", description = "Leutnant Gebler:\n\nWie seltsam, dass Ihr eine Gefangene gemacht habt... und dazu noch eine Untote. Was habt Ihr Euch dabei gedacht? Glaubt Ihr, dass sie nur wegen des ehemaligen Status über den Edikten des Scharlachroten Kreuzzugs stehen könnte?\n\nDas ist äußerst besorgniserregend, Gebler. Ich möchte Euch daran erinnern, dass solches Verhalten strafbar ist. Ich befehle Euch, die Gefangene sofort hinzurichten. Sie ist nicht mehr eine von uns.", sourceObjective = "Findet die Gefangene in der Scharlachroten Palisade.", progress = "Was steht darin?", completion = "Der Scharlachrote Kreuzzug macht keine Gefangenen. Dass sie es mit dieser jungen Frau tun... seltsam.\n\nDie Mächte, die Ihr beschreibt, sind noch seltsamer. Sie hat die Gitter ihres Gefängnisses durchquert und hat denjenigen, der sie gefangen genommen hat, getötet? Warum hat sie das nicht sofort getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[24980] = { id = 24980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Scharlachrote Palisade", description = "Wir brauchen jemanden mit \"Eigeninitiative\", um den Scharlachroten Kreuzzug ins Grab zu treiben. Jemanden wie Euch.\n\nBeweist mir, dass Ihr in der Lage seid, der Dunklen Fürstin zu dienen. Reist nach Westen zum Turm hinter Sollidens Bauernhof und erschlagt 10 Krieger des Scharlachroten Kreuzzugs.", sourceObjective = "Tötet 10 scharlachrote Krieger.", completion = "Ausgezeichnet, {class}. Eure Fähigkeiten in der Kampfkunst sind unbestreitbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24981] = { id = 24981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dorn in unserem Auge", description = "Informationen, die wir von Exekutor Arren in Todesend erhalten haben, enthalten alle nötigen Details, um die menschliche Plage aus diesen Landen zu tilgen. Laut dieser Informationen hat der Scharlachrote Kreuzzug Hauptmann Perrine und eine Brigade zum verfallenen Turm südwestlich von Brill versetzt.\n\nTötet 3 seiner Zeloten und 3 seiner Missionare. Und wenn Ihr schon da seid, seht zu, ob Ihr noch mehr Informationen über ihre Vorhaben herausfinden könnt.", sourceObjective = "Tötet 3 scharlachrote Zeloten und 3 scharlachrote Missionare und beschafft das dringende scharlachrote Memorandum.", progress = "Wir werden den Scharlachroten Kreuzzug wie Vieh ins Verderben treiben.", completion = "Hört sich an, als sollten wir nach dieser Voss Ausschau halten. Ich erwarte nicht, dass ein Verlassener für ihre Ergreifung eine Belohnung bekommen wird... ich befürchte nur, dass sie sich am Ende gegen uns wenden wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[24982] = { id = 24982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neuen Verlassenen", description = "Offen gesagt waren die Verlassenen früher ein Haufen schluchzender Jammerlappen. Wir haben uns in baufälligen Ruinen der Menschen verbarrikadiert, uns vor der Geißel versteckt, vor der Allianz verkrochen und am Rockzipfel der Horde gekatzbuckelt.\n\nDoch nun schaut Euch um und bewundert die neue Generation der Verlassenen. Wir haben uns hier in Azeroth einen Namen gemacht und dieser Name wird noch weiter wachsen. Schon bald wird unser Herrschaftsgebiet sich über die gesamte Welt erstrecken!\n\nWollt Ihr einen Rat? Sprecht mit Magistrat Sevren in Brill. Folgt einfach dieser Straße. Er leitet das Dorf.", sourceObjective = "Meldet Euch bei Magistrat Sevren in Brill in Tirisfal.", completion = "Ja, ich bin der Magistrat hier in Brill und direkt der Dunklen Fürstin unterstellt. Wenn Ihr es schafft, mich zu beeindrucken, begegnet Ihr der Bansheekönigin vielleicht eines Tages sogar selbst. Und jetzt zu Eurer ersten Aufgabe...", sourceObjectiveStatus = "unverified-source-field" }
quests[24983] = { id = 24983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlassenen-Pflichten", description = "Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.\n\nIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!\n\nReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.", sourceObjective = "Sprecht mit Todeswache Linnea bei der Wegstation Todeswacht in Tirisfal.", completion = "Magistrat Sevren will einen Bericht? Nun gut: Die Verteidiger auf dem Bollwerk halten den Großteil der Geißel in Schach, aber gelegentlich schlüpfen ein paar durch. \n\nWir haben sporadisch Aktivitäten der Geißel östlich dieses Postens gesichtet, und diese häufen sich um Balnirs Bauernhof.", sourceObjectiveStatus = "unverified-source-field" }
quests[24988] = { id = 24988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kälte des Todes", description = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer Dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.\n\nJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze bringen würdet, könnte ich mir eine Decke nähen. Helft mir, {name}, auf dass ich der Sache weiter dienen kann.", sourceObjective = "Sammelt fünf Nachtsaugerpelze.", progress = "Habt Ihr schon fünf Nachtsaugerpelze, {name}?", completion = "Ich weiß Eure Mühen zu schätzen, {name}. Möge Sylvanas Eure Tapferkeit eines Tages anerkennen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24989] = { id = 24989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Magistrat", description = "Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich Euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.", sourceObjective = "Kehrt zu Magistrat Sevren nach Brill zurück.", completion = "Es ist beunruhigend zu hören, dass die Geißel am Bollwerk vorbeischlüpft. Selbst jetzt noch greifen sie uns unaufhörlich an.\n\nAber wir werden nicht nachgeben. Der Lichkönig ist tot; niemand wird je wieder von uns Besitz ergreifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24990] = { id = 24990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzschlag der Schattenhunde", description = "Fürstin Sylvanas hat sich an das königliche Apothekarium gewandt. Sie hat uns aufgefordert, eine neue Seuche zu erfinden - eine Seuche, die tödlicher ist als jede Krankheit in Azeroth. Diese neue Krankheit wird den Untergang unserer Feinde - gleich, ob lebendig oder tot - herbeiführen.\n\nMeine Studien haben ergeben, dass Tierblut der Schlüssel sein könnte. Hier, füllt diese Phiolen mit Schattenhundblut, damit ich meine These testen kann.", sourceObjective = "Sammelt 5 Phiolen Schattenhundblut.", progress = "Habt Ihr das Schattenhundblut schon bekommen, {name}? Die Zeit verrinnt!", completion = "Ihr habt Eure Sache gut gemacht, {name}, und ich danke Euch für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24991] = { id = 24991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrens Schlupfwinkel", description = "Inzwischen ist Euch sicher schon aufgefallen, dass die Königliche Apothekervereinigung eine weit verbreitete Organisation ist. Wir nehmen unsere Seuchenalchemie ernst. Wir glauben, dass wir unsere Ziele schneller erreichen, je mehr unserer Agenten Experimente durchführen.\n\nEiner dieser Agenten geht seiner Arbeit in einem kleinen Lager nördlich von hier nach. Er heißt Jerrod, und er könnte einen Lehrling von Eurer... Statur brauchen.", sourceObjective = "Meldet Euch bei Apotheker Jerrod bei Garrens Schlupfwinkel in Tirisfal.", completion = "Holland? Ein Amateur. Man braucht kein zweistöckiges Apothekarium, um eine Seuche herzustellen... man braucht Liebe. Und vielleicht ein paar gute Assistenten.\n\nLasst mich Euch zeigen, wie man Seuchen WIRKLICH macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24992] = { id = 24992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Gilneas entflohen", description = "Wie Ihr Euch vorstellen könnt, ist ein streunender Worg in Tirisfal ein wichtiges Ereignis. Exekutor Zygand wäre daran sicher interessiert.", sourceObjective = "Berichtet Exekutor Zygand in Brill in Tirisfal von der Anwesenheit des Worgen.", completion = "Hm… ja, das ergibt Sinn. Die Worgen strömen nur so aus Gilneas heraus. Ich wusste, es wäre nur eine Frage der Zeit, bis sie hier in Tirisfal ankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24993] = { id = 24993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Worgen", description = "Wir müssen uns um diese Worgen kümmern, und zwar schnell. Unsere oberste Priorität besteht darin, alle Worgen auszulöschen, die in Brill eingedrungen sind.\n\nIch möchte, dass Ihr hier in Brill nach verdächtigen Vorkommnissen Ausschau haltet, {name}. Wir wissen, dass diese Worgen sich in den Schatten verstecken können, also achtet auf jedes noch so kleine Zeichen... Fußspuren, umgedrehte Steine, alles!", sourceObjective = "Findet und tötet 5 Spitzel der Worgen in Brill.", completion = "Und die ganze Zeit waren sie direkt vor unserer Nase! Kaum auszudenken! Ich werde meine Todeswachen alarmieren. So etwas passiert uns ganz sicher NICHT wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[24994] = { id = 24994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammniskraut", description = "Mein Abgesandter hat mir gerade einen Scheffel Düsterkraut geliefert. Düsterkraut! Ich brauche kein Düsterkraut, ich brauche Verdammniskraut! Ihr könnt die Bedrängnis, in der ich mich befinde, bestimmt nachvollziehen, {name}.\n\nEs soll Euer Schaden nicht sein, wenn Ihr mir beschafft, was ich benötige. Bringt mir Verdammniskraut in ausreichenden Mengen und ich werde Euch angemessen belohnen.\n\nSoweit ich weiß, verseucht es gerne die Flora in der Nähe des Massengrabs nördlich des Friedhofs von Brill. Eilt Euch und vergesst nicht, dass sich in der Gegend dort Gnolle befinden.", sourceObjective = "Sammelt 10 Verdammniskraut.", progress = "<Der Apotheker murmelt etwas zu sich selbst.>\n\nSie haben mir Düsterkraut gebracht? DÜSTERKRAUT?!", completion = "Ah, mein Verdammniskraut. Ausgezeichnet!\n\n<Apotheker Jerrod reibt sich gierig die Hände.>\n\nDas wird mir sehr nützlich sein. Ihr habt mir, äh, der Fürstin heute einen guten Dienst erwiesen, {name}. Wie versprochen ist hier Eure wohlverdiente Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[24995] = { id = 24995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Schuppen von den Augen", description = "Während Ihr Proben für mich gesammelt habt, ist mir durch meine Experimente schlagartig klargeworden, dass mehr Reagenzien nötig sein werden, damit sich diese Krankheit gut verbreiten kann. Ein hilfloses Opfer zu vergiften ist ein Kinderspiel. Eine ganze Welt zu verseuchen ist etwas komplizierter.\n\nIch brauche mehrere Schuppen von den Murlocs aus der Nähe. Ihr werdet diese Kreaturen dabei finden, wie sie hirnlos die Küste im Norden entlangwandern.", sourceObjective = "Beschafft 5 Finsterflossenschuppen.", progress = "{name}, habt Ihr die Schuppen von den Murlocs bekommen?", completion = "Die Schuppen sind perfekt, {name}. Genau das, was ich für dieses Gebräu brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[24996] = { id = 24996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hollands Experiment", description = "Wenn ich das richtig verstanden habe, hat sich noch einer dieser törichten Zwergengebirgsjäger einfangen lassen. Die Todeswache hat ihn hier in diesem Gebäude untergebracht und sie haben einen der ihren damit beauftragt, ihn davon zu überzeugen, dass er nicht fliehen sollte.\n\nWarum geht Ihr nicht und probiert, wie dem gefangenen Gebirgsjäger dieses Spezialgetränk, das ich für ihn zubereitet habe, schmeckt? Es beinhaltet einen dezenten Hinweis darauf, was die Dunkle Fürstin für ganz Azeroth im Sinn hat.", sourceObjective = "Bringt Hollands Spezialgetränk zu dem gefangenen Gebirgsjäger.", progress = "Wenn ich mein getreues Gewehr bei mir hätte, wärt Ihr so gut wie tot, {class}. Wartet nur, bis die Dampfpanzerbrigade hier anrückt, um mich zu befreien!", completion = "Ah, endlich etwas zu trinken. Was für ein Bier ist das? Ich bin sicher, dass es kein Rhapsodiemalz ist, aber jetzt gerade nehme ich alles, um die alte Kehle anzufeuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24997] = { id = 24997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabräuber", description = "Die Massengräber im Wald im Westen wurden ausgehoben, um die... beeindruckende... Zahl der Toten aufzunehmen, die Tirisfal zu beklagen hatte, als die Seuche zum ersten Mal auftrat.\n\nDen Leichen in diesen Gräbern ist der Untod bis jetzt erspart geblieben, aber die Geißel sendet jetzt schon Moderfellgnolle, um die Leichen zu sammeln und sie zur Aufstocken ihrer Streitkräfte zu benutzen. Das dürfen wir nicht zulassen!\n\nEure Aufgabe beinhaltet zweierlei: Tötet die Moderfelle beim Massengrab und bei Garrens Schlupfwinkel, und nehmt ihnen das Einbalsamierungssekret ab, das ihnen Leben verleiht.", sourceObjective = "Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle und sammelt 6 Fläschchen voll Einbalsamierungssekreten.", progress = "Ist Eure Aufgabe abgeschlossen? Habt Ihr diese Hundeviecher vernichtet und sie ihres Sekrets beraubt?", completion = "Meisterlich erledigt, {name}. Die Geißel irrt sich, wenn sie denkt, dass sie diese Leichen gegen uns verwenden könnte und die Flüssigkeit, die Ihr von den Moderfellsklaven gesammelt habt, wird von unseren Apothekern untersucht werden. Vielleicht enthält sie Geheimnisse, die wir gegen sie verwenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[24998] = { id = 24998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Madenauge", description = "Madenauge ist ein widerliches Ungeheuer - sogar nach Gnollmaßstäben. Er führt eine Bande abtrünniger Gnolle durch die Lande, zerfetzt alles in Tirisfal und stiehlt alle Leichen, die er unterwegs findet.\n\nDas sind unsere Leichen! Wir hatten Pläne damit!\n\nFolgt dem Pfad ein Stück hinauf, dort hält sich Madenauge für gewöhnlich auf. Erweist ihm keine Gnade. Gnade ist für Schwächlinge.", sourceObjective = "Tötet Madenauge und erbeutet seine Tatze.", progress = "Ja?", completion = "Ausgezeichnete Arbeit! Jetzt muss ich nur noch Jerrod davon überzeugen, unsere Operation in diese Hütte zu verlegen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24999] = { id = 24999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saat der Furcht pflanzen", description = "Sieht aus, als ließe Euch Jerrod die Murlocs im Norden jagen. Das ist gut... wir können ihre Bestandteile benutzen, um unsere Gifte herzustellen. Manchmal mache ich mir allerdings Sorgen...\n\nDie Laichgründe der Finsterflossenmurlocs sind nicht weit von der nördlichen Küste Tirisfals entfernt, also werdet ihr wahrscheinlich mehrere Kaulquappen zwischen den ausgewachsenen Tieren am Strand finden. Wenn diese leicht zu beeindruckenden jungen Murlocs sich eines Tages rächen würden... so etwas könnte uns ruinieren. Geht und jagt sie, und zeigt ihnen, dass mit den Verlassenen und der Horde nicht zu spaßen ist.", sourceObjective = "Jagt 12 Kaulquappen der Finsterflossen, bis sie vor Angst ohnmächtig werden.", completion = "Sind sie vor Euch weggelaufen, {name}? Gut. Das ist besser, als sie zu töten... wenn sie überleben, um davon zu erzählen, lernen zukünftige Generationen von Murlocs, uns zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25000] = { id = 25000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegans Leute", description = "He, {class}!\n\nSeid Ihr unterwegs, um Korporal Teegan zu unterstützen? Er ist dafür verantwortlich, dass die Nachschubrouten offen bleiben.\n\nEr hat zwei der widerspenstigsten Zwerge, die ich je gesehen habe, als Verantwortliche für Verschiedenes eingesetzt. Wenn Ihr auf diese beiden schrulligen Jäger Eindruck machen wollt, müsst Ihr zeigen, dass Ihr Euch gegen die Raubtiere hier in der Gegend behaupten könnt.\n\nDie Raptoren westlich der Burg sind besonders bösartig. Bringt Goucho einige frische Bälge und Ihr werdet mit einem Schlag sowohl Eindruck schinden, als auch die Truppen versorgen.", sourceObjective = "Tötet Schreckenszahnläufer und Schreckenszahnsensenklauen, um 8 Schreckenszahnbälge zu erhalten.", progress = "Worum geht es, {class}? Das Lager hier ist nicht geeignet für Besichtigungstouren.", completion = "Hey, Ihr seid zäher, als Ihr ausseht. Diese Schreckenszahnbälge wehren Pfeile ab und lassen Axtklingen abprallen - die Raptoren sind nicht leicht zu besiegen, aber ihre Bälge sollte man in diesem vom Licht verlassenen Brachland mit Silber aufwiegen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25001] = { id = 25001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandscharrer", description = "Meine anderen Assistenten kümmern sich darum, unsere stolzen neuen Kameraden in ihre gemütlichen Käfige zu bringen und sie dorthin zu befördern, wo sie am meisten gebraucht werden. Für die Horde. In der Zwischenzeit können wir uns um einen weiteren letzten Punkt auf meiner Agenda kümmern.\n\nSandscharrer, der Häuptling der Dünenbrecher, ist wahrscheinlich zu dumm, um zu merken, was wir hier tun. Aber ich mag es nicht, wenn man Sachen nicht komplett abschließt, Schätzchen. Er ist in dem Bau westlich von hier, nicht weit entfernt. Macht Euch die Hände schmutzig, macht ihn fertig und dann ist auch dieser Teil als abgeschlossen anzusehen, OK?", sourceObjective = "Tötet Sandscharrer.", completion = "Und damit sind wir fertig! Hier gibt es nichts mehr für uns zu tun. Gute Arbeit, Schätzchen.\n\nObwohl, vielleicht bin ich zu übereilig. Habt Ihr im Bau der Oger etwas gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25002] = { id = 25002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute", description = "<Ihr entdeckt eine Ladeliste bei der Leiche, die eine lange Liste verschiedener, dringend an der Front benötigter Kleinteile aufzählt.>\n\n<Eine blutige Spur im Schmutz zeigt, dass Leichen von hier aus nach Süden in die Richtung der Raptorennester gezerrt wurden.>\n\n<Die Raptoren haben möglicherweise auch die Vorräte weggeschleppt. Diese Vorräte für Korporal Teegan wiederzuholen könnte dabei helfen, dieses Unglück zu mildern!>", sourceObjective = "Holt 10 Vorratskisten der Nordwacht aus dem Raptorennest heraus.", progress = "Wie bitte? Meine Versorgungskarawane wurde von diesen kaltblütigen Scherenpfotendingern ausgeraubt?", completion = "Meine Vorräte! Also das zeigt ja echte Eigeninitiative, {class}. Diese Rapsägen, oder wie die heißen, haben schon ganz andere Männer zu Hackfleisch zerschnippelt. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[25003] = { id = 25003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familiengruft", description = "Der stärkste Punkt der Mühlen ist die Gruft der Familie Agamand. Hauptmann Dargol hat die Urahnen der Agamands mit Nekromantie auferstehen lassen und will sie gegen uns verwenden.\n\nDas darf nicht geschehen, und Ihr müsst ihn aufhalten. Reist zur Gruft der Familie Agamand und besiegt die wiedererweckten Ahnen der Agamands.", sourceObjective = "Tötet 5 klagende Vorfahrinnen und 5 faulende Vorfahren.", completion = "Eure Taten haben der Geißel einen Schlag versetzt. Und Euer Sieg wird nicht unbeachtet bleiben - weder von den Verlassenen noch von unseren Feinden.\n\nFührt den Kampf fort, so wie wir alle, {name}, und eines Tages werden die Verlassenen die Herrschaft über Azeroth haben, wie es ihnen gebührt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25004] = { id = 25004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die überrannte Mühle", description = "Die Geißel versucht, hier bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.\n\nEs wurden klare Befehle erteilt. Die Diener der Geißel bei den Mühlen müssen vernichtet werden.\n\nSammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.", sourceObjective = "Sammelt 5 schartige Rippen und 3 geschwärzte Schädel.", progress = "Unser Krieg gegen die Geißel dauert noch immer an, {name}. Tut das Eurige und werft diese verfluchten, hirnlosen Untoten wieder zurück in die Pestländer!", completion = "Eure Bemühungen wissen wir zu schätzen, {name}. Ich werde Euch nicht dafür danken, dass Ihr das Notwendige getan habt, aber ich werde mir Euren Namen merken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25005] = { id = 25005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Sevren", description = "Ich habe die Überreste zerstört, die Ihr mir gegeben habt, {name}. Das heißt alle bis auf diese...\n\nDevlin Agamand war in seinem Leben schwach und scharfzüngig und war einer der ersten, die der Seuche zum Opfer fielen. Er lebte lange als Sklave der Geißel, länger als die Meisten. Daher hat er möglicherweise Wissen, das für uns wertvoll wäre.\n\nBringt seine Überreste zu Magistrat Sevren, und sagt ihm, was ich Euch gesagt habe. Er wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Magistrat Sevren in Brill in Tirisfal.", progress = "Der Gestank des Untodes umgibt Euch, {name}. Was ist Euer Begehr?", completion = "Devlin Agamand? Ist es er, den Ihr da in Eurem Sack tragt? Ha!\n\nJa, ich weiß, was Coleman versuchen möchte, und das möchte ich auch. Ich hoffe, Ihr seid vorbereitet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25006] = { id = 25006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Griff lockert sich", description = "Während der Frostthron schlummert, wird die Kontrolle, die der Lichkönig einst über die Geißel hatte immer schwächer. Sein Einfluss auf einen Schwächling wie Devlin Agamand sollte gering genug sein, um ihn ganz auszuschalten.\n\nSprecht mit Schattenpriesterin Malia im Haus auf der östlichen Seite der Stadt. Sie wird Euch dabei helfen.", sourceObjective = "Sprecht mit Schattenpriesterin Malia in Brill und nehmt an der Extrahierung von Devlin Agamand teil.", progress = "Was habt Ihr herausgefunden?", completion = "Oh, wie schade. Vielleicht ist die Herrschaft der Geißel über Devlins Geist doch zu stark geblieben. Oder vielleicht waren unsere Methoden nicht stark genug. Es ist auch möglich, dass Devlin einfach zu einfältig war, um zu begreifen, was wir von ihm wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25007] = { id = 25007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Osten... Stets nach Osten", description = "Ihr habt so viel für uns hier getan, {name}, doch <Männer/Frauen> von Eurem Kaliber werden anderswo benötigt.\n\nIm Osten liegt das Bollwerk: eine verstärkte Barrikade gegen die Verheerer der Pestländer. Das Bollwerk schützt uns vor dem Einmarsch der Geißel und ermöglicht uns eine Zuflucht, in der wir unsere Streitkräfte hier in Tirisfal aufbauen können.\n\nGeht und sprecht mit Hochexekutor Derrington. Er ist ein Verbündeter und wird zweifellos jede Hilfe, die Ihr ihm anbieten könnt, zu schätzen wissen.", sourceObjective = "Meldet Euch bei Hochexekutor Derrington am Bollwerk in Tirisfal.", completion = "<Der Hochexekutor mustert Euch abschätzend.>\n\nIhr seid kein wirklich beachtlicher {class}, was? Nun ja, wenn ich mit Euch fertig bin, wird das anders sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25008] = { id = 25008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Tiere", description = "Ihr habt wahrscheinlich den Geruch von diesen Fleischreißerstrauchdieben auf dem Weg hierher aufgenommen - die stinken schlimmer als der Schwarze Peter hier. Wertlose Tiere! Sie schnappen uns unsere Beute vor der Nase weg, durchwühlen unsere Vorräte und was noch schlimmer ist... man kann sie nicht essen.\n\nGeht und tötet einige von ihnen.\n\nDann tötet noch ein paar mehr, wenn Ihr Lust habt.", sourceObjective = "Tötet 6 Fleischreißerstrauchdiebe.", completion = "Ooooo-oooooh, ja! Die besten Fleischreißer sind tote Fleischreißer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25009] = { id = 25009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Obwohl die Macht des Scharlachroten Kreuzzugs nachlässt, befinden wir uns noch immer im Krieg. Der Bericht, den Exekutor Arren geschickt hat, deutet darauf hin, dass Scharlachrote Kreuzfahrer vom verfallenen Turm im Südosten von Tirisfal in der Nähe von Balnirs Bauernhof aus angreifen. Sie werden von Hauptmann Vachon angeführt.\n\nTötet 3 seiner Zeloten und 4 seiner Ordensmitglieder. Das sollte dem Kreuzzug einen vernichtenden Schlag versetzen.", sourceObjective = "Tötet 3 Scharlachrote Zeloten und 4 Scharlachrote Ordensmitglieder.", completion = "Eure Taten werden das Vorrücken des Scharlachroten Kreuzzugs in Tirisfal erheblich verlangsamen... hoffentlich für immer. Doch andere Bedrohungen lauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25010] = { id = 25010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tödlicher neuer Verbündeter", description = "Kurz bevor Ihr am Bollwerk eingetroffen seid, hat sich eine höchst ungewöhnliche junge Untote bei mir gemeldet. Sie schwor dem Scharlachroten Kreuzzug ewige Feindschaft, also habe ich sie zur Arbeit gegen unsere Feinde im Norden geschickt. Ihr sagtet, Ihr hättet vor Kurzem tote Kreuzfahrer gesehen? Das war wahrscheinlich ihr Werk.\n\nGeht und seht nach ihr, und findet heraus, ob sie bei ihrem Rachefeldzug gegen den Kreuzzug Hilfe brauchen kann... obwohl es mich nicht überraschen würde, wenn sie schon alle getötet hätte.", sourceObjective = "Findet Euren neuen Verbündeten in der Scharlachroten Lagerstatt in Tirisfal.", completion = "Als Ihr die Ruinen des Lagers betrachtet, hört Ihr ein Flüstern hinter Euch.\n\n<\"Ich könnte Euch jetzt sofort töten, wenn ich wollte. Passt besser auf Euch auf, {race}.\">", sourceObjectiveStatus = "unverified-source-field" }
quests[25011] = { id = 25011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zu besseren und größeren Taten", description = "Hier auf dem Bollwerk gibt es keinen Ruhm mehr für Euch zu erringen, {name}. Ihr habt schon genug getan. Möglicherweise warten jedoch im Silberwald neue Abenteuer auf Euch.\n\nSprecht mit meinem Fledermausführer, Timothy Cunningham. Er wird Euch kostenlos nach Brill fliegen.", sourceObjective = "Sprecht mit Timothy Cunningham am Bollwerk in Tirisfal.", completion = "Klar könnt Ihr einen Flug nehmen. Wenn Hochexekutor Derrington darum bittet, habe ich ja auch eigentlich keine andere Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[25012] = { id = 25012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingt Euch in die Lüfte", description = "Wenn Ihr auf dem Rückweg nach Brill seid, solltet Ihr unterwegs bei Exekutor Zygand vorbeischauen. Ich habe gehört, dass es im Silberwald im Süden irgendeine Art Aufruhr gibt. Er weiß sicher mehr als ich.\n\nSprecht noch einmal mit mir, wenn Ihr bereit seid, abzureisen.", sourceObjective = "Sprecht mit Exekutor Zygand in Brill in Tirisfal.", completion = "Willkommen zurück, {name}. Ich habe Geschichten aus dem Osten gehört. Wer hätte gedacht, dass ein junger {race} wie Ihr die letzten winselnden Reste des Scharlachroten Kreuzzugs ausmerzen würde?", sourceObjectiveStatus = "unverified-source-field" }
quests[25013] = { id = 25013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Pep", description = "<Zitters probiert sein frisches Gebräu.>\n\nHmm... das ist nicht ganz fertig. Es braucht noch etwas, das ihm etwas mehr Pep verleiht. Ich hab's! Die Spinnen im Norden haben ein starkes Gift, das genau richtig sein sollte. Schaut Ihr mal nach, ob Ihr mir etwas davon extrahieren könnt, {name}?", sourceObjective = "Beschafft 4 Proben von heimtückischem Nachtweberspinnengift.", progress = "Habt Ihr etwas Gift von einer heimtückischen Nachtweberspinne, {name}? Es ist die letzte Komponente die ich brauche, um mein Experiment auszuprobieren.", completion = "Ah, dieses Gift wird perfekt, {name}. Alles andere ist zu meinem Gebräu hinzugefügt und verkocht worden. Danke, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25014] = { id = 25014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandscharrers Schatz", description = "In dieser verwitterten Steintruhe im hinteren Teil von Sandscharrers Hort findet Ihr ein erstaunliches Artefakt.\n\nEs ist wie ein Käfer geformt, hat eine glatte Oberfläche aus wunderbarem Blau mit goldenen Streifen. Es sieht mechanisch aus, aber nicht wie etwas, das Ihr bisher von den Händen Sterblicher hergestellt gesehen habt - und es sieht sehr alt aus.\n\nMegs wird sich sicherlich dafür interessieren.", sourceObjective = "Sprecht mit Megs Schredderschreck.", progress = "Ihr habt etwas gefunden?", completion = "Das habt Ihr im Ogerbau gefunden? Das...\n\n...ist nichts, um aufgeregt zu werden, sicherlich! Sicherlich ist das nur... ein ganz harmloses Schmuckstück... und ich kann Euch genau sagen, was Ihr damit zu tun habt.\n\n<Megs fängt an zu flüstern.>\n\nSeid leise und wedelt mit dem Ding nicht so in der Luft herum.", sourceObjectiveStatus = "unverified-source-field" }
quests[25015] = { id = 25015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie quieken", description = "Eine der heimischen Arten in Kalimdor sind die \"Stacheleber\". Stachlige kleine Nervensägen. Grund genug, diesen Kontinent zu hassen.\n\nDie Überfälle begannen kurz, nachdem wir unsere ersten Lager aufgeschlagen hatten. Schlimmer noch, diese stachligen Unholde scheinen in diesem dornigen Höllendschungel richtig aufzublühen. Ich brauche Eure Hilfe, um sie zurückzuschlagen, damit wir wieder Verbindung zum Gefechtsstand herstellen können.\n\nWährend Ihr da draußen seid, bringt einen dieser verdrehten Zweige an Euch, die ihre Zauberer offensichtlich dazu benutzen, um diesen Dschungelwuchs zu manipulieren...", sourceObjective = "Tötet insgesamt 8 Klingenwächter der Borstennacken oder Deviatdornweber und findet einen Dornstab von einem der Dornweber.", progress = "Ich sollte noch erwähnen, dass Ihr wahrscheinlich eine Machete benötigt, um Euch durch dieses Chaos einen Weg zu bahnen.\n\nDieser Dschungel kam aus dem Nichts!", completion = "<Korporal Teegan nickt, während Ihr ihm Bericht erstattet, dann umklammert er den Dornenstab mit beiden Händen.>\n\nAlso das hier verwenden die Stacheleber gegen uns? Glaubt Ihr, dass sie diese Stäbe benutzt haben, um diesen Dschungel zu erschaffen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25017] = { id = 25017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Hindernisse", description = "Seit Jahren wurde dieses Tal durch ein undurchdringbares Tor verschlossen. Das Tor wurde durch den Kataklysmus zerstört und nun ist es an uns, all die Geheimnisse des Tals zu erforschen.\n\nUnd doch stehen uns noch immer Hindernisse im Weg. Die vor Urzeiten von den Titanen hinter dem Tor erschaffenen Kreaturen sind zum Leben erwacht. Sie laufen ohne Ziel im Sand umher und greifen alles an, was ihnen in die Nähe kommt.\n\nJemand muss die Golems ausschalten, die im Tal patrouillieren. Was haltet Ihr davon?", sourceObjective = "Zerstört 6 Sandsteingolems.", completion = "Ich danke Euch, {class}. Ohne Eure Hilfe würden wir nicht mit solchen Feinden umzugehen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25018] = { id = 25018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andoren wird es wissen", description = "Hört gut zu, {name}. Ich weiß nicht, wie die Oger dieses Artefakt in die Hände bekommen haben; es handelt sich wirklich um ein Werk der Titanen. Ich bin zwar kein Experte, aber diese Tatsache allein macht das Ding wohl älter als den Sand, auf dem wir stehen.\n\nIch weiß auch, dass solche Dinge meistens Ärger hervorrufen. Ich will damit nichts zu tun haben. Reist nach Süden ins Tal der Behüter und gebt es dem Blutelfen Andoren Morgendunst. Und bitte stellt keine Fragen, Schätzchen.", sourceObjective = "Bringt das Artefakt zu Andoren Morgendunst im Tal der Behüter.", completion = "Ihr habt es... ausgerechnet in einem Ogerbau gefunden? Undenkbar. Es wundert mich, dass sie nicht versucht haben, es in Stücke zu zertrümmern.\n\nMit ein wenig Glück, {class}, werden wir hier noch weitere faszinierende Antiquitäten wie diese finden... wenn Ihr uns helfen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25019] = { id = 25019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anspruch erheben", description = "Nicht nur wir haben den Wert der Südmondruinen verstanden. Die Zwerge der Forscherliga sind bereits dort eingefallen und sammeln Artefakte und Inschriften für die Allianz.\n\nIch glaube, sehr viel mehr muss ich dazu nicht sagen. Wir werden nicht zulassen, dass ihre Funde in die Hände der Allianz fallen. Tötet so viele Zwerge, wie Ihr könnt und vertreibt sie aus den Ruinen.", sourceObjective = "Tötet 10 Archäologen der Zwerge.", completion = "Ausgezeichnet. Je weniger Störungen wir durch die Allianz erwarten können, um so besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[25020] = { id = 25020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprachfragmente", description = "Wir haben in den Südmondruinen östlich von hier ein paar interessante Funde gemacht. Meine Kollegen haben Steintafeln mit uralter Schrift gefunden, die durch die Sandstürme freigelegt wurden.\n\nDie Schrift ist in keiner uns bekannten Sprache verfasst, allerdings ähnelt sie den Markierungen der Ruinen der Titanen in manchen Aspekten. Wenn wir die Schrift entziffern könnten, so würde dies bestimmt viele Geheimnisse zu Tage bringen.\n\nLeider sind meine Kollegen damit beschäftigt, die Steintafeln vor der Allianz zu verteidigen. Begebt Euch zu den Südmondruinen und holt Euch die Tafeln.", sourceObjective = "Sammelt 5 uralte Hieroglyphen.", progress = "Habt Ihr die Hieroglyphentafeln?", completion = "Ich danke Euch, {name}. Nun können wir unsere Aufmerksamkeit ganz der Erforschung des Tors widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25021] = { id = 25021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut zum Blühen", description = "Um in der harten Wüste zu überleben, musst'n die Sandwüter die Geheimnisse der Blutmagie erlern'n. Blut trink'n, um Macht zu krieg'n... dunkles Voodoo, ja? Nich' schön, aber hier draußen hab'n wir ja nix voreinander zu verberg'n, oder?\n\nWenn wir das Schwert find'n woll'n, brauch'n wir Blut. Ihr habt Glück, dass Mazoga Verräter is', ja? Und viele Trolle der Sandwüter sind hier auf den Hügeln.\n\nHolt Euch Blut für Mazoga... viel Blut... und wir mach'n Ritual, um Jang'thraze zu find'n.", sourceObjective = "Sammelt 6 Handvoll Blut von Trollen der Sandwüter.", progress = "Ihr habt aber nix davon getrunk'n oder? Ich brauch das alles noch...", completion = "<Mazoga hält das getrocknete Blut in seinen Händen und führt es zu seinem Mund, um zu trinken. Es wird flüssig und fließt schmierig seinen Rachen herunter.>\n\nSie trink'n Blut, sie werd'n mächtig. Ich trinke ihr Blut...\n\n<Mazoga lächelt ein großes, blutverschmiertes Lächeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25022] = { id = 25022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlkommunikation", description = "Ich habe ihm gesagt, dass er ein Narr ist, aber Botschafter Gaines bestand darauf, dass er mit den Stachelebern eine Allianz gegen die Horde aushandeln könnte. Selbst wenn ihm das gelungen wäre - ich für meinen Teil hätte nicht mit diesen... Schweinekerlen an meiner Seite kämpfen wollen.\n\nNun, Gaines ist nicht zurückgekehrt und General Hawthorne wird mich zur Rechenschaft ziehen, wenn ich einen unserer besten Unterhändler an diese quiekenden Unholde verliere.\n\nFindet den Botschafter in diesem dampfenden Dschungelchaos und rettet ihn, wenn er noch am Leben ist.", sourceObjective = "Rettet Botschafter Gaines von den Stachelebern in der Überwucherung.", completion = "Gute Arbeit! Gaines ist vor nicht allzu langer Zeit hier auf seinem Weg nach Nordwacht und zu einem warmen Bad vorbeigekommen\n\nDie Mission war allerdings kein völliger Verlust. Wir haben ziemlich viel über diese Stacheleber und ihre Führungsstrukturen gelernt.\n\nJetzt können wir mit den Dingen... auf MEINE Art umgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25023] = { id = 25023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Freunde", description = "In Ordnung, dann haltet Euch mal an der Leiter fest. Wir müssen raus hier!\n\nWir machen einen kurzen Zwischenstopp in der Stadt und dann bringe ich Euch zu ein paar alten Freunden!", sourceObjective = "Sprecht mit Thrall am Spähposten des Kriegshäuptlings auf den Verlorenen Inseln.", completion = "Ich habe Euch doch gesagt, dass wir uns wiedertreffen würden, {name}.\n\n\n\nSchade, dass es unter diesen Umständen sein muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25024] = { id = 25024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertreibt die Fallschirmjäger", description = "Die Allianz hat uns genau zum falschen Zeitpunkt eingeholt, mein Freund. Wir haben uns zwar um ihre Schiffe gekümmert, aber sie haben immer noch ihre Flugzeuge und werfen ihre berühmte 127. Gebirgsjägerstaffel an der Küste ab.\n\nUnsere Kriegshetzer und Späher schaffen es kaum noch, die beiden Rampen gegen ihre überwältigende Zahl zu verteidigen. Aber wenn Ihr ihnen helft, wird das Schicksal sich sicher ganz schnell wenden!", sourceObjective = "Tötet 10 Fallschirmjäger der Allianz.", completion = "Nie hat ein {class} besser gekämpft!", sourceObjectiveStatus = "unverified-source-field" }
quests[25025] = { id = 25025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sang'thraze der Schmetterer", description = "Das Blut spricht. Ich spüre seinen Fluss im Sand... durchzog'n von Tod, eine Wüste des Leidens...\n\n<Mazogas Augen verdrehen sich.>\n\nDa! Das Blut fließt nach Süd'n, in ein Tal der Knochen. Zakkaru! Zakkaru, Brut von Makkari, dem Dunklen, der ein Opfer verlangt... sein Vater wurde aus Zul'Farrak verdrängt und sein Aufstieg verhindert... er wird noch einmal Blut schmeck'n...\n\n<Mazoga schwankt.>\n\nGeht, {class}. Zakkaru hat Sang'thraze. Ihr wollt nich', dass er es behält, glaubt mir.", sourceObjective = "Besiegt Zakkaru und erhaltet das versiegelte Sang'thraze.", progress = "Hab'n die Geister die Wahrheit gesagt, Mann? Habt Ihr's?", completion = "<Mazoga grinst, als er Euch das Schwert mit beiden Händen abnimmt.>\n\nHat Euch nich' besonders gemocht, hm? Nicht nur Trolle woll'n in dieser Welt Blut, Mann.\n\nLasst uns die andere Klinge find'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[25026] = { id = 25026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelstes Mojo", description = "Jang'thraze entzieht sich mir, Mann... das Blut war nich' genug. Wir müssen an etwas Stärkeres rankomm'n, um es zu find'n.\n\nWenn man jed'n Troll braucht, um über die Runden zu komm'n, dann ist ein toter Troll ein echtes Problem und deshalb hab'n die Sandwüter gelernt, wie man die Toten mit Voodoo wiederbelebt. Man fällt um, steht wieder auf, macht sich an die Arbeit. Immer wieder, für immer!\n\nDie Zombies, die entsteh'n, sind voll vom dunkelsten Mojo, das zu find'n ist. Geht in Richtung West'n, da findet Ihr einen ganzen Haufen von denen, und bringt mir das Mojo, ja?", sourceObjective = "Sammelt 6 dunkelstes Mojo von Zombies der Sandwüter.", progress = "Habt Ihr das Zeug, Mann?", completion = "<Mazoga kippt seinen Kopf zurück und inhaliert tief von dem Klumpen des geheimnisvollen Materials. Seine Augen leuchten auf.>\n\nMächtiges Zeug, Mann... ah, wenn Ihr seh'n könntet, was ich sehe... vielleicht probiert Ihr es ja auch mal aus, irgendwann.\n\nDie Geister ruf'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[25027] = { id = 25027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und das Schweinchen, das hat Zähne...", description = "Wenn man Gaines glaubt, nennen die Stacheleber ihre Matriarchin \"Dreizahn\". Sie hat die Dornen dieses verrückten Dschungels für ihre eigenen Zwecke verdreht und sie hat befohlen, dass man Gaines \"zerreißen und an die Überwucherung verfüttern\" soll. Nettes Weibchen.\n\nLassen wir sie ihre eigene Medizin kosten. Nehmt den Dornstab, den Ihr entdeckt habt und wendet ihn gegen Dreizahn an, um sie zu eliminieren. Dann tötet die Greisinnen, die sie ausgebildet hat, damit niemand anders ihren Platz einnehmen kann.", sourceObjective = "Verwendet den Dornstab gegen Dreizahn und tötet 2 Deviatgreisinnen in der Überwucherung.", progress = "Ich verstehe, warum die Horde diese kleinen Nervensägen hasst. Habt Ihr Euch Dreizahn schon angenommen?", completion = "...Extremität um Extremität abgerissen!? Nun, ich habe fast ein schlechtes Gewissen, aber der brennende Hass verhindert das. Sie hat bekommen, was sie verdiente.\n\n<Korporal Teegan nimmt den Dornenstab und zerbricht ihn über seinem Knie.>\n\nProblem gelöst.", sourceObjectiveStatus = "unverified-source-field" }
quests[25028] = { id = 25028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Grund auf Ärger", description = "Teegan ist ein Narr, wenn er denkt, dass die Stacheleber an dieser plötzlichen Wucherung Schuld sind. Seht Euch um. Ich beobachte jeden Tag, wie diese Pflanzen wachsen und sprießen - jede Generation ist noch mehr mutiert als die vorherige. Das ist keine Stammesmagie, das ist etwas Urwüchsiges. Und Gefährliches.\n\nVorgestern ist ein großer Druide durch unser Lager gezogen. Sucht Naralex irgendwo mitten in diesem Dschungel. Er wird wissen, was zu tun ist.\n\nUnd sammelt unterwegs Pflanzenproben in der Überwucherung, damit er sie studieren kann.", sourceObjective = "Sammelt 10 ungewöhnliche Blütenknospen von knospenden Blüten in der Überwucherung auf.", progress = "Ich bin sehr beschäftigt, {class}. Dieser unkontrollierte Bewuchs droht den ganzen Kontinent einzuhüllen. Habt Ihr irgendwelche Neuigkeiten?", completion = "Ah, Proben von verschiedenen Bereichen der Überwucherung? Ja, die werden ausgesprochen hilfreich sein. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25029] = { id = 25029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesfälle in der Familie", description = "Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.\n\nAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wenigstens waren wir loyale Narren.\n\nDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!\n\nDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.", sourceObjective = "Beschafft Euch die Überreste von Gregor, Nissa, Thurman und Devlin.", progress = "Habt Ihr die sterblichen Überreste der Agamands? Sind diese verfluchten Bestien endlich vernichtet?", completion = "Rache hat einen süßen Geschmack, findet Ihr nicht? Als Ihr die Agamands vernichtet habt, habt Ihr da irgendeinen Hinweis auf einen freien Willen in ihnen bemerkt? Ich hoffe es. Ich hoffe, sie hatten Angst, bevor sie in die Vergessenheit zerschlagen wurden.\n\nDas ist eine närrische Hoffnung, ich weiß. Aber es ist dennoch eine Hoffnung, die ich hege.", sourceObjectiveStatus = "unverified-source-field" }
quests[25030] = { id = 25030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spukmühlen", description = "Ihr spürt eine bösartige Präsenz im Schädel der Bestie. Coleman Heller wäre sicher daran interessiert.", sourceObjective = "Bringt Dargols Schädel zu Coleman Heller bei Agamands Mühlen.", progress = "Nun, nun... Was haben wir denn da?", completion = "Ist das Dargol? Als er noch am Leben war, war er schon bösartig. Seine Launen hinterließen tiefe Wunden, seine Klinge sogar noch tiefere.\n\nUntot zu werden hat daran nichts geändert, obwohl es seinem Charakter durchaus gerecht wird.\n\n<Coleman hält den Schädel hoch und blickt in die leeren Augenhöhlen.>\n\nJa, das war ganz sicher Dargol. Ich kann seine Boshaftigkeit sogar in seinen Überresten spüren.\n\nIhr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25031] = { id = 25031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zu den Mühlen", description = "Agamands Mühlen im Westen sind an die Geißel verlorengegangen. Die Familie Agamand wurde getötet und das gesamte Anwesen von der Geißel übernommen.\n\nDas ist möglicherweise der größte Außenposten der Geißel in Tirisfal, {name}. Wenn Ihr glaubt, dass Ihr {class} genug seid, geht dort hinaus und sprecht mit Coleman Heller. Er hat sein Bestes gegeben, um das Land zurückzuerobern, und er kann Hilfe gebrauchen. Folgt einfach dieser Straße - sie führt Euch direkt zu ihm.", sourceObjective = "Meldet Euch bei Coleman Heller bei Agamands Mühlen in Tirisfal.", completion = "Argh! Fort mit Euch! Oh, Ihr gehört nicht zur Geißel, oder?\n\nDer Bansheekönigin sei Dank, dass Ihr hier seid. Ich habe die Situation hier oben weit unterschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25032] = { id = 25032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse in der Oase", description = "Ja, jetzt sehe ich auch die andere Hälfte, Mann... südlich von hier...\n\nWir sind ganz in de Nähe, Mann. Es ist eine Oase, unter dem Schlamm des Wassers vergrab'n. Beeilt Euch!", sourceObjective = "Sucht nach dem Jang'thraze der Beschützer.", completion = "Mazoga? Er hat das Schwert an sich genommen? Dieser dreckige...\n\n<Trenton blickt sehr finster drein.>\n\nWenigstens seid Ihr mit dem Leben davon gekommen. Der Biss des Peitschers ist sehr gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25034] = { id = 25034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Front!", description = "Ich würde Euch gern hier hinter den Linien behalten, aber offensichtlich seid Ihr an die Front gerufen worden. Botschafter Gaines - Ihr erinnert Euch? - hat den Gefechtsstand verlegt und hat in seinem letzten Schreiben verlangt, dass Ihr ihm höchstpersönlich helfen sollt.\n\nIhr findet unseren Gefechtsstand südlich von hier in einer Gegend, die als \"Felder des Blutes\" bekannt geworden ist.\n\nSeid vorsichtig, {name}. Die Horde hat sich darauf verlegt, unsere Offiziere unterwegs aus dem Hinterhalt heraus zu überfallen.", sourceObjective = "Findet Botschafter Gaines im Gefechtsstand im Südlichen Brachland.", completion = "Ah, {name}. Ich habe mit dem General hier über Euch gesprochen. Ich danke Euch erneut, dass Ihr mein Leben gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25035] = { id = 25035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Linien durchbrechen", description = "Vol'jin hat zum Angriff auf die Naga, die unsere nördliche Insel übernommen haben, aufgerufen. Viele unserer Männer kämpfen bereits nahe der Brücke gegen den Feind, aber ein paar von uns versuchen ihre Linien zu durchbrechen, um die Insel selbst anzugreifen.\n\nSprecht mit Jornun. Er steht direkt hier und wird Euch den Ritt zur Insel ermöglichen. Sucht dort nach Morakki, dem Hauptmann der Wache. Er wird Euch sagen, wie Ihr bei der Schlacht behilflich sein könnt.", sourceObjective = "Sprecht mit Jornun, um Euch einen Ritt zur Bucht der Gallschuppen zu sichern und sucht dort nach Morakki.", completion = "Gut, dass Ihr hier seid, Bruder.\n\nVol'jin erfüllt uns in solchen Momenten mit Stolz. Es fühlt sich gut an, Bedrohungen bei den Hörnern zu packen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25036] = { id = 25036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegans Sorgen", description = "Der Admiral wird zufrieden sein, dass Nordwacht fast wieder gesichert ist, aber wenn wir diesen Kontinent im Griff behalten wollen, müssen wir die Nachschublinien nach innen offen halten.\n\nKurz vor dem Angriff habe ich die merkwürdigsten Berichte von Korporal Teegan erhalten, der die Verantwortung dafür trägt, dass unsere Verbindung mit dem Gefechtsstand aufrechterhalten wird. Er sagt, er hat Schwierigkeiten mit dem \"Dschungel\"? Es gibt keinen Dschungel im Brachland!\n\nFolgt der oberen Straße aus Nordwacht heraus und schaut, ob Ihr unserem eigensinnigen Korporal zur Hand gehen könnt.", sourceObjective = "Meldet Euch bei Korporal Teegan bei Teegans Expedition im Südlichen Brachland.", completion = "Also Paxton sagt, es gibt keinen Dschungel im Brachland? Und wie nennt Ihr DAS hier?\n\nIch habe einen Haufen Vorräte, die ins Innere gebracht werden sollen und mein Lager ist von einem Wald, der - ich schwöre - stündlich weiter wächst überrannt worden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25037] = { id = 25037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krebsfischen", description = "Vielleicht wird mein alternder Körper nach all den Jahren zu wählerisch, aber Eberfleisch bekomme ich nicht mehr so leicht runter. Na ja, bleibt umso mehr für die neuen Rekruten\n\nWir haben zwar gerade einige Krebsfallen ausgelegt, aber würdet Ihr einem ungeduldigen alten Troll, der sich nach frischem Kriecherfleisch sehnt, helfen? Es gibt sie überall auf der Insel, aber am besten jagt man sie vor der Ostküste.", sourceObjective = "Tötet Zwergbrandungskriecher und sammelt 5 Stücke frisches Kriecherfleisch.", progress = "Das Meer schenkt uns kaum etwas, das besser schmeckt als frisches Kriecherfleisch.", completion = "Wunderbar. Ich danke Euch für Eure große Freundlichkeit, Junge. Die Geister werden bestimmt wohlwollend auf Euch herabsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25038] = { id = 25038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordos Aufgabe", description = "Meister will Kräuter. Wir große Hände haben und nicht gut greifen können. Ihr uns helfen und wir Euch nicht wehtun. Wir Düsterkraut brauchen. Viele Kräuter hier und bei Straße.\n\nWenn Ihr Düsterkraut haben, Ihr bringen zu Meister Holland in Brill.", sourceObjective = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland in Brill.", progress = "Wo ist diese nutzlose Monstrosität? Entweder habt Ihr, was ich benötige, oder Ihr verschwindet besser von hier und sucht es.", completion = "Was ist denn das? Düsterkraut?! Ich brauche kein Düsterkraut! Diese hirnlose Fleischmasse pflückt da draußen Gänseblümchen und bringt Gott weiß wie viele Tölpel wie Euch dazu, das Gleiche zu tun. Das sollte keine Beleidigung sein.\n\nWir kümmern uns später um das Düsterkraut. Im Moment haben wir andere Dinge zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25039] = { id = 25039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr etwas Merkwürdiges gesehen?", description = "{race}! Hört mal, ich habe etwas… Merkwürdiges zu besprechen.\n\nGestern war ich am Blendwassersee angeln, als ich etwas wirklich Komisches gesehen habe… eine Art Wolfmann, der in Tirisfal herumrannte. Meint Ihr… äh… also… Könnte das ein Worgen gewesen sein?\n\nJedenfalls überlege ich die ganze Zeit, ob ich es Exekutor Zygand sagen soll, aber dieser Kerl jagt mir einfach eiskalte Schauer über den Rücken. Könntet Ihr nicht mit ihm sprechen?", sourceObjective = "Sprecht mit Exekutor Zygand über Eure Begegnung mit dem Worgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25041] = { id = 25041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz des Löwen", description = "Respektiert den Löwen, {name}! Ein grausamer Jäger. Man muss die Eleganz des Tieres bewundern... Muskeln und Klauen... Jagt seine Beute bis zur Erschöpfung... So urtümlich...\n\nTut mir leid - ich schweife ab. Wie ich schon sagte, ich respektiere diese Löwen, aber sie sind mörderisch für unsere Patrouillen. Und das meine ich wörtlich. Die Männer haben Angst, nachts alleine aufs Klo zu gehen. Könntet Ihr dabei helfen, unser ein Lager ein wenig sicherer zu machen?\n\nBrachlandlöwen hängen gerne unter Bäumen herum.", sourceObjective = "Tötet insgesamt 5 Ebenenstreuner oder Ebenenstolzmähnen.", completion = "Gute Arbeit! Wie war's? Habt Ihr die Jagd genossen?\n\nSeid Ihr durch hohes Gras gelaufen, angetrieben von der Witterung Eurer Beute, bis Ihr ihr an die Kehle springt und das Adrenalin durch Euch schießt während Eure sabbernden Fangzähne... Äh, also so in etwa.", sourceObjectiveStatus = "unverified-source-field" }
quests[25042] = { id = 25042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerer Bauch marschiert nicht gern", description = "Es stimmt schon, was man sagt: Leerer Bauch marschiert nicht gern. Und wir marschieren jetzt schon eine ganze Weile.\n\nIch überlege, ob wir ein paar dieser riesigen Sturmschnauzen grillen sollen, die hier herumstolpern. Das Fleisch würde uns für Wochen ernähren.\n\nSturmschnauzen sind groß und langsam und sollten einfach zu töten sein. Es sei denn... Ihr habt nicht zufällig Metall bei Euch?", sourceObjective = "Besorgt 4 frische Sturmschnauzensteaks, indem Ihr Sturmschnauzen im Südlichen Brachland tötet.", progress = "<Trawley leckt sich über die Lippen und kann sein Sabbern kaum unterdrücken.>\n\nHabt Ihr meine Steaks schon? Schön blutig?", completion = "<Sams Augen quellen ihm förmlich aus dem Kopf, als ihr die riesigen Fleischstücke vor ihm hinknallt.>\n\nOh ja... oh ... JA! Ich hätte meins gern englisch. Ich denke, ich könnte etwas für die anderen grillen... Wie hätte Ihr Eures gern?", sourceObjectiveStatus = "unverified-source-field" }
quests[25043] = { id = 25043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felder des Blutes", description = "Die Horde nennt diese Gegend nur noch die \"Felder des Blutes\". Ein passender Name: Das Rohr hier ist mit dem Blut einiger meiner besten Leute getränkt.\n\nIch habe Spähtrupps ausgeschickt, um die Stacheleber zu vernichten und mir über die Bewegungen der Hordentruppen Bericht zu erstatten, aber niemand ist zurückgekehrt. Sie könnten da draußen Eure Unterstützung brauchen.\n\nPatrouilliert durch die Felder und sucht die Ödnisgrunzer, die uns so viel Verdruss bereiten. Erwartet nicht, dass sie aufgeben - ihr Kriegshäuptling hat ihnen befohlen, bis zum Tod zu kämpfen.", sourceObjective = "Tötet 10 Ödnisgrunzer in den Feldern des Blutes im Südlichen Brachland.", completion = "Sehr gut! Vielleicht wird es uns nie gelingen, die Horde ganz aus diesen Landen zu vertreiben, aber mit einer starken Präsenz können wir ihren Kampfeswillen untergraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25044] = { id = 25044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die etwas andere Diplomatie", description = "Ich habe meine Begegnung mit dem Tod durch die Hände der fiesen Stacheleber in dem dreckigen Dschungel nicht vergessen. Der General hat einige taktische Schläge angeordnet, aber er will keinen Völkermord begehen. Derartige Skrupel kenne ich nicht.\n\nNehmt dieses Horn, das ich während meiner Verhandlungen 'ausgeliehen' habe. Lasst das Horn innerhalb des Herausforderungsrings der Borstennacken westlich von hier erschallen - Ihr könnt ihn nicht übersehen. Ich möchte, dass Ihr Säbelschnauze, den Champion der Borstennacken, zu einem Einzelkampf herausfordert. Sein Tod vor den Augen seiner Anhänger wird sie ins Chaos stürzen.", sourceObjective = "Geht mit dem Horn der Herausforderung zum Herausforderungsring der Borstennacken im Südlichen Brachland. Lasst das Horn erschallen, um Säbelschnauze herauszufordern und tötet ihn.", progress = "Säbelschnauze! Ist er tot? Welche Neuigkeiten gibt es?", completion = "Eine \"Schweinokalypse\" sagt Ihr? Diese Tiere haben auf jeden Fall eine einzigartige Vorstellung von \"Einzelkampf\"!\n\nEgal, Ihr habt es gut gemacht. Jetzt, da die Stacheleber im Chaos versinken, sollte ich keine Probleme haben, die Feldkommandeure davon zu überzeugen, dass sie Streuner, die ihnen begegnen, hinrichten sollen. Der General muss gar nicht wissen, dass wir die Kampagne auf einen neuen Level angehoben haben.... Es ist besser so.", sourceObjectiveStatus = "unverified-source-field" }
quests[25045] = { id = 25045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Linie im Schmutz", description = "Aus strategischen Gründen erfordert die Kontrolle über eine Region ständige Bewachung. Schaut hier auf dieser Karte - ich habe eine Anzahl strategisch wichtiger Hügel ausgemacht, die die Allianz einnehmen muss, wenn wir den Feind unter Kontrolle behalten wollen.\n\nMeine Späher haben diese Örtlichkeiten bereits auf dem Feld markiert. Ich brauche jemanden, der die Führung übernimmt, um sie einzunehmen und Ihr seid genau <der richtige Mann/die richtige Frau> für diese Aufgabe.\n\nSucht nach neutralen grauen Flaggen auf den Hügeln im Norden, Osten und Süden von den Überresten Taurajos. Nehmt einen ein und verteidigt ihn!", sourceObjective = "Erobert einen neutralen Hügel in den Feldern des Blutes und verteidigt ihn gegen den Gegenangriff der Horde.", completion = "Euer Bericht, {class}?\n\n\n\nUnglaublich, {name}! Ihr seid wahrlich ein Gewinn für die Allianz. Ich werde dafür Sorge tragen, dass meine Männer Eurem Beispiel folgen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25046] = { id = 25046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Umarmung einer Tochter", description = "Das Flüstern fährt fort.\n\n<\"Mein Name ist Lilian Voss. Bevor ich starb, war ich Mitglied des Scharlachroten Kreuzzugs. Mein Vater, Hohepriester Voss, erzog mich, eine Waffe gegen die Verseuchten zu sein. Ich lernte Tarnung, Magie, Kampfkünste. Alles, um mich stärker zu machen. Ich habe ihm meine Kindheit geopfert.\">\n\n<\"Doch dann wollte es das Schicksal, dass ich starb und... so zurückkehrte. Mein Vater vergaß mich sofort, und als ich zu ihm zurückkehrte, befahl er meine Hinrichtung.\">\n\n<\"Kommt. Wir werden jetzt mit ihm sprechen, in seinem Turm im Nordwesten.\">", sourceObjective = "Bringt Lilian Voss zu ihrem Vater im Turm am Kreuzfahrerpass.", completion = "Von der Wiege über die Bahre in den Untod folgen wir alle unserem eigenen Weg - manche leichter als andere. Es hört sich an, als wäre der Weg dieses Mädchens Voss bis jetzt hart gewesen.\n\nHoffentlich entschließt sie sich am Ende, uns beizutreten und der Dunklen Fürstin zu folgen. Mit Macht wie ihrer könnten wir unglaubliches leisten.\n\nÜbrigens, {name}... großartige Arbeit da draußen. Wenn Ihr jemals Zeit und Lust habt, habe ich vielleicht etwas Arbeit in den Pestländern für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25047] = { id = 25047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Pantherfigur", description = "Diese völlig zerbrochene Figur wurde von ihrem letzten Besitzer beiseite geworfen. Mit den richtigen Materialien und Euren Fähigkeiten in Juwelierskunst könnte sie jedoch wieder vollständig repariert werden.", sourceObjective = "Repariert die zerbrochene Figur mit den Fähigkeiten und den Materialien, die Euch zur Verfügung stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25048] = { id = 25048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung an der Küste", description = "Wenn wir Herrn Noggenfogger davon überzeugen möchten, mehr Gnome hier einziehen zu lassen, müssen wir ihm nur zeigen, wie nett wir sind! Und ich weiß auch schon, wie.\n\nGadgetzan ist von Piraten eingenommen worden, aber viele der Güter, die von den Schiffen geworfen wurden, sind noch intakt. Sie wurden nur weggespült. Viele davon werden südlich der Stadt angespült.\n\nSammelt für sie diese Vorräte, damit wir uns mit ihnen anfreunden! Ich werde mich darum kümmern, dass dieses böse Goblinmädchen sie nicht vor Euch an sich nimmt und verkauft.", sourceObjective = "Sammelt 7 Dampfdruckvorräte.", progress = "Ihr habt alle Kisten? Lasst mich mal sehen!", completion = "Fast alles sieht noch gut aus! Was für ein Glück!\n\nDie Goblins des Dampfdruckkartells werden so froh darüber sein, ihre Ladung wieder zurückzubekommen. Und natürlich werden so gute Taten auch belohnt!\n\nWir müssen aber noch so viele andere Sachen erledigen. Fleißig, fleißig!", sourceObjectiveStatus = "unverified-source-field" }
quests[25049] = { id = 25049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfützenstampfer", description = "Hier gibt es ein großes Problem! Es ist toll, dass der Ozean so weit ins Land gestoßen ist, weil Schiffe jetzt Gadgetzan ansteuern können. Aber auch ein paar üble Meeresriesen nähern sich der Stadt! Ich bin mir sicher, dass Herr Noggenfogger sich freuen würde, wenn wir uns darum kümmern.\n\nKeine Sorge, ich will nicht, dass Ihr es aus Herzensgüte macht. Tötet sie und ich werde Euch belohnen!", sourceObjective = "Tötet 8 Gezeitenschreiter.", completion = "Oh, jetzt wird es hier so viel schöner werden, ohne die Gezeitenschreiter!\n\nZumindest, bis wieder welche hierher finden. Aber trotzdem, vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[25050] = { id = 25050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenrettung", description = "Als das Wasser über uns hereinbrach wurde das Dampfdruckpier östlich von hier komplett überflutet und nun sind dort noch immer arme Goblins, die auf Rettung warten! Die Piraten schießen auf jedes Boot, das die Docks verlässt.\n\nSie werden aber nicht damit rechnen, dass wir fliegen! Bei den Docks steht ein Heißluftballon. Wir können ihn benutzen, um die Goblins zu retten und gleichzeitig auch noch die Seeräuber ausschalten. Herr Noggenfogger wird begeistert sein!\n\nGeht zu den Docks und macht den Heißluftballon startklar. Ich komme gleich hinterher, ja? Ich muss nur noch die Raketen holen...", sourceObjective = "Bringt Lebensraketen zu 5 Überlebenden des Dampfdruckkartells und benutzt Bomben, um 40 Blockierer der Südmeerfreibeuter zu töten.", completion = "Das war toll! Es scheint, als seien die meisten der Goblins, denen wir geholfen haben, sicher an Land gekommen, ohne von den Bomben erwischt zu werden. Jetzt haben wir es dem Goblinmädchen aber gezeigt!\n\nHier ist eine ganz besondere Belohnung für Euch, mein Lieber!", sourceObjectiveStatus = "unverified-source-field" }
quests[25051] = { id = 25051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graunebelausrottung", description = "Die Spinnen, die sich in den Graunebelhöhlen im Nordwesten tummeln, sind eine weitere ernste Bedrohung für uns hier. Die Oger kommen zwar locker mit ihnen zurecht, aber uns auf sie zu konzentrieren, während die Streitkräfte von Theramore in der Gegend lauern, wäre ein tödlicher Fehler.\n\nIch brauche jemanden, der die Eier in den Graunebelhöhlen zerstört, um dieser Plage ein Ende zu setzen. Ihr findet die Eier im tiefsten Teil der mit Netzen übersäten Minen... bei ihren Wächtern.", sourceObjective = "Zerstört 8 Graunebeleier in den Graunebelhöhlen.", completion = "Das ist eine große Erleichterung, {class}. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[25052] = { id = 25052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truhe des toten Mannes", description = "Oh du meine Güte, man kann wirklich sehen, dass die Schlacht mit den Piraten eine wilde Schlacht ist. Wir werden sicherstellen, dass sie Gadgetzan und unseren neuen Gnomenwohnort nie wieder belästigen werden!\n\nWir werden sie töten!\n\nWollt Ihr uns helfen? Wir müssen wirklich sicherstellen, dass wir mehr von ihnen töten als Grünnase da drüben mit ihren furchtbaren Helfern. Das wäre wirklich sehr hilfreich!", sourceObjective = "Tötet 15 Piraten der Südmeerfreibeuter.", completion = "Gute Arbeit! Wir räumen hier aber wirklich richtig auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[25053] = { id = 25053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niederbrennen!", description = "Dieser Ort wäre für uns Gnome bestimmt eine tolle Heimat, wenn es nur nicht so alt, schmutzig und voller Piraten wäre! Mit den Piraten sind wir einen Schritt weiter, aber hässlich und schmutzig ist es immer noch.\n\nIch meine, kein respektierlicher Gnom würde jemals in so hässlichen Behausungen wie diesen Hütten wohnen! Also, nehmt diese Flasche mit dem hochentzündlichen Rum und brennt diese hässlichen Hütten nieder!", sourceObjective = "Benutzt den brennenden Rum, um die nordwestliche Hütte, die nordöstliche Hütte und die südwestliche Hütte niederzubrennen.", completion = "Ist das nicht wunderschön anzusehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25054] = { id = 25054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute plündern", description = "Es ist so verschwenderisch, wie die Piraten ihre Goldschätze überall herumliegen lassen. Man könnte das Zeug sogar für praktische Sachen hernehmen! Man könnte es schmelzen und Draht herstellen, oder immanente Abwehrmatrizen, oder es einfach an andere dumme Völker verkaufen, die Gold kaufen, um es zu haben.\n\nOh, und wo ich gerade von anderen dummen Völkern spreche: die geizigen Goblins werden versuchen, alles an sich zu reißen. Das dürfen wir nicht zulassen! Geht, und sammelt die Schätze für Gnomeregan!", sourceObjective = "Sammelt 10 Stück Piratenbeute.", progress = "Ich hoffe, Ihr versucht nicht, etwas davon für Euch selbst zu behalten, Dummerchen! Mit dieser Brille kann ich den Inhalt Eurer ganzen Tasche sehen.\n\nUnd Eurer Rüstung.", completion = "Fantastisch! Damit kann man genug Draht für eine ganze Armee herstellen!\n\nWas für ein Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[25056] = { id = 25056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausige Grizzlys", description = "Habt Ihr die verseuchten Braunbären gesehen, die westlich von hier herumstreunen? Diese Bälge... so entsetzlich, so krank, so... perfekt!\n\nBringt mir 5 davon. Ich habe eine Idee für ein Gift gegen die Geißel, das garantiert wirken wird!", sourceObjective = "Beschafft 5 Bälge eines verseuchten Braunbären.", progress = "Mal sehen... habt Ihr genug Bälge?", completion = "Zitters, Ihr habt es wieder mal geschafft. Die sind perfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25057] = { id = 25057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft sie in Ketten", description = "Unsere Politik, nicht-gewalttätige Kriminelle aus den Verliesen von Sturmwind zu rekrutieren, rächt sich gerade gewaltig, {name}. Einige der weniger moralischen Soldaten sind seit unserem Sieg in Taurajo fahnenflüchtig und plündern die Überreste der Stadt.\n\nDas ist ein Disziplinverlust. Schlimmer noch, die Entweihung ihrer Häuser spornt unsere Feinde an, noch verbissener zu kämpfen, dabei sollte unser eigentliches Ziel doch Frieden heißen.\n\nNehmt diese Handfesseln und führt die Plünderer von Taurajo der Gerechtigkeit zu. Sprecht zunächst mit ihnen, aber wahrscheinlich müsst Ihr Gewalt anwenden, um sie zu bändigen.", sourceObjective = "Sprecht mit Plünderern von Taurajo in den Überresten von Camp Taurajo und verhaftet sie. Benutzt die Handschellen von Nordwacht, um 5 verwundete Plünderer zu überwältigen.", progress = "Ist die Situation in Taurajo unter Kontrolle?", completion = "Gut gemacht, {name}. Einige der Plünderer sind bereits zurückgekrochen und haben um Gnade gebeten. Ich lasse sie eine Weile in dem Verlies der Nordwacht schmoren.\n\nDanke, dass Ihr geholfen habt, die Disziplin in den Rängen aufrecht zu erhalten. Für eine Armee ist es wichtig, als Soldaten wahrgenommen zu werden und nicht als gemeine Banditen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25058] = { id = 25058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenentschärfung nach Goblinart", description = "Die Fallschirmjäger haben den Strand vermint!\n\nDer Kriegshäuptling hat mich gefragt, ob wir etwas dagegen tun können. Ich habe ihm gesagt \"Aber klar können wir!\". Ich dachte mir, Ihr könntet ja diesen Beutel mit Granaten nehmen und die Landminen aus sicherer Entfernung sprengen.\n\nSo regeln wir die Dinge, nicht wahr?!", sourceObjective = "Sprengt 10 Landminen.", progress = "Boss, könnt Ihr noch einmal da runter gehen und noch ein paar mehr sprengen?\n\nDanke!", completion = "Eins zu Null für die Goblins! Dumme Zwerge und Gnome.", sourceObjectiveStatus = "unverified-source-field" }
quests[25059] = { id = 25059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Taurajo Informationen", description = "Der General ist von den Plünderern in Taurajo viel zu sehr abgelenkt. Er ist viel zu weich! Wir müssten uns auf unseren Schlag gegen die Horde konzentrieren.\n\nEs gibt wertvolle Erkenntnisse, die gefährdet werden, wenn wir die Überreste von Camp Taurajo weiter brennen lassen. Während Ihr den Laufburschen für den General macht, sucht nach Karten oder Notizen. Ich verstehe die Orcsprache ein wenig - ich werde das, was Ihr findet schon verstehen können.", sourceObjective = "Durchsucht die Überreste von Camp Taurajo nach 3 Geheiminformationen der Taurajo.", progress = "Habt Ihr die Ruinen schon durchsucht?", completion = "Was habt Ihr für mich ausgegraben? Hmm. Interessant. Die Notiz aus Orgrimmar deutet darauf hin, dass sich ein Wechsel in der Hordenführung anbahnt. Ich denke, dass da Köpfe rollen werden nach dem, was wir Taurajo angetan haben.\n\nWas ist das? Ein Todesurteil für den General hier! Das ist gut zu wissen... Sehr gut zu wissen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25060] = { id = 25060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Definiert \"verrückt\"", description = "Wir haben erfahren, dass vor einiger Zeit ein Schiff der Goblins hier am Strand Schiffbruch erlitten hat. Es gab nur wenige Überlebende, die sich jetzt alleine durchschlagen. Wir hatten gehofft, dass sie wenigstens einigermaßen bei Verstand sind, sodass wir sie befragen können.\n\nAber wir fanden nur einen Haufen Goblins des Bilgewasserkartells, die vollkommen verrückt, wahnsinnig und manisch gewalttätig waren... und das noch mehr als sonst.\n\nIn Kürze werden sie nutzlos und gefährlich sein. Wir können Gnomeregan am besten dienen, wenn wir so viele von ihnen wie möglich vernichten.", sourceObjective = "Tötet 10 verrückte Überlebende.", completion = "Eure Berichte über ihr Verhalten sind wahrlich verstörend… aber auch ein wenig amüsant.\n\nWenn doch nur diese alte Hexe Schredderschreck auf diesem Schiff entkommen wäre…", sourceObjectiveStatus = "unverified-source-field" }
quests[25061] = { id = 25061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landende", description = "Psst! Hey! Kommt näher her, Ihr Narr! Oder soll ich Eure Gedanken lesen? Oh... Egal, kommt trotzdem näher her!\n\nIhr habt tolle Arbeit geleistet, die Ziele Gnomeregans zu realisieren! Und Ihr habt wirklich richtig gut so getan, als seid Ihr nur am Geld interessiert gewesen, einfach fantastisch. Jetzt könnte Kelsey Stahlfunken aber mehr von Eurer Hilfe gebrauchen.\n\nSie ist weiter gezogen... und hat mich gebeten, Euch zu sagen, dass Ihr sie weit im Süden, in Landendestrand zu finden ist. Ich würde sie nicht warten lassen!", sourceObjective = "Sprecht mit Kelsey Stahlfunken an der Station Stahlfunken.", completion = "Es wundert mich, dass Pfauentraum in der Lage war, meinen einfachen Anweisungen Folge zu leisten. Noch dazu musste er auch seinen Mund dabei halten.\n\nAber es tut auch wirklich gut, Euch wiederzusehen, {name}. Jetzt, da diese Scharade vorüber ist, kann ich Euch zeigen, wie die Gnome sich hier um ihre Angelegenheiten kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25062] = { id = 25062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warum wir hier sind", description = "Gnomeregan hat in Erfahrung gebracht, dass die Bilgewassergoblins der Horde eine Bruchlandung auf einer unbewohnten Insel nahe Kalimdor überlebten, bevor sie in Durotar ankamen. Wir kamen ursprünglich her, um zu untersuchen, welche Techniken und Technologien diesem hoffnungslosen Narrenpack erlaubten, solch raue Bedingungen zu überleben.\n\nWährend die Goblins völlig ahnungslos sind, sollten wir immer noch herausfinden, was genau hier passiert ist. Sucht am Strand nach Wrackteilen und Habseligkeiten und bringt mir alles, was Euch irgendwie relevant erscheint.", sourceObjective = "Sucht in den Bilgewässer Schließkisten nach Hinweisen.", progress = "Was habt Ihr gefunden?", completion = "<Kelsey nimmt das Tagebuch und blättert es vorsichtig durch.>\n\nIch muss mir wirklich das Lachen verkneifen. Das ist so typisch. Die Tölpel wissen nicht einmal, dass sie in Kalimdor sind!\n\nAber auf den späteren Seiten... hier könnte etwas Bedeutsameres vonstatten gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25063] = { id = 25063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschildkrötet", description = "Wir brauchen das Objekt, von dem in dem Tagebuch geschrieben wird. Wir brauchen es unbedingt. Es aus der Truhe zu entnehmen wäre kein Problem, wenn das Objekt selbst nicht beeinträchtigt und instabil wäre. Die Truhe mit Gewalt zu öffnen könnte furchtbare Folgen haben.\n\nZum Glück wissen wir, wo der Schlüssel ist... Zumindest statistisch gesehen. Am östlichen Ende des Strandes sind viele Meeresschildkröten. Eine von ihnen könnte den Schlüssel haben.", sourceObjective = "Erlangt von einem Brandungsgleiter den von einer Schildkröte verdauten Schlüssel.", progress = "Hoffentlich ist er trotz Eurer Schildkrötenzerstörungswut noch ganz.", completion = "Nun gut, dieser Tag wird besser und besser! Ich könnte vielleicht noch lächeln später!\n\nNur, wenn Ihr nicht schaut natürlich. Davon habt Ihr schon genug gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25064] = { id = 25064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moraya", description = "Moraya sucht nach Hilfe mit den Raptoren. Ihr solltet mit ihr auf der anderen Seite der Dunkelspeerfeste sprechen, wenn Ihr Gelegenheit dazu findet.", sourceObjective = "Sprecht mit Moraya.", completion = "Heda, Süßer. Vol'jin hat Euch geschickt? Es ist so süß von ihm, an mich zu denken.\n\nIch kann auf jeden Fall Hilfe gebrauchen, aber Ihr müsst noch ein ganzes Stück laufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25065] = { id = 25065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schlag ins Gesicht", description = "Es ist an der Zeit, die Sache zu einem Ende zu bringen. Nach unseren Erkenntnissen ist dieses mysteriöse Objekt im Besitz des \"schlauen\" Schlägers, der im Tagebuch beschrieben wurde. Wir wissen nicht genau, was mit diesem Wesen geschehen ist, also solltet Ihr vorsichtig sein.\n\nDieser ... \"Hackvisage\" versteckt sich in den Hügeln, in der Nähe des Ortes, an dem diese Goblins ihre Toten begraben. Haltet nach dem Friedhof Ausschau. Er sollte sich direkt dahinter aufhalten.", sourceObjective = "Beschafft die Truhe von Hackvisage.", progress = "Seid vorsichtig mit dem Inhalt der Truhe.", completion = "Gut gemacht, {name}. Der Inhalt dieser Truhe wird unser Wissensarchiv in Gnomeregan sicher beträchtlich erweitern. Ich glaube, Ihr habt Euch eine Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25066] = { id = 25066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz von Kezan", description = "Das ist lächerlich! Diese Gnome wissen einfach nicht, wann man aufhören muss!\n\nJetzt ist der Stolz der Goblins gefragt! {name}, springt in den Stolz von Kezan und zeigt ihnen, was das bedeutet!\n\nGebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Schießt 10 Tarnkappenflugzeuge von Gnomeregan vom Himmel.", progress = "Was macht Ihr denn hier? Hoch in die Lüfte mit Euch und holt sie vom Himmel.", completion = "JA!", sourceObjectiveStatus = "unverified-source-field" }
quests[25067] = { id = 25067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkuppel: Der Ginormus!", description = "Die Regeln sind einfach: zwei Männer betreten den Ring, einer - nein, wartet. Manchmal sind da auch Frauen.\n\nAlso, zwei Kämpfer betreten den Ring, einer - nein, ach, manchmal sind es mehr als zwei, und dann kommen auch mehr wieder raus...\n\nAlso, die einzige Regel ist es, in der Donnerkuppel zu bleiben! Es gibt keine anderen Regeln!\n\nZuerst tretet Ihr gegen den größten, heftigsten Banditen der Wüstenläufer an. Das wird ein Kampf zum Aufwärmen oder ein Blutbad. Und Ihr könnt entscheiden!", sourceObjective = "Besiegt Ginormus.", completion = "Ein beeindruckender Anfang. Macht Euch auf mehr gefasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[25068] = { id = 25068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruchstücke der Vergangenheit", description = "Die Kreaturen, die in den Ruinen umherwandern sind Irdene - die Urahnen der Zwerge, die von den Titanen erschaffen wurden, um die Welt zu formen.\n\nDie Struktur der ursprünglichen Irdenen brach bereits vor Tausenden von Jahren zusammen und sie fielen dem Chaos anheim; die neu entdeckten scheinen ihnen darin zu ähneln. Wir sollten diese verwirrten und instabilen Konstrukte nutzen.\n\nBegebt Euch in die Ruinen und zerstört die Irdenen; sammelt die Juwelen, die sich in ihnen befinden. Ihre magischen Energien werden sowohl wertvoll als auch für unsere Studien nützlich sein.", sourceObjective = "Sammelt 5 Juwelen der Irdenen.", progress = "Handhabt sie sorgsam, {name}. Sie sind so alt wie die Welt selbst.", completion = "Wunderbar. Der Gedanke, dass sie von den Schöpfern dieser Welt hergestellt wurden...", sourceObjectiveStatus = "unverified-source-field" }
quests[25069] = { id = 25069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse Uldums", description = "Wir sind bereit, die Vorkammer zu betreten, {name}. Dies ist ein einzigartiger Augenblick.\n\nAus den Schriften, die Ihr mir gebracht habt, glaube ich entnehmen zu können, dass es sich bei diesen Ruinen um den ehemaligen Haupteingang nach Uldum handelt. Die Erdbeben, die die Tore geöffnet haben, haben mit ziemlicher Wahrscheinlichkeit die Tunnel zerstört, aber wir können trotzdem sicherlich noch unglaubliche Sachen hier finden.\n\nSucht die Ruinen nach allem ab, das nicht zerstört scheint, damit wir es untersuchen können. Das Entdeckungsfieber wird uns packen!", sourceObjective = "Sucht in der Vorkammer von Uldum nach einem unzerstörten Artefakt.", completion = "Die Truhe liegt ungestört hier und wurde seit Tausenden von Jahren nicht mehr geöffnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25070] = { id = 25070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was im Inneren ist", description = "Als Ihr Eure Hand auf die Truhe legt ertönt ein leises Rumpeln. Ihr hört das Geräusch einer schleifenden Bewegung hinter Euch wiederhallen, als sich die Truhe von alleine schließt.\n\nEtwas nähert sich!", sourceObjective = "Besiegt den Wächter der Vorkammer.", completion = "Die Truhe öffnet sich nun wieder mit einem schleifenden Geräusch und im Rest der Vorkammer ist Stille eingekehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25072] = { id = 25072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Goblinehre", description = "Wir haben hier nicht einfach unser Lager aufgeschlagen, um lustige Lieder über Gnomen zu singen und mit gefährlichen Maschinen zu spielen. Meine Männer haben seit über einer Woche versucht, diesen Schwarmbau auszuräuchern! Das Problem ist, dass wir so viele Verluste hinnehmen mussten, dass die Käfer im Vorteil sind.\n\nZum Glück fressen die Käfer nicht gerne Goblins. Oder sie heben das Beste bis zum Schluss auf. Zumindest sind fast all meine Männer immer noch in Kokons eingesponnen. Ihr müsst sie retten!", sourceObjective = "Rettet 8 gefangene Goblinkäferjäger aus den Kokons der Hazzali.", completion = "Vielen Dank für Eure Hilfe! Das lag mir wirklich schwer auf der Seele. Wenn man seine Männer verliert, verliert man auch die Arbeitskraft. Und die Moral. Und die Waffen. Und die Magazine, die man diesem Typ ausgeliehen hat.\n\nIhr wisst schon, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25073] = { id = 25073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sen'jin", description = "Ihr macht Euch sehr gut für jemanden, der noch so jung ist. Ich habe keine Zweifel, dass Ihr Euch einen großen Namen machen werdet.\n\nGeht jetzt, nach Nordwesten, durch die Untiefen nach Sen'jin. Dort werdet Ihr auf Meister Gadrin treffen. Er hat sicherlich die eine oder andere Aufgabe für Euch, bevor Ihr Euch wirklich weit in die Wildnis von Durotar wagt.\n\nBitte denkt daran, {name}, wir mögen mit dem jungen Höllschrei nicht immer einer Meinung sein, doch seine Absichten sind edel, und es ist sehr wichtig, dass wir eine vereinte Horde bleiben. Macht die Dunkelspeere stolz.", sourceObjective = "Meldet Euch bei Meister Gadrin in Sen'jin.", completion = "Willkommen, junger {race}. Ihr kommt mit glühenden Empfehlungen, Mann. Es ist gut, Euch endlich in Person zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25074] = { id = 25074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Triumph sehen wir uns wieder", description = "Zum Teil verdanken wir Euren Bemühungen, dass wir die Situation hier stabilisiert haben. Wir müssen unsere Aufmerksamkeit jetzt nach Süden auf die Triumphfeste richten.\n\nDie Triumphfeste ist der Schlüssel zu unserer Operation im Brachland - die lebensnotwendige Landverbindung zwischen Nordwacht und Theramore.\n\nIch packe meine Sachen und mache mich dann allein auf den Weg. Meldet Euch bei Kommandant Roberts in der Feste und ich werde Euch dort bald wiedertreffen. Zusammen werden wir die Frontlinie sichern!", sourceObjective = "Meldet Euch bei Kommandant Roberts in der Triumphfeste im Südlichen Brachland.", completion = "Habt Ihr es schon gehört? Der General ist nie angekommen!\n\nEr wurde da draußen wie ein Hund getötet!", sourceObjectiveStatus = "unverified-source-field" }
quests[25075] = { id = 25075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilejagd", description = "Diese sperrigen Belagerungsmaschinen der Zwerge sind nicht für den Nahkampf in der engen Kriegsnarbe ausgelegt.\n\nIch habe einige neue Entwürfe, die ich gern ausprobieren würde, aber erst einmal benötige ich einige Ersatzteile. In der Kriegsnarbe stehen reichlich Wracks herum. <Ein unternehmungslustiger/Eine unternehmungslustige:c> {class} wäre jetzt ideal, um sie zurückzuschleppen.\n\nDas seid Ihr, {name}. Ich spreche von Euch.", sourceObjective = "Sammelt 8 Teile Belagerungsmaschinenschrott in der Kriegsnarbe im Südlichen Brachland auf.", progress = "Was habt Ihr für mich?", completion = "Ooh, schaut mal! Ein fast vollständiger Auspuffkrümmer, ein Verteilerkasten, ein funktionierendes Sperrdifferential... Ihr habt wirklich Ahnung von Schrott, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25079] = { id = 25079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulverspielchen", description = "Unsere Ladung Salpeter aus Düstermarschen wurde aufgehalten. Das bedeutet, wir können hier kein Schwarzpulver mehr herstellen.\n\nAber ich kann unsere Bewaffnung umrüsten, damit sie mit dem Spreng-und-Weg-Pulver der Goblins funktionieren. Es ist instabil, gefährlich, schädlich für die Haut und gesundheitsschädlich, wenn man es verschluckt... aber ich glaube, ich könnte es einsatzfähig machen.\n\nBringt mir ein Fass von dem Zeug, indem Ihr einen dieser Pionierspezialisten der Goblins angreift, die unsere Mauern angreifen.", sourceObjective = "Besiegt einen Pionierspezialisten in der Nähe der Kriegsnarbe und bringt ein Fass mit Spreng-und-Weg-Pulver an Euch.", progress = "Habt Ihr schon ein Fass mit Spreng-und-Weg-Pulver?\n\nWenn Ihr eins in die Hände bekommt - nicht schütteln!", completion = "Großartig! Stellt das Fass genau hier ab. Ich werde einige Ladungen abmessen, sobald ich meinen Ganzkörperschutzanzug angezogen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25080] = { id = 25080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Batterien nicht eingeschlossen", description = "Okay! Mit den Ersatzteilen, die Ihr für mich besorgt habt, habe ich den groben Rahmen für mein vielseitiges neues Angriffsfahrzeug erstellt. Jetzt brauche ich nur noch eine kompakte Energieversorgung.\n\nMir ist aufgefallen, dass die einheimischen Wildtiere hier ganz schön zuschlagen - elektrostatisch gesprochen. Könnt Ihr Donnerköpfe in der Nähe jagen und mir einen intakten Elektromagen besorgen? Möglicherweise müsst Ihr ein paar töten, bevor Ihr eine brauchbare Drüse findet.", sourceObjective = "Besorgt einen summenden Elektromagen von einem Donnerkopf im Südliches Brachland.", progress = "Es muss doch ein ungeheurer evolutionärer Vorteil sein, wenn man Blitze abfeuern kann. Aus dem Gesicht.", completion = "<Der Magen versetzt Mizzy einen Schock, als Ihr ihn ihr überreicht und sie fällt zu Boden.>\n\nOh, OH! Das ist fies! Ich liebe es!", sourceObjectiveStatus = "unverified-source-field" }
quests[25081] = { id = 25081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anspruch auf die Kriegsnarbe erheben", description = "Die Horde hat uns hier durch den Kampf, den sie von ihrer Feste westlich von hier führen, zum Stillstand gebracht. Die Kämpfe halten an, obwohl das Land unter unseren Füßen auseinanderbricht.\n\nJemand muss die Pattsituation aufheben! Ihr müsst Euch für mich in die Kriegsnarbe vorwagen und meinen Leuten helfen, die Hordengegner dort zu zerschmettern.\n\nIm Zentrum der Narbe befindet sich eine Flagge, die anzeigt, wer gerade über sie herrscht. Findet die Flagge. Es wird sich für Euch lohnen, die Narbe für die Allianz einzunehmen, wenn es nicht schon jemand anders getan hat.", sourceObjective = "Geht zu der Kriegsnarbe. Findet die Flagge und tötet 10 Ödnisräuber\n\nDie Flagge einzunehmen wird allen Allianzspielern in der Narbe einen Vorteil im Kampf gewähren.", completion = "Großartige Arbeit, {name}! Meine Leute berichten mir über einen Durchbruch. Ihre Feste wird nicht mehr lange überleben...", sourceObjectiveStatus = "unverified-source-field" }
quests[25082] = { id = 25082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Käfer beseitigen", description = "Warum das Oberkommando der Meinung war, dass es eine gute Idee ist, auf einem Silithidenhügel eine Feste zu errichten, werde ich nie verstehen. Diese kleinen Mistviecher untergraben unsere Befestigungsanlagen und halten uns auf. Wir müssen sie ausräuchern!\n\nNehmt diesen Eimer mit brennendem Pech und schüttet das Pech über den Silithidenhügeln vor dem Haupttor aus. Sie sehen wie Sandhügel aus. Tötet alles, was herauskommt, aber seid vorsichtig, {name}, diese gemeinen Viecher werden wahrscheinlich herausschwärmen, wenn Ihr die Hügel in Brand steckt.", sourceObjective = "Wendet den Eimer mit brennendem Pech auf Silithidenhügel außerhalb der Triumphfeste an und tötet 10 Silithidschwärmer, wenn sie herauskommen.", progress = "Wie läuft der Kampf, {name}?", completion = "Das sollte unsere Bugprobleme für eine Weile beheben - sie dürften Schwierigkeiten haben, sich da herauszugraben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25084] = { id = 25084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsende Bedrohung", description = "Einen Moment mal, {class}.\n\nWir haben hier mehr Probleme, als nur das Ende der Welt, wie wir sie kennen. Unser Wachtposten hier wird von den Stachelebern bedroht. Klar, solange sie in ihrem Kral blieben, hatten wir kein Problem damit, sie einfach in Ruhe zu lassen, aber jeden Tag rücken sie weiter auf unser Lager vor.\n\nMahka, ihr grünes Herz sei gesegnet, würde mir nie verzeihen, wenn ich hinausginge und ihnen selbst die Schädel einschlüge, aber wenn Ihr helfen könntet, diejenigen, die in der Nähe des Lagers herumstreunen, zurückzudrängen, würde ich das sehr begrüßen.", sourceObjective = "Tötet 13 Stacheleber der Klingenmähnen.", completion = "Euch gebührt mein Dank, wenn nicht sogar der Dank des gesamten Irdenen Rings.\n\nVielleicht werden wir eines Tages einen Weg finden, das mit diesen Schweinen auszudiskutieren, aber wir können das Land nicht heilen, wenn wir im Schlaf getötet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25085] = { id = 25085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quetschzahn", description = "Una hat viel Zeit in Camp Taurajo verbracht. Sie hat mir von einem Stacheleber erzählt, der dort gefangen gehalten wurde. Sein Name war Quetschzahn. Für einen Stacheleber war er ziemlich gerissen.\n\nIch habe mir den Kopf zerbrochen, warum die Stacheleber in letzter Zeit so aufmüpfig sind und möglicherweise ist Quetschzahn lebend aus Taurajo entkommen. Wenn ja, ist er derjenige, der ihnen sagt, wo's langgeht.\n\nIn den Hügeln im Nordwesten befindet sich eine große Hütte. Wenn Ihr Quetschzahn dort findet, streckt ihn nieder.", sourceObjective = "Tötet Quetschzahn.", completion = "Welch eine Erleichterung. Vielleicht wird sich der Rest von ihnen jetzt zurückhalten. Je weniger hier gekämpft wird, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[25086] = { id = 25086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammensteinspitze", description = "Könnt Ihr mir einen großen Gefallen tun, {name}? Der Onkel meiner Schwägerin ist Mitglied im Irdenen Ring und er befindet sich hier im Brachland, um die Auswirkungen des Kataklysmus an der Flammensteinspitze zu erforschen. Er sagt, sein Lager ist von Stachelebern umzingelt und ich mache mir Sorgen, dass sie sein Lager überrennen könnten.\n\nWürdet Ihr einmal für mich nach Dorn Roterde schauen? Ich möchte auf keinen Fall, dass ihm ein Leid geschieht, gerade weil er ein Familienmitglied ist und so.", sourceObjective = "Sucht nach Dorn Roterde an der Flammensteinspitze im Südlichen Brachland.", completion = "Wie bitte? Der kleine Logan meint, ich brauche Schutz?\n\nIch bin derjenige, der beschützt!\n\nDie Stacheleber sind kurz davor, Amok zu laufen. Sie haben den gesamten Süden abgewürgt und jetzt stehen nur noch wir ihnen im Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[25087] = { id = 25087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Doppelzopf", description = "Die Allianz schuldet den Zwergen von Bael Modan etwas, die einige der ältesten Befestigungen hier im Brachland gebaut haben.\n\nIhr Kommandant, General Doppelzopf, ist wahrhaft unerschütterlich. Einer unserer Besten. Er ist südlich von hier auf Patrouille und hält die Horde in Atem.\n\nIch möchte ihn über die Situation auf dem Laufenden halten, damit wir unseren nächsten Schritt planen können. Könntet Ihr diesen Bericht von der Front zu ihm hinaus bringen?", sourceObjective = "Liefert den Bericht von der Front bei General Doppelzopf ab, der im Südlichen Brachland auf Patrouille ist.", progress = "Hrm, Neuigkeiten aus der Feste? Naja. Spuckt es aus!", completion = "<Der General liest den Bericht und nickt zustimmend, als er von der Kriegsnarbe liest.>\n\nIhr habt Euch hier im Brachland durchaus einen Namen gemacht, {name}. Aber Roberts geht nicht weit genug. Wir brauchen einfach einen entscheidenden Sieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[25089] = { id = 25089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach den Gräbern", description = "Darnell hat mir berichtet, dass Ihr Euch schon kennengelernt habt. Das ist gut, weil ich Euch beide nach Todesend schicken werde. Eure Arbeit hier ist abgeschlossen.\n\nSprecht mit Todeswache Saltain nördlich von hier. Er wird Euch mehr verraten können.", sourceObjective = "Sprecht mit Todeswache Saltain in Todesend in Tirisfal.", completion = "Die Val'kyr waren in letzter Zeit sehr beschäftigt mit neuen Wiederbelebungen. Allein seit heute Morgen habe ich ein Dutzend neuer Ankömmlinge den Hügel herunterlaufen sehen.\n\nIhr seid allerdings der vielversprechendste {class}, den ich heute gesehen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25090] = { id = 25090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eitrige Aufgabe", description = "Teile der Geißel sind nach und nach in Tirisfal eingedrungen und suchen diese Gegend heim.\n\nIch brauche jemanden, der die faulenden Toten und verheerten Kadaver zurückschlägt, die den kleinen Hof übernommen haben. Zerstreut ihre Knochen und bringt uns ihre eitrigen Klauen, dann werden die Todeswachen Euch entlohnen.", sourceObjective = "Bringt 7 eitrige Klauen zu Todeswache Dillinger auf dem Verlassenen Anwesen.", progress = "Habt Ihr die Aufgabe erledigt, die ich Euch auftrug? Habt Ihr die eitrigen Klauen?", completion = "Gut gemacht. Es hat Spaß gemacht, Euch zuzusehen, wie Ihr diese Untoten zu Brei geschlagen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25091] = { id = 25091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandmarterwache", description = "Wenn Ihr nach mehr Arbeit sucht, dann hab ich was für Euch.\n\nIch kenne einen Elfen namens Trenton Lichthammer, der seit Jahren von den Sandtrollen in der Nähe von hier besessen ist. Er ist darauf festgefahren, eine Art magisches Schwert der Trolle zu finden und vor Kurzem hat er tatsächlich Helfer gefunden, die mit ihm zum Suchen zur Sandmarterwache sind.\n\nMeine letzte Information ist, dass sie die Trolle verjagt und ein Lager errichtet haben. Sucht westlich von hier nach ihnen, in der Nähe von Zul'Farrak.", sourceObjective = "Sprecht mit Trenton Lichthammer in Sandmarterwache.", completion = "Marin schickt Euch? Ich bin über seine Hilfe sehr dankbar.\n\nIch bin hier, um Sul'thraze zu finden. Wenn Ihr mir helfen wollt, so sprecht mit Mazoga... er war bisher sehr hilfsbereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25093] = { id = 25093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Köpfe des SI:7", description = "Diese Orcs an der Küste wurden von der Allianz kaltblütig ermordet. Wir haben nichts getan, um sie zu provozieren.\n\nIhr Tod soll nicht ungesühnt bleiben, {name}. Werdet Ihr für Gerechtigkeit sorgen?\n\n<Es scheint, als könne Aggra ihre Wut kaum zurückhalten.>\n\nUnten am Strand halten sich drei Anführer des SI:7 auf. Bringt mir ihre Köpfe!", sourceObjective = "Sammelt die Köpfe von Kommandant Arrington, Dunkelklinge Cyn und Alexi Stummheuler.", progress = "Habt Ihr der Gerechtigkeit Genüge getan?", completion = "Vielen Dank, {name}. Endlich können die Seelen der Gefallenen Ruhe finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25094] = { id = 25094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkuppel: Zumonga!", description = "Ausgezeichnet, gut gemacht! Ihr werdet hier aber nicht nur einfache Menschen bekämpfen!\n\nEuer nächster Gegner ist ein ganz heftiger... Nehmt Euch vor seiner Rechten in Acht. Und seiner Linken. Also überhaupt vor seinen Fäusten.", sourceObjective = "Besiegt Zumonga.", completion = "Nicht schlecht. Ihr seid aber noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25095] = { id = 25095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkuppel: Sarinexx!", description = "Ich hoffe, Ihr seid bereit für Euren nächsten Gegner, {name}. Nur ein Fehler entspricht einem schmerzvollen, sofortigen Tod! Aber genau dafür zahlen die Leute, nicht wahr?\n\nIch hoffe, Ihr habt kein Problem mit Insekten...", sourceObjective = "Besiegt Sarinexx.", completion = "Beeindruckend. Nur wenige können einem Silithidenhäscher gegenüberstehen und auch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25098] = { id = 25098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshäuptling braucht Euch", description = "Thrall hält sein Wort und bringt uns auf den richtigen Weg, um unser Volk zu retten. Er will mit Euch sprechen.\n\nViel Erfolg, {name}. Unser Leben liegt in Eurer Hand.", sourceObjective = "Sprecht mit Thrall am Spähposten des Kriegshäuptlings auf den Verlorenen Inseln.", completion = "Und wieder habt Ihr uns geholfen, unseren gemeinsamen Feind zu überwältigen, die Allianz.\n\nJetzt ist es an der Zeit, dass wir Euch helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25099] = { id = 25099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borgt Euch Bastia aus", description = "Geht zurück zur Küste und sagt Kilag, dass Ihr Euch in meinem Auftrag Bastia ausborgen sollt. Der Panther weiß, wo Eure Freunde gefangen gehalten werden.\n\nGeht jetzt. Ich werde Euch wiedersehen, bevor wir unsere Initiative gegen den Handelsprinz einleiten.", sourceObjective = "Sprecht mit Kilag Blutmaul an der Stillen Küste auf den Verlorenen Inseln.", completion = "Natürlich könnt Ihr Euch Bastia ausborgen. Das heißt, wenn sie sich das gefallen lässt.\n\n<Kilag zwinkert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25100] = { id = 25100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsitzen!", description = "Bastia bringt Euch sicher dorthin, wo Ihr hin wollt, Goblin.", sourceObjective = "Sprecht mit Slinky Scharfklinge an den Himmelsfällen auf den Verlorenen Inseln.", completion = "{name}?! Nettes Kätzchen!\n\nWir haben nicht viel Zeit. Vielleicht ist Euch ja schon aufgefallen, dass der Vulkan Feuer spuckt?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25102] = { id = 25102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Bullen", description = "Doppelzopfs Patrouillengänge bringen uns jedes Mal in große Gefahr. Wenn es nicht die Hinterhalte der Horde sind, ist es ein blitzartiger Überfall der Stacheleber.\n\nDas Problem sind diese lausigen Landbeberkodos. Riesige laufende Mauern aus Fell, bei denen die Erde bebt... Wir können einen Hinterhalt weder hören noch sehen, wenn er sich hinter unserem Rücken nähert.\n\nGeht und jagt ein paar von ihnen in die Flucht. Wenn Ihr einige von ihnen tötet, wird die Herde wohl wieder in den Süden ziehen und nicht länger auf meinen Nerven herumtrampeln.", sourceObjective = "Tötet 4 Landbeberkodos und 1 Landbeberbulle im Südlichen Brachland.", completion = "Ich dachte, Ihr steckt vielleicht hinter den Staubwolken, die ich im Osten sah. Gute Arbeit! Diese Bullen sind nicht feige.", sourceObjectiveStatus = "unverified-source-field" }
quests[25103] = { id = 25103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmugglerposten", description = "Wir haben hier erstklassige Arbeit geleistet. Ich werde dafür sorgen, dass diese Schießbudenfiguren hier anständig aufräumen und werde dann für eine Weile nach Gadgetzan zurückkehren.\n\nWenn Ihr noch mehr Eindruck auf unsere Freunde vom Dampfdruckkartell schinden, oder einfach nur noch mehr Geld verdienen wollt, solltet Ihr von hier aus nach Südwesten gehen. Der Schmugglerposten befindet sich am Rand der Klaffenden Schlucht.\n\nSprecht mit Zeke Scheuerschuh. Ich würde gutes Geld darauf verwetten, dass er Hilfe braucht.", sourceObjective = "Sprecht mit Zeke Scheuerschuh am Schmugglerposten.", completion = "Ihr gehört also zu Megs, hm? Es geht das Gerücht um, dass sie sich mit Noggenfogger auf Teufel komm raus gutstellen will.\n\nNaja, was kümmert es mich. Seid Ihr bereit, ein paar Wanzen zu töten?", sourceObjectiveStatus = "unverified-source-field" }
quests[25104] = { id = 25104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustand der Grabungsstätte", description = "Die Patrouille war heute wirklich ruhig. Das bereitet mir Sorgen, {name}.\n\nSeit die Allianz Taurajo geplündert hat, sind unsere Standorte nicht mehr sicher. Ihr seht so aus, als ob Ihr allein zurechtkommt - könntet Ihr Euch für mich umsehen?\n\nMeldet Euch bei meinem Sohn Marley außerhalb der Ausgrabungsstätte von Bael Modan im Südosten von hier. Die Grabungsstätte ist ungeschützt und ein leichtes Ziel für Überfälle, und mein Sohn ist zu stolz, um nach Hilfe zu fragen, wenn er sie benötigt.", sourceObjective = "Findet Marley Doppelzopf außerhalb der Ausgrabungsstätte von Bael Modan im Südlichen Brachland.", completion = "Vater hat Euch geschickt? Er macht sich zu viele Sorgen. Hier gibt es nichts, das ich nicht bewältigen könnte...\n\nDennoch weiß ich die Hilfe zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25105] = { id = 25105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibbler! Nein!", description = "Lilas Haustier Nibbler ist schon wieder in meine Werkstatt gelangt!\n\nIch war dabei, einen Armreif herzustellen und er sollte heute geliefert werden. Die Arbeit war fast beendet, bis auf ein paar Edelsteine. Ich habe die ganze Nacht damit zugebracht, sie zu schleifen, doch als ich kurz vor die Tür gegangen bin, um zu frühstücken, ist das kleine Biest in die Werkstatt gekommen und hat jeden Edelstein in Reichweite geschluckt! Das Ding kann ALLES verdauen und glaubt mir, Ihr würdet Euch den Rücken brechen bei dem Versuch, seine Hinterlassenschaften aufzusammeln.\n\nIch brauche schnell Ersatzedelsteine; der Kurier kommt heute Abend. Hilfe!", sourceObjective = "Schleift drei gediegene Zephyrite und gebt sie Isabel Jones in Sturmwind.", progress = "Habt Ihr die gediegenen Zephyrite, die ich brauche?", completion = "Ihr habt wirklich meine Haut gerettet, {name}. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[25106] = { id = 25106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hände weg von meiner Grabung!", description = "Schaut Euch das Chaos hier unten an, {name}! Ich habe die Vorarbeiter angewiesen, so viele Artefakte, wie möglich, zu retten. Wer weiß, mit welchen Schätzen diese Taurentiere sich gerne aus dem Staub machen würden.\n\nKönnt Ihr mir helfen, die Dinge in den Griff zu bekommen? Tötet die Plünderer und rettet so viele Artefakte, wie möglich.\n\nWenn Ihr schon dabei seid, haltet Ausschau nach meinen verschwundenen Werkzeugen. Einige schnelle Reparaturen und ich kann diese Flugmaschine wieder flugfähig machen.", sourceObjective = "Tötet 8 Räuber der Ausgrabungsstätte, rettet 5 Artefakte aus Bael Modan und findet Doppelzopfs Werkzeuge in der Ausgrabungsstätte von Bael Modan.", progress = "Wie ist die Situation hier unten, {name}?\n\nAls der Überfall losging, habe ich ihrem Anführer Steinbuckel eine Kugel verpasst, aber er kam immer weiter auf mich zu.", completion = "Mein Vater wäre sehr stolz auf Euch, {name}.\n\nUnd jetzt muss ich diese Flugmaschine wieder in Gang bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25107] = { id = 25107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Tafel", description = "Auf dem Boden der Truhe findet Ihr eine große Tafel. Das Material scheint Stein zu ähneln, ist aber ganz sanft und fein anzusehen und mit seltsamen Schriften versehen.\n\nEin Teil der Schrift ist der gleiche wie an den Mauern, doch es sind auch andere Schriften darauf zu finden. Andoren wird sich sicherlich dafür interessieren.", sourceObjective = "Bringt die große Tafel zu Andoren Morgendunst.", progress = "Ihr seid zurück! Was habt Ihr gefunden?", completion = "Das ist wirklich unglaublich. Die Hieroglyphen sind zweifellos von den Titanen, aber die Markierungen darunter...\n\nEinige der Zeichen sehen aus wie die uralten Schriften der Kaldorei. Und die Vorkammer war voller Hieroglyphen, sagt Ihr?\n\nWas Ihr gefunden habt ist weitaus wichtiger als jegliche Reichtümer, {name}. Bitte, nehmt Euch eine Belohnung, die Ihr angemessen findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25108] = { id = 25108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feegly der Verbannte", description = "Das ist die traurigste Geschichte, die ich je gehört habe, {name}. Feegly war einer unserer schnellsten Gräber, bis er an dieses... Ding... geraten ist. Die \"Träne der Monde\" nennen wir es. Sie hat ihn verändert. Umgewandelt. Ich wünschte, sie wäre nie ausgegraben worden.\n\nFeegly wurde aus Bael Modan verbannt, aber ich hörte Berichte, dass er wieder in der Nähe der Grabungsstätte herumschnüffelt. Das bemitleidenswerte Ding hat genug gelitten. Wenn Ihr ihn dort unten findet, erlöst ihn von seinem Elend.", sourceObjective = "Tötet Feegly den Verbannten in der Ausgrabungsstätte von Bael Modan.", completion = "<Marley nickt grimmig.>\n\nJa, ich denke, es ist am Besten so.", sourceObjectiveStatus = "unverified-source-field" }
quests[25109] = { id = 25109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gallywix' Fronmine", description = "Wir sind gerade so mit heiler Haut entkommen!\n\nDer Handelsprinz hat einen ganzen Haufen von uns versklavt und lässt uns in seiner Höhle schuften. Er nennt es Gallywix' Fronmine.\n\n<Slinky schnaubt.>\n\nGreely hat uns sieben bei der Flucht geholfen, aber dabei wurde sie selbst gefangen genommen.\n\n{name}, Ihr seid <der Einzige, der/die Einzige> die; verrückt genug ist, um in einen explodierenden Vulkan hineinzuspazieren! Die Assistentin wird Euch dabei helfen, die anderen zu befreien.\n\nSchnell! Dieser Ort geht gleich endgültig in die Luft!", sourceObjective = "Sprecht mit Assistentin Greely in Gallywix' Fronmine auf den Verlorenen Inseln.", completion = "<Die Assistentin sieht Euch verwirrt an.>\n\nHä… was? Wer?", sourceObjectiveStatus = "unverified-source-field" }
quests[25110] = { id = 25110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Cola! Hier kommen die IDEEN (TM)", description = "Assistentin Greely sieht eindeutig verwirrt und verängstigt aus. Wie soll sie Euch in diesem Zustand nur helfen, alle zu retten?\n\nVielleicht hilft ja ein Schluck von diesem Kaja'Cola minus eins, das Ihr gesehen habt. Das sollte sie auf Ideen bringen!", sourceObjective = "Sammelt 1 Kaja'Cola minus eins.", progress = "Häh?", completion = "<Assistentin Greely sieht die Kaja'Cola minus eins in Eurer Hand und ihre Augen leuchten lebhaft.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25111] = { id = 25111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwerter zur Wiederverwertung", description = "Jetzt, wo ich weiß, dass Ihr nicht zimperlich seid, habe ich noch mehr Arbeit für Euch. Habt Ihr die Vögel mit den roten Federn gesehen, die um die Knochen schwärmen? Es sind Feuerrocs. Sie können Euch in Flammen setzen, wenn Ihr nicht aufpasst.\n\nAufgrund ihres außerordentlichen Körperbaus sind sie auch verdammt wertvoll. Die meisten Jäger sind nicht in der Lage, für gutes Gold Feuer spuckende Bussarde zu töten... seid Ihr es?", sourceObjective = "Benutzt den Schlächterbot, um 12 tote Feuerrocs auszuschlachten.", completion = "Alchemisten müssen für diese Ware tief in die Tasche greifen. Vielleicht könnte ich manchen versuchen, sie als Drachenteile zu verkaufen, aber das ist auch nicht mein Problem, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25112] = { id = 25112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlächterbot", description = "Ich verdiene mein Gold mit dem Verkauf von Tierteilen und habe eine idiotensichere Methode zur Gewinnmaximierung perfektioniert: den Schlächterbot!\n\nSchlächterbots sind situationsabhängig darauf programmiert, um auch das kleinste Stückchen wiederverwertbarer Materialien von den Wildtieren aus der Umgebung zu erhalten. Schlächterbot verrichtet die ganze Arbeit und das Beste daran ist, dass nur ich weiß, wie man die Waren aus ihm herausbekommt.\n\nWenn Ihr Euch auch ein paar Münzen verdienen wollt, könnt Ihr mit einem der Schlächterbots losziehen. Ich brauche Teile von Glashautbasilisken - Ihr findet sie südlich von hier.", sourceObjective = "Benutzt den Schlächterbot, um 10 Kadaver von Glashautbasilisken auszuschlachten.", completion = "Gute Arbeit, Kind. Auch keine Finger verloren? Gut, dann können wir Euch mit mehr Arbeit versorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25115] = { id = 25115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiterpfotenschlachtung", description = "Die Hyänen sehen zwar so aus, als sei nichts an ihnen dran, aber sie haben die stärksten Kiefer, die Ihr finden könnt! Wenn Ihr nicht aufpasst, können sie Euch mit einem Biss ein Bein abreißen. Knochenstärke wie diese ist wertvoll, man muss nur die richtigen Käufer finden!\n\nNehmt einen der Schlächterbots. Kieferspaltung ist nicht einfach, aber der Kleine wurde so programmiert, dass er genau weiß, was zu tun ist. Bringt ihn zu mir zurück, wenn er voll ist.", sourceObjective = "Benutzt den Schlächterbot, um 10 Kadaver von Eiterpfotenhyänen auszuschlachten.", completion = "Wunderschön! Diese Schönheiten machen wir noch schön sauber und dann sind sie in kürzester Zeit zum Verkauf bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25118] = { id = 25118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach den Lauerern schauen", description = "Ich weiß nicht, wie es Euch geht, aber Spinnen mag ich gar nicht, und die, die größer sind als ich, erst recht nicht. Loch Modan ist ein wunderschöner Ort, aber ohne diese furchtbaren Spinnentiere überall wäre es doch schöner.\n\nPasst auf, ich habe ein paar Münzen übrig, und Ihr seht stark aus. Wenn Ihr für mich ein paar dieser Viecher erledigt, werde Ich Euch für die Zeit entlohnen, die Ihr investiert habt.", sourceObjective = "Tötet 8 Waldlauerer.", completion = "Ich werde sicherlich besser ruhen können, nun da ich weiß, dass diese Dinger mich nicht mitten in der Nacht heimsuchen... wieder heimsuchen werden. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[25120] = { id = 25120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marleys letzter Flug", description = "Okay, {name}! Lasst uns diese Artefakte zu meinem Vater zurückbringen und ihm aus erster Hand Bericht erstatten.\n\nDank Eurer Hilfe ist meine Flugmaschine jetzt wieder einsatzbereit. Wir können zusammen dorthin fliegen und uns den Ruhm teilen.\n\nSprecht mich an, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Sprecht mit Marley Doppelzopf und akzeptiert einen Flug in seiner Flugmaschine.", completion = "<Der übel zugerichtete Zwerg hängt schlaff im Cockpit. Ihr nähert Euch dem brennenden Wrack und seine Augenlider öffnen sich flatternd.>\n\n<Marley Doppelzopf lebt noch!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25121] = { id = 25121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momentum", description = "Wir haben wohl noch mehr Arbeit zu tun! Dass Herr Noggenfogger uns gebeten hat, den Rest der Piraten zu beseitigen, ist eine wahre Ehre.\n\nIhr wart bisher SOO hilfreich, warum kommt Ihr nicht und trefft mich in der Mast- und Schotbucht? Ich muss mir nur etwas gemütlichere Kleidung überziehen, also wartet nicht hier auf mich. Ich hole Euch sowieso ein, versprochen!", sourceObjective = "Trefft Kelsey Stahlfunken in der Mast- und Schotbucht.", completion = "Hallo auch! Wir haben schon angefangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25122] = { id = 25122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moralschub", description = "Ihr müsst die gesamte Kaja'Cola minus eins sammeln, die Ihr in die Finger bekommt! Bringt die Goblins dazu, sie zu trinken, damit sie einen Moralschub erhalten und sich befreien!", sourceObjective = "Benutzt die Kaja'Cola minus eins, um Ass, Izzy, Gobber und 6 überlebende Goblins oder Bürger von Kezan zu befreien.", completion = "Ich hasse den Handelsprinzen, aber über die Ergebnisse seiner Methoden lässt sich nicht streiten. Die Kaja'Cola minus eins ist eine deutliche Verbesserung im Vergleich zur herkömmlichen Kaja'Cola. Halb so viele Kalorien, doppelt so viele Ideen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25123] = { id = 25123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft ihn zu Boden!", description = "Dieser Alptraum findet nie ein Ende, solange Knallschatten der Tiermeister noch atmet. Dabei gibt es jedoch ein paar Probleme.\n\nZum einen hat er als Hexenmeister eine Sukkubus namens Delicia Peitschenknall bei sich. Wenn Ihr Knallschatten schnell erledigt, kehrt der Dämon wieder dorthin zurück, von wo er beschworen wurde.\n\nDas zweite Problem ist der Seelenstein, mit dem Knallschatten sich als Hexenmeister wiederbeleben kann. Ihr müsst seinen Seelenstein an Euch nehmen und ihn zerstören, sodass er für immer tot bleibt!", sourceObjective = "Vernichtet Knallschattens Seelenstein.", completion = "Euer Seelenstein ist abgelaufen, Knallschatten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25125] = { id = 25125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht am Ende des Tunnels", description = "In Ordnung, wir müssen hier weg, bevor die Mine endgültig in die Luft fliegt!\n\nLasst uns aus dem anderen Ende des Tunnels an der Nordseite der Mine fliehen. Wir sollten einen der Minenwagen benutzen können, um schnell an der Seite des Vulkans herunterzurasen.", sourceObjective = "Bedient den Minenwagen außerhalb von Gallywix' Fronmine auf den Verlorenen Inseln.", completion = "Sieht ein wenig klapperig aus…", sourceObjectiveStatus = "unverified-source-field" }
quests[25126] = { id = 25126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfe Zähne", description = "Als erstes müssen wir Euch ein wenig Selbstvertrauen lehren. Ich könnte Euch ins Brachland auf die Kodojagd schicken, aber ehrlich gesagt, nützt Ihr uns lebend mehr als tot.\n\nEs wäre wohl besser, wenn Ihr erst einmal die Eber abschlachtet, die es auf den Höfen nördlich und nordöstlich von hier gibt.", sourceObjective = "Tötet 6 scheckige Eber.", completion = "Aber lasst Euch das nicht zu Kopfe steigen... Ihr werdet in Eurer Karriere vor schwierigeren Gegnern als Ebern stehen.\n\nTrotzdem habt Ihr Euch bewiesen. Eure nächste Prüfung wird Euch zu einem gefährlicheren Gegner führen, deshalb benötigt Ihr zusätzlichen Schutz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25127] = { id = 25127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stich des Skorpiden", description = "Ich muss Euch zurück ins Feld schicken, {class}. Ihr werdet nordwestlich von hier viele Skorpide finden. Bringt mir 8 ihrer Schwänze.\n\nDas Gegengift für ihren Stich wird aus dem Gift gemacht, das aus ihren Stacheln extrahiert wird. Wir halten immer große Mengen Gegengift für Skorpidgift bereit, um Neulinge wie Euch zu heilen...\n\nAber ich bin sicher, dass Ihr nichts davon brauchen werdet, nicht wahr?", sourceObjective = "Beschafft 8 Skorpidarbeiterschwänze.", progress = "Der Panzer eines Skorpids ist nicht so dick, dass die Stärke eines entschlossenen Kriegers davon abgehalten würde. Schlagt hart und ohne Zögern zu, und die Skorpide werden leichte Beute abgeben.", completion = "Es gibt eine wichtige Lektion, die Ihr aus dem Kampf mit Skorpiden lernen müsst. Die kleinsten oder größten Eurer Feinde können Euch ins Verderben schicken. In heftigen Kämpfen kann Euch viel zum Straucheln bringen.\n\nIch habe Euch nichts mehr beizubringen, {name}. Ihr habt Euch gut geschlagen, und ich werde Eure Fortschritte mit Interesse verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25128] = { id = 25128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hana'zua", description = "Hey, Mann, macht mal Pause und hört mir zu. Wir haben ein Problem. \n\nHana'zua, ein guter Freund von mir, ist ins Tal hinausgegangen und nicht wieder zurückgekehrt. Als ich ihn das letzte Mal sah, ging er nach Norden, wo die Skorpide jagen. Vielleicht könnt Ihr nach ihm suchen gehen? Die Geister haben mir gesagt, dass es ihm nicht gut geht.", sourceObjective = "Findet Hana'zua im Tal der Prüfungen.", completion = "<Hana'zua stöhnt vor Schmerzen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25129] = { id = 25129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkoth", description = "{class}! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte seiner Schere einen ordentlichen Hieb versetzen, bevor sie sich um mein Bein schloss.\n\nIch hatte jedoch nicht mit seinem Stachel gerechnet, der auf meine Brust niederfuhr, sich in mein Fleisch grub und großen Blutverlust verursachte. Bitte, Ihr müsst den Skorpid für mich töten! Meine Ehre darf nicht besudelt werden! Da oben auf dem Plateau im Süden habe ich gegen ihn gekämpft.", sourceObjective = "Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", progress = "Ah... mein Vater sagte immer, aus mir würde nie etwas werden. Ich fürchte, so, wie ich hier unter dem Baum liege, während mein Leben mir zwischen den Fingern zerrinnt, sieht es aus, als hätte er Recht gehabt.\n\nIch wünsche mir nur, mit dem Wissen sterben zu können, dass mein letzter Feind in diesem Leben tot ist.", completion = "Mein Schlag war nicht stark genug, um ihn zu töten, aber wenn ich mir den Schaden ansehe, den ich verursacht habe, macht es mich doch ein bisschen stolz. Mit diesem bisschen Stolz muss ich mich zufrieden geben, wenn ich sterbe; doch in diesem Licht betrachtet, erfüllt mich die kurze Liste meiner im Leben erreichten Leistungen mit Wut.", sourceObjectiveStatus = "unverified-source-field" }
quests[25130] = { id = 25130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Höhlenbau", description = "Zu sehen, was Ihr für mich getan habt, gibt mir neuen Mut. Ich kann nicht so einfach fallen! Ich muss durchhalten!\n\nAber es ist noch immer so, dass ich die Reise zurück in unsere Siedlung nicht ohne Hilfe überstehen werde. Bitte, {name}, kehrt zurück und berichtet Gornek von meiner Situation. Vielleicht kann er mir helfen.", sourceObjective = "Überbringt Gornek im Tal der Prüfungen die Nachricht von Hana'zuas Notlage.", completion = "Eurer Beschreibung des Biests nach muss es sich um Sarkoth handeln! Kein Wunder, dass Hana'zua von ihm besiegt wurde. Ihm wird sofort Hilfe geschickt. Kümmert Euch nicht weiter um Hana'zuas Situation.\n\nIch muss jedoch sagen, dass ich davon beeindruckt bin, dass Ihr Sarkoth getötet habt. Das ist eine Tat, auf die man stolz sein kann, {name}. Und dass Ihr für die Ehre eines Anderen gekämpft habt obwohl andere Aufgaben Eure Zeit in Anspruch nahmen, mehrt Eure eigene Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[25131] = { id = 25131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üble Familiare", description = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, {class}.\n\nMan hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...\n\nEin Anhänger der Brennenden Klinge - ein widerwärtiger Kult von Dämonenanbetern - hat hier im Tal der Prüfungen sein Lager aufgeschlagen. Er lungert in einer Höhle im Norden herum und seine üblen Familiare kriechen daraus hervor, um Chaos anzurichten.\n\nAls erste Aktion gegen die Brennende Klinge bitte ich Euch, diese Familiare zu vernichten. Tötet so viele Ihr könnt und falls Ihr überlebt, kehrt zu mir zurück.", sourceObjective = "Tötet 8 üble Familiare.", completion = "Das habt Ihr gut gemacht, {name}.\n\nDie elenden Familiare waren zwar nur Schoßtiere der dunkleren Mächte der Brennenden Klinge, aber Euer Sieg über sie lässt mich ahnen, dass noch größere Taten folgen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25132] = { id = 25132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medaillon der Brennenden Klinge", description = "Durch meine Visionen sehe ich einen mächtigen Gegenstand - ein Medaillon - tief im Koven der Brennenden Klinge, bewacht von Monstern und schwarzer Magie. Wir müssen es haben.\n\nDiese Dämonenanbeter haben unsere Heimat schon zu lange entweiht. Läutert den Koven von seiner dämonischen Verderbnis, indem Ihr die Teufelsbestien und ihren Anführer tötet. Kehrt mit dem Medaillon als Beweis Eurer Tat zurück.\n\nGeht, {name}. Ihr werdet den Koven in einer Höhle nördlich von hier finden.", sourceObjective = "Tötet 7 Teufelspirscher und bringt das Medaillon der Brennenden Klinge an Euch.", progress = "Habt Ihr Eure Aufgabe vollendet, {name}?", completion = "Ihr habt es! Gut gemacht!\n\nEure Bemühungen im Koven der Brennenden Klinge sind der Schlüssel für die Ausrottung dieses Kults im Tal der Prüfungen. Ich fürchte jedoch, dass sie in unserem Land noch mehr vorhaben.\n\nNoch sind wir sie nicht endgültig los.", sourceObjectiveStatus = "unverified-source-field" }
quests[25133] = { id = 25133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht erstatten in Sen'jin", description = "Eure Prüfungen gegen die Brennende Klinge sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.\n\nBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.\n\nBerichtet Gadrin von der Brennenden Klinge und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.\n\nGeht, {name}, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Brennenden Klinge entdeckt haben, nur der Vorbote eines viel größeren Übels ist...", sourceObjective = "Sprecht mit Meister Gadrin in Sen'jin.", completion = "Hm... Euer Bericht kommt zu einem schlechten Zeitpunkt. Kultisten der Brennenden Klinge wurden hier in Sen'jin nicht mehr gesichtet, aber wir werden weiterhin auf der Hut sein, dass sie hier nicht wieder Fuß fassen können.\n\nDie Orcs sind Freunde der Dunkelspeertrolle. Ehrenhafte Freunde. Wir wollen den Orcs helfen, aber... wir benötigen ebenfalls Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25134] = { id = 25134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faule Peons", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, {race}. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nHaltet unter den Bäumen im Tal nach ihnen Ausschau. Verdammte faule Peons...", sourceObjective = "Benutzt den Totschläger des Großknechts an 4 faulen Peons, wenn sie schlafen.", progress = "Verdammter fauler B...\n\nHuch? Habt Ihr meinen Totschläger? Habt Ihr Peons dabei erwischt, wie sie bei der Arbeit schliefen?!", completion = "Gut, gut. Vielleicht werden sie es sich in Zukunft zweimal überlegen, bevor sie wieder nachlässig werden! Ich danke Euch für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25135] = { id = 25135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thazz'rils Hacke", description = "{name}, Ihr seid <ein/eine:r> {race}, auf <den/die:r> man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?\n\nVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Brennenden Klinge, und meine Hacke holen?\n\nIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", sourceObjective = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", progress = "Habt Ihr den Koven der Brennenden Klinge betreten, {name}? Und habt Ihr meine Hacke gefunden?", completion = "Prima, Ihr habt sie! Vielen Dank, {name}. Das ist meine Lieblingshacke! Wenn meine Peons irgendwann einmal fertig sind, diese Bäume zu fällen, finden wir vielleicht eine hübsche Höhle für den Bergbau!", sourceObjectiveStatus = "unverified-source-field" }
quests[25136] = { id = 25136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgars Kaktusapfel Surprise", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweiß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, {name}. Wenn Ihr mir 6 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", sourceObjective = "Sammelt 6 Kaktusäpfel.", progress = "Habt Ihr schon genug Kaktusäpfel eingesammelt?", completion = "Wunderbar, {name}! Wie versprochen, habt Ihr hier Euren Kaktusapfel Surprise - und noch ein bisschen was dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[25138] = { id = 25138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenpergament", description = "Ah, während Ihr weg wart, ist ein Pergament für Euch gekommen, {name}.\n\nLest es, wenn Ihr die Zeit habt. Wenn ich mich nicht irre, kommt es von Magierlehrerin Acrypha. Sie möchte mit Euch reden, wenn Ihr bereit seid.", sourceObjective = "Lest das Glyphenpergament und sprecht mit Acrypha im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25139] = { id = 25139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Ihr wisst bereits, wie man einen arkanen Schuss abfeuert. Gut. Aber wenn Ihr das tut, sinkt Euer Fokus. Um Fokus zurückzugewinnen, müsst Ihr zu einem anderen Fernangriff übergehen.\n\nGeht, sammelt mehr Erfahrung. Wenn Ihr das tut, erlernt Ihr einige neue Fähigkeiten. Die erste wird Euch helfen, Fokus zurückzuerlangen.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe und übt daran fünfmal den zuverlässigen Schuss.", completion = "Ihr lernt schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[25141] = { id = 25141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Fangen wir mit den Grundlagen an, ja? Ich bin der einzige Schurkenlehrer hier, also werdet Ihr von mir lernen müssen.\n\nGeht, sammelt mehr Erfahrung, findet heraus, wie Ihr Eure Gegner ausweiden könnt und zeigt es mir dann an den Trainingsattrappen hier. Ich werde Eure Leistung dann bewerten.", sourceObjective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Findet eine Trainingsattrappe und übt daran dreimal die Anwendung von 'Ausweiden'.", sourceObjectiveStatus = "unverified-source-field" }
quests[25143] = { id = 25143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Während Ihr Kraft durch das Erklimmen neuer Stufen erlangt, werdet Ihr Macht erkennen, mit der Ihr neue Fähigkeiten nutzen könnt. Die erste dieser Fähigkeiten, die Ihr auf Eurer Reise entdeckt, ist der 'Urtümliche Schlag'.\n\nSetzt ihn ein, um mit Eurer Waffe einen Schlag zu führen, der mit der Macht der Elemente erfüllt ist.\n\nEs ist Zeit, Eure neue Fähigkeit zu erlernen und sie zu meistern. Übt an einer der Trainingsattrappen vor der Höhle.", sourceObjective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Findet eine Trainingsattrappe in Shikriks Nähe und übt daran dreimal die Anwendung von 'Urtümlicher Schlag'.", completion = "Sehrt gut. Jetzt, da Ihr wisst, wie man mit den Elementen spricht, testen wir Eure Verbindung mit ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25145] = { id = 25145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Es ist meine Pflicht, Euch auszubilden und ich gedenke, genau das zu tun.\n\nWenn Ihr mehr Macht erlangt, werdet Ihr die Teufelsstimmen hören, die Euch neue Zauber offenbaren.\n\nGeht, sammelt mehr Erfahrung, erlernt einen neuen Zauber und übt ihn dann an einer der Trainingsattrappen hier.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Findet eine Trainingsattrappe und wirkt fünfmal 'Verderbnis' auf sie.", completion = "Offenbar lernt Ihr schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[25147] = { id = 25147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmangriff", description = "Man hat mich angewiesen, Euch auf den Kampf vorzubereiten. Ihr seht allerdings aus, als hättet Ihr schon ein wenig Zeit auf dem Schlachtfeld verbracht. Gut.\n\nWährend Ihr Eure Reise fortsetzt, werdet Ihr erkennen, dass Ihr beginnen könnt, neue Techniken anzuwenden.\n\nGeht, sammelt Erfahrung und bringt Euch selbst den 'Sturmangriff' bei. Zeigt mir dann, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Sucht eine Trainingsattrappe und übt die Benutzung von 'Sturmangriff'.", progress = "Nach dem Training werden wir Eure Fähigkeiten überprüfen.", completion = "Versteht Ihr es jetzt? Gut, dann probiert es aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25149] = { id = 25149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Gut, kommen wir zum einfachen Teil.\n\nAlles, was Ihr tun müsst, um Eure Verbindung zum Arkanen zu vertiefen, ist, erfahrener zu werden und mehr Macht zu erlangen. Dann werdet Ihr feststellen, dass Ihr neue Zauber wirken könnt.\n\nIhr werdet sehen. Geht und probiert es aus und zeigt mir dann, was Ihr erlernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Findet eine Trainingsattrappe und übt den Zauber 2-mal daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[25151] = { id = 25151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er braucht Bier!", description = "<Marley umklammert mit zitternder, blutiger Hand eine Seite Eures Kopfes.>\n\nBier... Muss... Bier... trinken...\n\nHager-Bschorr von drinnen. <Er hustet.> Das sollte... helfen.", sourceObjective = "Durchsucht Burg Bael'dun nach einem Krug mit Hager-Bschorr und bringt ihn zu Marley Doppelzopf am Eingang.", progress = "<Marley atmet stoßweise und zittert keuchend.>\n\n<Sein Blick ist flehend auf Euch gerichtet.>", completion = "<Ihr rennt mit dem Bier auf Marley zu und seine Augen glitzern. Er ergreift den Krug mit beiden Händen und kippt trinkt gierig. Weißer Schaum quillt über seinen blutverschmierten Bart.>\n\nAh... das ist genau das Richtige. Hager-Bschorr... Ich danke Euch, mein Freund.\n\nDas wird all dies... ein wenig einfacher machen.\n\n<Er hustet ein letztes Mal und bricht über der zertrümmerten Steuerkonsole zusammen. Der halb leere Krug fällt zu Boden und sein Inhalt ergießt sich im Sand. Seine Augen brechen.>\n\n<Marley Doppelzopf ist tot.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25152] = { id = 25152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Platz in der Welt", description = "Endlich seid Ihr alt genug, {name}... alt genug, um im Namen der Horde zu kämpfen. Um für den Ruhm des Kriegshäuptlings Siege zu erringen.\n\nJa...\n\n<Kaltunk mustert Euch.>\n\nDoch, doch, Ihr eignet Euch.\n\nZweifellos wollt Ihr Euch einen mächtigen Drachen oder einen Dämon suchen und ihn mit bloßen Händen erwürgen, aber vielleicht ist es vernünftiger, wenn Ihr mit etwas weniger... Gefährlichem anfinget.\n\n<Kaltunk lacht.>\n\nMeldet Euch bei Gornek; der sollte Euch eine Aufgabe zuweisen können, die zu einem wie Euch passt, {class}. Er sitzt am Feuer direkt hinter mir.", sourceObjective = "Sprecht mit Gornek.", completion = "Wieder einer von Kaltunks Rekruten, was?\n\nEs ist wirklich schlecht um die Horde bestellt, wenn das das Beste ist, was wir auf die Beine stellen können. Einerlei. Wenn es so weit ist und wir erkennen, dass Ihr bereit seid, das Tal zu verlassen, werdet Ihr ein stolzer Krieger der Horde sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25153] = { id = 25153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bael'duns Rettung", description = "Hilfe! Ihr müsst etwas tun!\n\nEinige Zwerge sind noch drinnen... so viele... gefangen unter den Trümmern. Lebendig begraben. Die Flammen! Es ist ein Alptraum da drinnen. Wir wissen nicht, wie lange es noch dauert, bis das Dach einstürzt.\n\nBitte, {class}, Ihr müsst sie retten!\n\nRennt hinein. Benutzt die Notfallfeuerventile, um Euch vor den Flammen zu schützen. Ihr seid ihre einzige Hoffnung!", sourceObjective = "Begebt Euch in die Burg Bael'dun und rettet 10 Überlebende von Bael'dun aus den Trümmern.\n\nBenutzt die Notfallfeuerventile, um Euch vor den Flammen zu schützen.", completion = "Ihr seid eine Legende, {name}.\n\nDie anderen Überlebenden und ich werden noch Jahre von Euren Taten erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25154] = { id = 25154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Lila", description = "Ich versuche diese Handelsschiffskapitänin, Lila, zu beeindrucken. Ich habe an einer Halskette gearbeitet, die zu ihren wunderschönen violetten Haaren passt, aber die Edelsteine sind verschwunden! Sie waren hier, als ich sie gestern Abend meinem guten Freund Curver gezeigt habe. Wir haben Fusel getrunken und ich bin bewusstlos geworden - als ich wach wurde, waren die Edelsteine weg! Das müssen verdammt raffinierte Diebe gewesen sein, Curver hat nämlich nichts gesehen.\n\nIhr Schiff kommt heute Abend an und ich brauche dringend drei Nachtsteine, um ihr Geschenk zu vollenden. So helft mir doch!", sourceObjective = "Schleift drei zeitlose Nachtsteine und gebt sie Isabel Jones in Sturmwind.", progress = "Habt Ihr mir die Nachtsteine gebracht?", completion = "Danke! Ich bin sicher, dass ich diese Marith Lazuria aus Orgrimmar damit schlagen kann! Ich kann gar nicht abwarten, den Blick in ihrem schönen Auge zu sehen, wenn ich es ihr gebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25155] = { id = 25155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogermazonen in Stimmung", description = "Ich sollte heute eine Ladung Jaspis von Azeroth Express erhalten, aber ich habe gerade gehört, dass ihr Schiff auf einer winzigen Insel namens Ogerzonien aufgelaufen ist. Ich mache mir Sorgen um die Besatzung, da die gigantischen weiblichen Oger auf der Insel, wenn man den Gerüchten Glauben schenkt, entsetzliche Rituale an Männern durchführen, die auf ihre Insel stoßen. Meine Arbeit muss aber fortgeführt werden und wir brauchen diese Edelsteine. Ich habe viel über Eure Fertigkeiten als Juwelenschleifer gehört - könntet Ihr mir vor Ende des Tages drei gezackte Jaspise bringen?", sourceObjective = "Schleift drei gezackte Jaspise und gebt sie Isabel Jones in Sturmwind.", progress = "Habt Ihr mir die Edelsteine gebracht, die ich brauche?", completion = "Eure Arbeit ist so gut, wie man es sich erzählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25156] = { id = 25156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarglibber", description = "Statt der gewöhnlichen alten Methode, Edelsteine in Ringe und dergleichen einzusetzen, benutze ich eine innovative neue Methode. Ich klebe die Steine einfach mit Barnsworths Elementarkleber an! Der Professor braucht jedoch mehr Elementarglibber für eine weitere Ladung, und ich muss heute noch viele Edelsteine einsetzen. Könnt Ihr mir welchen besorgen?", sourceObjective = "Besorgt 10 Elementarglibber von beliebigen Cataclysm-Elementaren und bringt sie zu Isabel Jones in Sturmwind.", progress = "Habt Ihr mir den Elementarglibber mitgebracht?", completion = "Danke. Ähm. Einfach da drüben ablegen. Ich muss mir noch überlegen, wie ich meine Hand von diesem Gefäß löse.", sourceObjectiveStatus = "unverified-source-field" }
quests[25157] = { id = 25157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schrei!", description = "Professor Barnsworth arbeitet gerade an diesem neuen Sternenstaub. Da diese Saison in Sturmwind alles angesagt ist, was glitzert, bin ich mir sicher, dass man ihn uns auf dem Markt praktisch aus der Hand reißen würde. Aber der Juwelenschleiferverband erlaubt uns nicht, das Zeug unter die Leute zu bringen, bis wir ein paar Tests an humanoiden Lebewesen vorgenommen haben. Sie brabbeln irgendwas von Gefahren bei der Handhabung von magischem Staub und allerlei anderen Unsinn. Nun, ich schätze, wir müssen sie irgendwie bei Laune halten. Nehmt diese Tasche und testet den Sternenstaub No. 2 an humanoiden Testobjekten.", sourceObjective = "Testet den Sternenstaub No. 2 an 10 \"humanoiden Testobjekten\".", progress = "Und, wie lief der Test?", completion = "Was ist passiert? Wir sind ruiniert! Hmm. Nun, wenn man es genau nimmt... Vielleicht kann der Professor eine andere Verwendung dafür finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25158] = { id = 25158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibbler! Nein!", description = "Lilas Haustier Nibbler ist schon wieder in meine Werkstatt gelangt!\n\nIch war dabei, einen Armreif herzustellen und er sollte heute geliefert werden. Die Arbeit war fast beendet, bis auf ein paar Edelsteine. Ich habe die ganze Nacht damit zugebracht, sie zu schleifen, doch als ich kurz vor die Tür gegangen bin, um zu frühstücken, ist das kleine Biest in die Werkstatt gekommen und hat jeden Edelstein in Reichweite geschluckt! Das Ding kann ALLES verdauen und glaubt mir, Ihr würdet Euch den Rücken brechen bei dem Versuch, seine Hinterlassenschaften aufzusammeln.\n\nIch brauche schnell Ersatzedelsteine; der Kurier kommt heute Abend. Hilfe!", sourceObjective = "Schleift drei gediegene Zephyrite und gebt sie Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir die gediegene Zephyrite gebracht, die ich brauche?", completion = "Ihr habt mir wirklich die Haut gerettet, {name}. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[25159] = { id = 25159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schrei!", description = "Dr. Vernstrom arbeitet gerade an diesem neuen Sternenstaub. Da diese Saison in Orgrimmar alles angesagt ist, was glitzert, bin ich mir sicher, dass man ihn uns auf dem Markt praktisch aus der Hand reißen würde. Aber der Juwelenschleiferverband erlaubt uns nicht, das Zeug unter die Leute zu bringen, bis wir ein paar Tests an \"lebenden Organismen\" vorgenommen haben. Sie brabbeln irgendwas von Gefahren bei der Handhabung von magischem Staub und allerlei anderen Unsinn. Nun, ich schätze, wir müssen sie irgendwie bei Laune halten. Nehmt diese Tasche und testet den Sternenstaub No. 2 an humanoiden Testobjekten.", sourceObjective = "Testet den Sternenstaub No. 2 an 10 \"humanoiden Testobjekten\".", completion = "Was ist passiert? Wir sind ruiniert! Hmm. Nun, wenn man es genau nimmt... Vielleicht kann der Doktor eine andere Verwendung dafür finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25160] = { id = 25160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Lila", description = "Ich versuche diese Handelsschiffskapitänin, Lila, zu beeindrucken. Ich habe an einer Halskette gearbeitet, die zu ihren wunderschönen violetten Haaren passt, aber die Edelsteine sind verschwunden! Sie waren hier, als ich sie gestern Abend meinem guten Freund Curver gezeigt habe. Wir haben Fusel getrunken und ich bin bewusstlos geworden - als ich wach wurde, waren die Edelsteine weg! Das müssen verdammt raffinierte Diebe gewesen sein, Curver hat nämlich nichts gesehen.\n\nIhr Schiff kommt heute Abend an und ich brauche dringend drei Nachtsteine, um ihr Geschenk zu vollenden. So helft mir doch!", sourceObjective = "Schleift drei zeitlose Nachtsteine und gebt sie Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir die Nachtsteine gebracht?", completion = "Danke! Ich bin sicher, dass ich diese Isabel Jones aus Sturmwind damit schlagen kann! Ich kann gar nicht abwarten, den Blick in ihrem schönen Auge zu sehen, wenn ich es ihr gebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25161] = { id = 25161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogermazonen in Stimmung", description = "Ich sollte heute eine Ladung Jaspis von Azeroth Express erhalten, aber ich habe gerade gehört, dass ihr Schiff auf einer winzigen Insel namens Ogerzonien aufgelaufen ist. Ich mache mir Sorgen um die Besatzung, da die gigantischen weiblichen Oger auf der Insel, wenn man den Gerüchten Glauben schenkt, entsetzliche Rituale an Männern durchführen, die auf ihre Insel stoßen. Meine Arbeit muss aber fortgeführt werden und wir brauchen diese Edelsteine. Ich habe viel über Eure Fertigkeiten als Juwelenschleifer gehört - könntet Ihr mir vor Ende des Tages drei gezackte Jaspise bringen?", sourceObjective = "Schleift drei gezackte Jaspise und gebt sie Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir die Edelsteine gebracht, die ich brauche?", completion = "Eure Arbeit ist so gut, wie man es sich erzählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25162] = { id = 25162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarglibber", description = "Statt der herkömmlichen Methode, Edelsteine in Ringe zu fassen und so weiter, benutze ich eine innovative neue Methode. Ich klebe die Edelsteine einfach mit Vernstroms Elementarkleber an! Der Doktor braucht jedoch mehr Elementarglibber für eine weitere Ladung und ich muss eine Menge Steine einfassen. Könnt Ihr mir welchen besorgen?", sourceObjective = "Besorgt 10 Elementarglibber von beliebigen Cataclysm-Elementaren und bringt sie zu Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir den Elementarglibber mitgebracht?", completion = "Danke. Ähm. Einfach da drüben ablegen. Ich muss mir noch überlegen, wie ich meine Hand von diesem Gefäß löse.", sourceObjectiveStatus = "unverified-source-field" }
quests[25163] = { id = 25163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer war das?", description = "Sabotage! Es gibt keine andere Möglichkeit. Das ganze Munitionslager der Burg ist explodiert. Die Horde muss jemanden hineingeschmuggelt haben...\n\n{class}, wenn Ihr den Mumm habt, in den brennenden Alptraum zu laufen... sucht nach Hinweisen, wer uns das angetan hat. Der General wird es wissen wollen! Sucht nach einer Leiche der Horde in den Trümmern und geht dieser Katastrophe auf den Grund...", sourceObjective = "Sucht in Burg Bael'dun nach einer Leiche der Horde.", completion = "<Eine qualmende Leiche ist besonders auffällig in diesem Gemetzel. Der tote Goblin hält einen Bauplan der Burg mit seiner leblosen Hand umklammert...>\n\n<Die Goblins des Bilgewasserkartells. Sie stecken dahinter!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25164] = { id = 25164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ecke gedrängt", description = "Die Naga sind da, {class}! Helft uns dabei, sie abzuwehr'n!", sourceObjective = "Verteidigt das Lager des Irdenden Rings, bis die Naga sich zurückziehen.", progress = "Sie schein'n unermüdlich zu sein, aber wir werd'n sie zurückdräng'n!", completion = "Ich bin froh, dass Ihr hier wart, Mann.\n\nToshe sieht aus, als will er sie verfolg'n. Ihr solltet ihn'n helf'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[25165] = { id = 25165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Haken und Lächeln sollten Misstrauen hervorrufen", description = "Als Nächstes werden wir Gift von den Skorpionen holen, die hier überall herumrennen. Aber keine Sorge, Bom'bay passt auf, dass Euch nichts passiert!\n\nBom'bay hat ein großes Totem, das Ihr in den Boden stecken könnt, wenn der Skorpion angreift. Das Totem entzieht ihm das Gift, und Ihr lauft ganz normal und gesund wieder heim. Klingt das gut?", sourceObjective = "Erhaltet 6 Proben Skorpidtoxin, indem Ihr das Totem der Giftextraktion in der Nähe eines rasselnden Skorpids aufstellt.", completion = "Ja! Auf dieses Skorpidjuju hat Bom'bay gewartet! Jetzt machen wir Euch auch wieder heil, {class}.\n\nIhr kommt wieder zu Bom'bay, wenn Ihr Euch besser fühlen wollt. Bom'bay hat Zauber, die Euch gesund machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25166] = { id = 25166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän Schreckensbart", description = "Das macht wirklich Spaß, aber wir dürfen nicht vergessen, dass wir für Gnomeregan hier sind!\n\nWir haben den Kapitän der Südmeerfreibeuter auf einem seiner Boote südlich von hier entdeckt, dort, wo die Kämpfe stattfinden. Er ist ganz alleine und ungeschützt auf seinem kleinen Boot!\n\nWenn Ihr Euch um ihn kümmert werden wir den Rest der Piraten in Windeseile los sein.", sourceObjective = "Tötet Kapitän Schreckensbart.", completion = "Er hat einen Meeresriesen unter Kontrolle gehabt? Wenn wir das weiter untersuchen könnten...\n\nÄh, ich meine natürlich, das ist ja total verrückt! Zum Glück ist er jetzt weg, hurra! Herr Noggenfogger wird so erfreut sein.\n\nUnd hier ist eine nette, große Belohnung für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[25167] = { id = 25167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ketten durchbrechen", description = "Oh Mann, das is' nicht gut! Überhaupt nicht!\n\nThrall ist in See gestochen, Vol'jin kümmert sich um Sachen auf den Echoinseln und der alte Meister Gadrin wird hiergelassen, um sich um Sen'jin zu kümmern. Und dann? Dann kommen diese Menschen von der Feste Nordwacht und schlagen in unserem Gebiet Lager auf!\n\nZum Glück sind sie eben erst angekommen und noch mit dem Aufbau beschäftigt. Ihr könnt dem alten Gadrin helfen, indem Ihr ihre großen Vorratskisten zerstört und die Arbeiter tötet, die die Kisten schleppen. Ihr findet sie südwestlich von hier.", sourceObjective = "Zerstört 3 Vorratskisten aus Nordwacht und tötet 10 Träger der Nordwacht.", completion = "Wir haben ihre bisherigen Anstrengungen nichtig gemacht, aber hier sind sie immer noch. Wir müssen härter gegen sie vorgehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25168] = { id = 25168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal reinigen", description = "Nordwacht ist eine sehr gut verteidigte Festung südwestlich von hier, hinter dem Hafen. Es ist eine strategisch gelegene Festung, die für die Horde bisher schwer einzunehmen ist. Wir können wirklich nicht gebrauchen, dass die Menschen eine neue Nordwacht in Durotar aufsetzen.\n\nFegt durch das Tal im Westen und tötet diese Menschen, {name}. Zeigt ihnen die Macht und Wut von Sen'jin.", sourceObjective = "Besiegt 12 Trupps der Nordwacht am Vorposten der Nordwacht.", completion = "Ein gut geführter Kampf, {class}, doch ich habe Zweifel an unserer Effizienz. Diese Menschen sind immer noch hier.\n\nIhr habt allerdings mehr getan, als man von einem loyalen Mitglied der Horde einfach so verlangen kann. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25169] = { id = 25169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf gegen die Aggression der Nordwacht", description = "Diese Menschen westlich von hier sind nicht zum Zelten in Durotar. Die haben andere Pläne, und zwar keine netten! Sie wollen unsere Heimat einnehmen und unsere Schädel auf Piken sehen!\n\nAber nicht mit mir! Nein! Nicht mit Lar! Ich habe Familie hier in Sen'jin und werde verflucht sein, wenn jemand auch nur versuchen will, den Schädel von Tai'tasi auf eine Pike zu piken!\n\nDie Menschen haben ihre Pläne alle aufgeschrieben. Große Schriftrollen, schauen wichtig aus. Die werden wir verbrennen, bevor sie überhaupt erst dazu kommen, etwas Ähnliches zu tun.", sourceObjective = "Zerstört 3 Angriffspläne, die beim Vorposten der Nordwacht gelagert werden.", progress = "Zerstört diese Menschen, {name}.", completion = "Gute Arbeit, richtig heldenhaft! Ihr habt Sen'jin heute gute Dienste geleistet. Ganz Durotar habt Ihr heute gute Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25170] = { id = 25170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küstensäuberung", description = "Hey, Ihr da! Bom'bay stellt grad mehr Mojo her! Wollt Ihr ein Schlückchen kosten? Oh, davor muss ich aber eh erst noch ein paar Jujus besorgen!\n\nZuerst braucht Bom'bay was von dem Saft von den Krabbenviechern am Wasser. Oh, zeigt mir Eure Hände!\n\n<Bom'bay betrachtet Eure Hände ganz genau.>\n\nMh, bei Euren Händen braucht Bom'bay fünf Handvoll. Geht schon!", sourceObjective = "Erhaltet 5 Handvoll Kriechersekret.", progress = "Ihr bringt mir die Jujus und ich lasse Euch mein Mojo kosten.", completion = "Ja, man, das ist das gute Zeug. Jetzt brauchen wir noch andere Jujus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25171] = { id = 25171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterreiten", description = "Wir müssen unsere Verbündeten in Klingenhügel benachrichtigen. Die Menschen mögen heute besiegt worden sein, doch morgen werden sie wieder da sein und dann werden wir Hilfe von den Orcs brauchen.\n\nSprecht mit Jhash vor den Toren von Sen'jin. Er wird Euch mit seinen Wölfen nach Klingenhügel bringen. Sie kennen den Weg gut.", sourceObjective = "Sprecht mit Räuber Jhash, um nach Klingenhügel zu gelangen. Sprecht mit Gar'Thok, sobald Ihr angekommen seid.", completion = "Der Troll will, dass wir Hilfe schicken? Pff, das kann er vergessen. Ich habe meine eigenen Menschenprobleme, und selbst die sind gerade meine geringsten Sorgen.\n\nSen'jin liegt zwischen den Echoinseln und dem Tal der Prüfungen. Sicherlich wird der Alte Gadrin genügend junge Krieger finden, die ihm mit dem Einfall der Menschen helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25172] = { id = 25172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge in unserer Heimat", description = "Ihr seid nicht einfach ein weiterer Grünschnabel - Ihr scheint wirklich <ein/eine:c> {class} zu sein. Gut, denn das ist genau das, was ich brauche.\n\nVersucht, es für Euch zu behalten, denn ich möchte keine Panik verursachen... aber es gibt noch weitere Berichte über Menschen in der Nähe. Das ist eine ungeheuerliche Verletzung des Friedens, den wir mit dieser erbärmlichen Jaina Prachtmeer ausgehandelt haben! Wir können keine Menschen hier in Durotar dulden, erst recht nicht hier im Tal.\n\nIhr findet sie im Süden. Tötet sie schnell, bevor es noch mehr werden.", sourceObjective = "Tötet 7 Späher der Nordwacht.", completion = "Schnell und präzise ausgeführt. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25173] = { id = 25173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmer geht immer", description = "Burg Tiragarde liegt südöstlich von hier, an der Ostküste Durotars. Ihr seid wahrscheinlich auf Eurem Weg von Sen'jin daran vorbeigekommen. Die Burg ist mir schon seit Langem ein Dorn im Auge.\n\nMenschen aus Kul Tiras haben jahrelang in der Burg gelebt und jeden meiner Versuche, sie zu erobern, abgewehrt. Nach dem Kataklysmus war die Küste zerstört, und die Burg mitsamt allen Menschen verschwunden. Allerdings haben diese Ankömmlinge aus Nordwacht jetzt ihren Platz eingenommen!\n\n<Gar'Thok brüllt angesichts dieser erschwerten Umstände.>", sourceObjective = "Tötet 6 Marinesoldaten der Nordwacht, 6 Heckenschützen der Nordwacht und Leutnant Palliter in Burg Tiragarde.", completion = "Von Eurem Mut wird überall erzählt, {name}. Geschichten über Euren Sieg in Burg Tiragarde werden selbst in Orgrimmar erzählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25174] = { id = 25174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelzopf muss es wissen", description = "<General Doppelzopf wird die Einzelheiten dieses feigen Angriffs wissen wollen. Ihr sammelt die Beweise auf.>", sourceObjective = "Meldet Euch bei General Doppelzopf bei Doppelzopfs Patrouille im Südlichen Brachland.", completion = "Wie bitte? WIE BITTE?!!!\n\nBael'dun liegt in Trümmern? Leichen überall - nein. Nein!\n\n<Ihr beschreibt die Beweise, die Ihr am Ort des Geschehens vorgefunden habt.>\n\nDie Bilgewassergoblins also, ja? Die wollen Streit haben? Denen werden wir zeigen, was es heißt, Teil der Horde zu sein, und ob. Ich werde die Kriegsnarbe mit ihren Leichen füllen. Ich werde die Erde mit ihrem Blut tränken.\n\n<Doppelzopf packt Euch am Kragen.>\n\nGoblins. Werden. Sterben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25175] = { id = 25175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Nachrichten", description = "<Sanft schließt Ihr Marleys Augen.>\n\n<Jemand muss General Doppelzopf mitteilen, dass die Horde seinen einzigen Sohn getötet hat.>\n\n<Dieser Jemand seid Ihr.>", sourceObjective = "Überbringt General Doppelzopf bei Doppelzopfs Patrouille im Südlichen Brachland die schlechte Nachricht.", completion = "<General Doppelzopf schleudert seine Axt in den Schmutz. Seine Stimme ist ruhig, aber sein Körper zittert vor Unglaube und Wut.>\n\nDas war mein Junge, {name}. Mein einziger Junge.\n\nJetzt haben sie es persönlich gemacht, {class}. Persönlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25176] = { id = 25176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Situation ausnützen", description = "<Hey, Hübscher! Ich bewundere Euren großen, fleischigen, starken Bizeps schon, seit Ihr in die Stadt gekommen seid!/Was schaut Ihr denn> hässliche Schachtel! Ich weiß, wie Ihr durch Klingenhügel stolziert und versucht, mir MEINE Männer auszuspannen!;\n\nHört her, ich habe etwas für Euch zu tun. Ich habe gehört, dass Gar'Thok Euch nach Tiragarde geschickt hat. Während Ihr dort seid, könntet Ihr für mich vielleicht ein paar der verlorengegangenen Sachen von Kul Tiras besorgen?\n\n<Danke, Süßer!/Fragt nicht> wieso. Ihr könnt froh sein, dass ich überhaupt mit Euch rede!;", sourceObjective = "Erhaltet 6 Stücke vom Schatz von Kul Tiras.", progress = "<Gail schnurrt entwaffnend wie ein Kätzchen, als sie Euch sieht.>", completion = "Ihr habt mir den Schatz gebracht! Oh, Ihr seid selber so ein Schatz!", sourceObjectiveStatus = "unverified-source-field" }
quests[25177] = { id = 25177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strände stürmen", description = "Jetzt sind die Menschen erstmal aus dem Weg und wir können uns um richtig wichtige Sachen kümmern.\n\nDer Kataklysmus hat die Ostküste Durotars äußerst stark mitgenommen. Ihr habt selbst gesehen, was aus Tiragarde geworden ist. Und an der Küste östlich von hier ist das Ausmaß noch weitaus schlimmer.\n\nNach der ersten Schockwelle wurde der Strand von wütenden Elementaren eingenommen, die aus dem Meer kamen. Ich habe Grunzer geschickt, um sich um sie zu kümmern, aber es waren zu viele für sie. Ich habe das Gefühl, dass Ihr mehr Erfolg haben werdet.\n\nNehmt Euch aber vor den Gezeiten in Acht!", sourceObjective = "Tötet 11 schäumende Meereselementare.", completion = "Der Geruch des Meeres haftet an Euch, {name}. Eure Anstrengungen gewähren Klingenhügel einen weiteren Tag.\n\nIch werde bei meinen Vorgesetzten von Euren Taten berichten. Ihr könnt Euch unserer Dankbarkeit sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25178] = { id = 25178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffswracks durchsuchen", description = "<Hey, Hübscher, willkommen zurück! Es würde Euch nicht stören, noch einmal für mich aufzubrechen, oder? Ich wäre Euch SOO dankbar.../Ihr da! Halt> diebische Elster! Mit Euch bin ich noch nicht fertig!;\n\nIch habe gehört, dass Ihr zur Küste unterwegs seid. Am Strand sind unzählige gestrandete Schiffe, und in den Schiffen sind Gnomenwerkzeuge... die kann ich gebrauchen.\n\n<Bis bald, Muskelprotz!/An die Arbeit> Frollein!;", sourceObjective = "Erhaltet 4 Kisten Gnomenwerkzeuge.", progress = "Da ist ja mein Ritter in der glänzenden Rüstung!", completion = "Ihr lest einem Mädchen wie mir wirklich jeden Wunsch von den Augen ab, wisst Ihr das? Wenn Ihr jemals etwas von mir braucht...", sourceObjectiveStatus = "unverified-source-field" }
quests[25179] = { id = 25179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abbau der Verluste", description = "Ihr müsst uns helfen. Die Elementare... sie sind stärker, als man ihnen ansieht, und sie kommen in Massen. Sie haben uns total überrascht und übermannt.\n\nViele meiner Grunzer liegen am Strand im Sterben. Wenn Ihr sie retten könntet... wäre ich Euch so dankbar, und Gar'Thok in Klingenhügel auch!", sourceObjective = "Rettet 4 verletzte Grunzer von Klingenhügel.", completion = "Ich habe schon mit ein paar der Orcs gesprochen, die vom Strand zurückgekehrt sind. Alle haben gesagt, dass Ihr sie gerettet habt.\n\nIhr habt heute eine ritterliche Tat vollbracht, {name}. Lok'tar ogar! Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[25182] = { id = 25182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Ich will tote Goblins sehen, {name}! Direkt westlich von hier findet Ihr ein ganzes Nest dieser kleinen Maden, die sich in den Berg graben.\n\nSorgt dafür, dass es ihr eigenes Grab ist, das sie sich graben!\n\nVernichtet sie. Vernichtet diese gesamte gierige Operation. Sie haben in Bael'dun ihren eigenen Untergang besiegelt, {class}. Es ist Zeit, dass sie ihrem Schöpfer gegenübertreten.", sourceObjective = "Tötet 10 Minenarbeiter von Frazzelcraz in Frazzelcraz' Hauptader im Südlichen Brachland.", completion = "Tot? Gut!\n\nMöge die Nachricht von dieser Tat sich schnell verbreiten und mit ihr die Angst.\n\nDie Horde wird die Folgen ihres Angriffs auf Bael'dun schon zu spüren bekommen und den Tag bereuen, an dem sich unsere Wege kreuzten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25183] = { id = 25183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "… und vergrabt die Reste", description = "Sie zu töten reicht einfach nicht. Nach der Katastrophe in Bael'dun will ich, dass diese Goblins ihre eigenen fiesen Machenschaften zu spüren bekommen.\n\nGeht in Frazzelcraz' Mine und macht ein paar Sprengsätze scharf.\n\nAm Eingang der Mine sollte sich eine Art Schalter oder Auslöser befinden. Sobald die Sprengsätze scharf sind, verwendet den Auslöser, um den ganzen Ort in die Luft zu jagen. Versetzt sie in Angst und Schrecken, {class}!", sourceObjective = "Macht 6 Sprengsätze von Frazzelcraz in Frazzelcraz' Hauptader scharf.", progress = "<Vom Auslöser führen ein paar sehr provisorisch aussehende Drähte in die Mine.>", completion = "<Die Sprengsätze sind scharf und bereit!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25184] = { id = 25184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilder Minenwagenritt", description = "Springt einfach auf und sprecht mit Assistentin Greely, wenn Ihr unten angekommen seid.", sourceObjective = "Reist mit dem Minenwagen an das Ende der Strecke und sprecht mit Assistentin Greely.", completion = "Wie wir hier beim Tüftlerverband sagen würden: Vom atmosphärischen tropfenförmigen Niederschlag in den metallischen Weiterleitungsbehälter am Dachlauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25185] = { id = 25185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist vollbracht", description = "<Ihr schützt Eure Augen vor der Explosion und dem umherfliegenden Geröll, als die Mine einstürzt.>\n\n<General Doppelzopf wird sehr erfreut sein, aber Ihr bezweifelt, dass das seinen Rachdurst stillen kann.>", sourceObjective = "Kehrt zu General Doppelzopf an Doppelzopfs Patrouille im Südlichen Brachland zurück.", completion = "<Doppelzopf nickt, als Ihr die Zerstörung der Mine beschreibt, aber in seinen Augen brennt immer noch kalter Hass.>\n\nSehr gute Arbeit, {name}. Ich schätze, dass es auch strategische Vorteile gibt, der Horde diese Mineralien zu rauben, aber am zufriedensten macht mich, dass diese kleinen grünen Monster zerquetscht wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25186] = { id = 25186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweckloser Widerstand", description = "{name}, ich habe nicht die Absicht, Kommandant Singleton meinen Bericht ohne auch nur das geringste bisschen an guten Nachrichten zukommen zu lassen. Wir müssen der starrköpfigen Horde die Kontrolle über diese Straßen entringen.\n\nSoweit ich weiß, ist ihr Anführer Kona Donnerlauf. Er hat ein Lager direkt nördlich von hier. Er ist im Steinkrallengebirge heimisch und kennt diese Straßen so gut wie seine Westentasche. Wenn wir ihn vernichten können, lässt der Widerstand aus dem Westen möglicherweise nach.\n\nFindet und tötet Kona Donnerlauf, dann meldet Euch bei Kommandant Singleton!", sourceObjective = "Tötet Kona Donnerlauf an der Grenze zwischen dem Steinkrallengebirge und dem Südlichen Brachland.", completion = "Also unsere Vorräte kommen nicht durch? Hmmm. Die Ehrenwacht wird immer mehr isoliert.\n\nDoch der Sieg über Donnerlauf sollte unseren Feinden ein Signal senden, dass wir die Absicht haben, zu bleiben. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25187] = { id = 25187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Fluten verloren", description = "Die Ereignisse, die mit dem Kataklysmus in Verbindung stehen, haben nicht nur ein paar Boote an Land geschwemmt, {name}. Der Südstrom ist über die Ufer getreten und das gesamte westliche Becken Durotars ist unter Wasser.\n\nDort sind noch immer Leute, die Hilfe brauchen. Ich habe schon eine Zeit lang gesucht, konnte aber nichts finden. Würde es Euch stören, selbst zu schauen?", sourceObjective = "Benutzt Thonks Handfernrohr, um in der Südstromaue nach Überlebenden zu suchen.", progress = "Was konntet Ihr sehen?", completion = "Aah, ich verstehe... das KLEINE Ende vom Handfernrohr wird ans Auge gesetzt. Das werd ich mir merken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25188] = { id = 25188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aue patrouillieren", description = "Mein Posten ist hier, im Turm, und ich kann meinen Posten nicht verlassen, {name}. Ich brauche jemanden, der für mich den Leuten hilft, die nach der Überschwemmung des Flusses Hilfe brauchen.\n\nKann ich mich auf Euch verlassen?", sourceObjective = "Sucht die Südstromaue nach den Leuten ab, die Ihr mit dem Handfernrohr gesehen habt und helft ihnen.", completion = "Ich habe den Trick mit dem kleinen Ende vom Handfernrohr benutzt und Euch beim Hin- und Herrennen da unten zugeschaut. Sehr beeindruckend!\n\nOh, wie habt Ihr die alte Frau zum Fliegen gebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[25189] = { id = 25189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister seien gelobt", description = "Wer seid Ihr? Was ist passiert?\n\nIch habe in meiner Hütte meditiert, und...\n\nAh, jetzt erinnere ich mich. Die Geister haben angefangen, zu schreien, und der Fluss trat über die Ufer. Ich kann mich glücklich schätzen, dass Ihr mich hier gefunden habt. Ich bin alt und kann den Elementen nicht mehr so ohne Weiteres standhalten. Werdet Ihr mir hier heraushelfen?", sourceObjective = "Begleitet Großmatrone Tekla zu Raggaran.", progress = "Meine Großmutter ist hier noch irgendwo...", completion = "Meine Großmutter war einst eine mächtige Schamanin. Ich dachte, sie hätte mit dem Alter ihre Macht verloren, aber manche Dinge behält man wohl für immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25190] = { id = 25190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn Raggarans", description = "Die Stacheleber sind ein Schandfleck in der Landschaft, den nicht einmal der übergetretene Strom wegwaschen kann. Mir wurde gesagt, wir sollen evakuieren, aber das konnte ich nicht, weil ich mit meiner Arbeit noch nicht fertig war.\n\nAaarggggh! Ich hasse Stacheleber so unglaublich arg! Helft Ihr mir, sie zu töten?", sourceObjective = "Tötet 4 Stacheleber der Klingenmähnen und 4 Späher der Klingenmähnen.", completion = "<Raggaran scheint sich ein wenig beruhigt zu haben, seit Ihr ihn das letzte Mal getroffen habt.>\n\nGut, gut. Wir sind schon einen Schritt weiter, diese knopfäugigen, korbtragenden, ebernasigen, zweizehigen...\n\n<Raggarans Zorn nimmt offensichtlich wieder zu.>\n\n...gebückt laufenden, schreienden, stachligen, nichtsnutzigen, Gnome mögenden... AAAAAAARGGGH! Stacheleber!", sourceObjectiveStatus = "unverified-source-field" }
quests[25191] = { id = 25191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begutachtet die Zerstörung", description = "Ich habe von unglaublichen seismischen Anomalien hier in Kalimdor gehört, aber ich hatte keinen Schimmer, dass das geologische Chaos so umfassend ist!\n\nIch benötige eine aktuelle Begutachtung der Zerstörung, während ich hier bleibe und die seismographischen Aufzeichnungen auswerte. Könntet Ihr mit meinem vollautomatischen Feldvermessungsfahrzeug ein paar Daten für mich sammeln? Ich kümmere mich um das Fliegen.\n\nWenn die Vermessung erfolgt ist, zeigt die Daten meinem Kollegen Horton Kardanherz in Nordwacht.", sourceObjective = "Sprecht mit Nibb Spindelgang in Ehrenwacht, um die Zerstörung des Kataklysmus zu vermessen.", completion = "Wie bitte? Seht Ihr nicht, dass wir hier angegriffen werden!\n\n<Kardanherz schnappt sich die Aufzeichnungen aus dem Feldvermessungsfahrzeug und stopft sie willkürlich in eine Art Seesack.>\n\nJa natürlich werde ich mir Nibbs Ergebnisse genau ansehen. Und wenn es nach mir geht, aus der Sicherheit der Östlichen Königreiche heraus!", sourceObjectiveStatus = "unverified-source-field" }
quests[25192] = { id = 25192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raggaran regt sich auf", description = "Ich werde nicht ruhen, bis sie besiegt sind! Tötet sie ALLE!\n\n<Raggaran holt tief Luft.>\n\nIhre stinkenden Behausungen sind nördlich von hier, oder südlich von hier!", sourceObjective = "Tötet 5 Staubläufer der Klingenmähnen und 5 Schlachtwachen der Klingenmähnen.", completion = "<Raggaran scheint, sich etwas beruhigt zu haben.>\n\nIhr habt gute Arbeit geleistet.\n\nEs tut mir leid, dass Ihr mich so aufgebracht sehen musstet. Danke, dass Ihr die Stacheleber getötet habt. Vielleicht solltet Ihr besser gehen, bevor ich wieder anfange, mich aufzuregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25193] = { id = 25193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren, aber nicht vergessen", description = "Heute ist der Todestag meines Sohnes Kron. Ich habe es ewig nicht zugeben mögen, aber nun weiß ich, dass er nicht von der Krokiliskenjagd heimkehren wird.\n\nIch habe an etwas gearbeitet... etwas, das Krons Leidenschaft für die Jagd darstellt. Eine Halskette mit Krokiliskenzähnen... Reihe um Reihe von Zähnen; ein Schmuckstück, das nur von dem mutigsten jungen Orc getragen werden kann. Ich werde die Kette auf sein Grab legen.\n\nKron war mutig, aber nicht so stark wie Ihr. Könnt Ihr mir die Zähne für seine Kette besorgen?", sourceObjective = "Sammelt 250 Krokiliskenzähne.", progress = "Kron wird nicht vergessen werden.", completion = "{race}, ich danke Euch. Ich werde sofort an der Kette weiterarbeiten.\n\nVor seinem Tod habe ich für Kron das hier angefertigt. Ich kann damit nichts anfangen, aber Euch könnte es nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25194] = { id = 25194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebetene Gäste", description = "Keine Sorge, Zen'Taji ist nicht in Schwierigkeiten. Hat nur gelernt, was passiert, wenn der Fluss über die Ufer tritt.\n\nSeht Ihr die großen Vögel, da am Flussufer? Zen'Taji glaubt, die sind in Schwierigkeiten. Durch das Erdbeben und die Flut wurden die Ebenenschreiter auf diese Seite des Stroms gebracht, aber sie können nicht zurückfliegen, und schwimmen können sie auch nicht. Sie haben Angst davor.\n\nWenn sie hier bleiben müssen, werden sie sterben. Zen'Taji mag Gewalt nicht, aber vielleicht könnt Ihr sie angreifen, damit sie sich so arg erschrecken, dass sie auf die andere Seite flüchten. Ja?", sourceObjective = "Greift 3 launische Ebenenschreiter an, bis sie in Richtung Brachland fliehen.", progress = "Haut sie einfach ein bisschen. Vertraut Zen'Taji, sie werden fliehen. Es ist echt nicht viel dahinter.", completion = "Hey, ich mag alle Tiere. Ich mag auch große Tiere. Ich mag es nur nicht, wenn Ihr ihnen wehtut... aber es ist ja zu ihrem Wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[25195] = { id = 25195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende dieses Raptors", description = "Viele Kreaturen starben, als das Wasser in das Tal strömte. Die Raptoren allerdings vermehrten sich und fühlten sich in dieser neu entstandenen Umgebung wohl. Sie sind schlaue Raubtiere und konnten sich vom Unglück anderer Tiere ernähren.\n\nEiner der Raptoren ist besonders grausam. Er tötet die kleinen Tiere und lässt sie im Wasser verrotten - er isst sie nicht mal! Er heißt Hiebkreischer; wenn wir nicht aufpassen, wird er das Gleichgewicht der Natur sehr stören.\n\nReist nach Norden, tötet ihn, und gebt seinen Körper der Natur wieder.", sourceObjective = "Tötet den als Hiebkreischer bekannten Raptor.", progress = "Raptoren waren schon immer sehr anpassungsfähig.", completion = "Zen'Taji glaubt, dass der Kataklysmus bei Hiebkreischer etwas komisches hervorgerufen hat. Er war nicht immer so gewalttätig und irrational.\n\nIch danke Euch für Eure Hilfe, {name}. Zen'Taji wird sich nun weiter seinen Naturstudien widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25196] = { id = 25196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blockade von Dranosh'ar", description = "Ihr solltet von hier aus nach Norden reisen, {name}. Sprecht mit Gor dem Vollstrecker bei der Blockade von Dranosh'ar. Er ist mit der Aufgabe beauftragt, die Seestraßen, die nach Orgrimmar führen, zu sichern. Sein Dock ist direkt neben der Knochenhöhle. Ich bin mir sicher, dass er daran interessiert wäre, dort weiterzumachen, wo wir aufgehört haben.", sourceObjective = "Meldet Euch bei Gor dem Vollstrecker bei der Blockade von Dranosh'ar in Durotar.", completion = "Ihr seid derjenige, der sich im Alleingang um die Brennende Klinge gekümmert hat? Meine Ohren sind überall, mein Junge, und Neuigkeiten reisen schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[25197] = { id = 25197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Admiral gibt nicht klein bei", description = "Wie bitte? Ihr wollt hierbleiben, um zu kämpfen? Typisch {class}, will bleiben und gegen die Horde kämpfen, wenn man doch noch die Chance hätte, wegzulaufen.\n\nHört zu, wenn Ihr wirklich Nordwacht retten wollt, solltet Ihr Euch bei Admiral Aubrey im Turm hinter mir melden. Egal, wie sehr ich ihn darum bitte, er behält seine Schiffe für den Kampf hier, anstatt uns alle in Sicherheit zu bringen.\n\nWenn Ihr mich jetzt entschuldigen wollt - ich muss noch fertig packen!", sourceObjective = "Meldet Euch bei Admiral Aubrey in der Feste Nordwacht im Südlichen Brachland.", completion = "Ihr habt es gewagt, den ganzen Weg von Ehrenwacht aus hierher zu kommen? Ausgezeichnet, wir können Eure Erfahrung hier brauchen.\n\nSie haben zwar die Mauern durchbrochen, aber Nordwacht wird sich nicht kampflos ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25198] = { id = 25198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winnoa Kiefernwald", description = "Obwohl wir hier einiges erreicht haben, wäre es eine Tragödie, wenn ein Teil dieser Verderbnis unserer Aufmerksamkeit entgangen wäre. Die Tunnel der Höhlen des Wehklagens erstrecken sich unter dem gesamten Brachland und wenn noch ein weiterer Punkt ungezähmter Energie sich einen Weg an die Oberfläche gebahnt hat...\n\nIhr habt allerdings genug für mich getan. Ich möchte Euch nur noch darum bitten, einen Druidenfreund von mir wissen zu lassen, was hier geschehen ist. Ihr findet Winnoa Kiefernwald an der Vendettakuppe südwestlich von hier.", sourceObjective = "Sprecht mit Winnoa Kiefernwald an der Vendettakuppe im Südlichen Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[25199] = { id = 25199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundbefehle", description = "Hey! Ihr seht aus, als könntet Ihr uns helfen!\n\nWenn Ihr bereit seid, unsere Ziele zu unterstützten, müsst Ihr erst die Grundausbildung absolvieren. Gnomenausbildungen sind brutal und rigoros, also hoffe ich, dass Ihr vorbereitet seid!\n\nGeht zu Ausbildungsoffizier Dampfkurbel, und er wird Euch beibringen, was Ihr wissen müsst. Folgt unbedingt seinen Befehlen, wenn er sie erteilt, oder Ihr werdet es nie schaffen!\n\nAber ich warne Euch: es ist hart da drüben. Falls Ihr durchkommt, meldet Euch wieder bei mir.", sourceObjective = "Folgt Ausbildungsoffizier Dampfkurbels Befehlen und meldet Euch dann bei Hauptmann Tret Funkdüse zurück.", completion = "Ihr seid noch in einem Stück? Ihr habt mehr Getriebe unter der Haube als ich gedacht hätte, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25200] = { id = 25200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderangriff", description = "Dieser nichtsnutzige Handelsprinz Gallywix hat es irgendwie geschafft, die gesamte Fußbombenmannschaft der Dampfdruckhaie auf der Yacht unterzubringen. Ich habe keinen einzigen von ihnen zu Gesicht bekommen!\n\nJetzt erledigen sie für ihn die Drecksarbeit hier auf der Rodungsfläche. {name}, Ihr seid <der Held, der/die Heldin> die; für uns den Pokal zurück nach Kezan geholt hat. Ihr müsst sie loswerden!", sourceObjective = "Tötet 8 Dampfdruckhaie.", completion = "Ich kann nicht behaupten, dass ich je ein Fußbombenfan war, aber Ihr bringt mir das Spiel wirklich nahe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25201] = { id = 25201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ultimative Fußbombenuniform", description = "Schaut, <Kleiner/Kleine>, meine Aufgabe ist, dafür zu sorgen, dass Ihr im Endspiel eine faire Chance habt. Thrall braucht Eure Hilfe im Kampf gegen den Handelsprinzen.\n\nGreely, Hobart und ich haben ein ultimatives Fußbombentrikot zusammengestellt, mit der Ihr das Spiel garantiert gewinnt. Zuerst benötige ich jedoch noch ein paar Dinge.\n\nZu unserem Glück quillt diese Rodungsfläche vor Schredderersatzteilen fast über. Also raus auf den Platz und gebt mir 110%!", sourceObjective = "Sammelt 8 Schredderersatzteile.", progress = "Wollen wir mal sehen, was Ihr da habt, {name}.", completion = "Ja, die eignen sich hervorragend. Gut gemacht, Kleiner. Ich sorge dafür, dass Ihr das beste Fußbombentrikot aller Zeiten bekommt.\n\nIn der Zwischenzeit habt Ihr andere Bomben, die Ihr auf die Lakaien des Handelsprinzen niedergehen lassen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25202] = { id = 25202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schnellste Weg zu seinem Herzen", description = "Oh, Mädchen! Ihr werdet nie glauben, wer sich auf der Ölplattform im Norden aufhält.\n\n<Izzy schüttelt traurig den Kopf.>\n\nChip ist da draußen und arbeitet für den Handelsprinzen. Diese kaltherzige Schlange hat Euch wie eine heiße Kartoffel fallenlassen und jetzt arbeitet er auch noch für die anderen. Ich habe sogar gehört, dass er mit diesem Flittchen Vani LeHörnchen ausgeht!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber ich würde ihm sein noch schlagendes Herz aus der Brust reißen.", sourceObjective = "Reißt Chip Endale das noch schlagende Herz aus der Brust.", progress = "Wie habt Ihr Euch entschieden? Tod oder Vergebung?", completion = "Er hat nur das bekommen, was er verdient hat. Na, na, nicht weinen. Ihr findet schon einen anderen, der Euch gut behandelt.\n\nHier, lasst mich das nehmen… Wir wollen ja nicht, dass die Leute denken, Ihr wärt verrückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25203] = { id = 25203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer heißt denn schon Chip?", description = "Kumpel! Ihr werdet nie glauben, wer sich auf der Ölplattform im Norden aufhält.\n\n<Ass schüttelt ungläubig den Kopf.>\n\nChip ist da draußen und arbeitet für den Handelsprinzen. Dieser Verräter arbeitet für die anderen. Aber es kommt noch schlimmer! Ich habe gehört, dass er mit Eurer Ex-Freundin Vani LeHörnchen ausgeht!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber wenn das meine Ex wäre, würde ich etwas dagegen unternehmen.", sourceObjective = "Tötet Chip Endale.", completion = "Anders kann man es nicht sagen… Er hat einfach genau das bekommen, was er verdient hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25204] = { id = 25204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gelöstes Problem", description = "Wir müssen Handelsprinz Gallywix' Ölversorgung stoppen und seine Maschinen aufhalten.\n\nIhr müsst für uns zur Ölplattform der HGK gehen und die Ventile lösen, um das Kühlsystem zu überlasten. Geht danach zur Plattformsteuerungskonsole und bringt sie zum Explodieren.", sourceObjective = "Löst die Ventile 1 bis 4.", progress = "Ihr habt noch nicht alle vier Ventile gelöst. Das Kühlsystem der Plattform funktioniert immer noch mit ganz normalen Parametern.", completion = "Alle Leuchten und Anzeigen auf der Steuerungskonsole spielen verrückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25205] = { id = 25205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wolf und der Kodo", description = "Mein \"Kollege\" hier hat Pläne mit Euch, denen ich nicht zustimmen kann. Er ist hastig, unkontrolliert, unverantwortlich und außerdem bezahlt Ihr am Ende vielleicht auch noch mit Eurem Leben.\n\nBevor Ihr mit Gor sprecht, möchte Ich Euch bitten, Euch die Geschichte anzuhören, die ich zu erzählen habe. Es geht bei der Geschichte um ihre Moral - es ist eine Fabel. Ich glaube aber, dass die Moral dieser Geschichte für Euch sehr wertvoll sein könnte. Sprecht mit mir, wenn Ihr sie hören möchtet.", sourceObjective = "Lauscht der Moral der Geschichte von Shin Steinsäule.", progress = "Achtet auf die Bedeutung hinter den Worten, mein Kind.", completion = "Die Moral der Geschichte: Voreilige Handlungen, die aus Faulheit getätigt wurden, können ein böses Ende nehmen. Wir sollten den Lauf der Dinge nicht überstürzen... wir müssen uns unsere Belohnungen verdienen. Ich habe versucht, dem Vollstrecker diese Geschichte zu erzählen, aber sein Höllschrei-verehrender Schädel hat sie einfach nicht verstanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25206] = { id = 25206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Warnungen nicht beachten", description = "Ihr könnt die Worte des Schamanen ignorieren, <Soldat/Soldatin>. Es gibt gewisse Leute in der Horde, die auf unsere Zusammenarbeit bestehen. Ich kann Euch aber versichern, dass dieser Thrall-verrückte Scharfseher nicht einmal über seine eigene Hutspitze sehen kann.\n\nDie Elementare führen westlich von hier miteinander Krieg. Normalerweise wäre mir das egal, aber ich brauche dieses Gebiet, um die Schiffstraße von hier ins Brachland zu vergrößern. Die Elementare sind normalerweise recht stark, aber durch ihre Kämpfe miteinander sind sie geschwächt. Mit diesem Wissen sollte es Euch ein Leichtes sein, sie zu zerstören.", sourceObjective = "Zerstört 12 verfeindete Elementare. Ihr könnt wütende Erdwächter oder belebte Wasserwächter töten.", completion = "Seht Ihr? Die Geschichten des Schamanen sind nicht mehr als... eine Bettgeschichte für einen Jüngling. Die neue Horde nimmt sich, was sie will, und verschwendet mit solchem Schwachsinn nicht ihre Zeit.\n\nFalls Ihr dazu kommt, könnt Ihr ja Shin... und auch allen anderen, die sein Verhalten unterstützen... sagen, dass sie Eure Zeit nicht vergeuden sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25207] = { id = 25207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Plattform platt", description = "Auf der Konsole ist ein einzelner großer, roter Knopf. Wenn es Knöpfe gibt, die große Explosionen auslösen, sehen sie ganz sicher so aus!", sourceObjective = "Drückt den großen roten Knopf auf der Ölplattform der HGK.", completion = "Ich habe die Hitze der Explosionen bis hierher spüren können!", sourceObjectiveStatus = "unverified-source-field" }
quests[25208] = { id = 25208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichtet Silvia", description = "Es scheint, als haben wir eine Plage gefunden, die um einiges schlimmer ist als die, mit dir wir gerechnet hatten. Cho'gall versucht zweifellos, durch die Gordok Zugang zu den Überresten Eldre'Thalas' in Düsterbruch zu erlangen, ein Ort voller verbotener Mächte, die den Fall von Shen'dralar hervorriefen...\n\nIch schweife zu sehr aus. Geht, {name}. Berichtet Silvia von dem, was ich Euch erzählt habe. Was auch immer in Düsterbruch vor sich geht, muss aufgehalten werden.", sourceObjective = "Sprecht mit Silvia am Turm von Estulan.", completion = "Ihr seid zurückgekehrt. Was hat Estulan gesagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[25209] = { id = 25209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch die Gordunni", description = "In der Oberen Wildnis südlich von hier befinden sich viele uralte Ruinen. An diesem Ort haben die Vorfahren der Nachtelfen sich an der arkanen Magie versucht und die Oger der Gordunni streifen dort umher, um Überreste dessen ausfindig zu machen.\n\nIhr werdet bemerken, dass der Wald dort komplett zerstört wurde; die Oger hinterlassen nichts als Schlamm und entziehen der Horde dadurch wertvolle Ressourcen.\n\nGeht und tötet die Gordunni, {name}. Sichert das Gebiet für die Horde, für die Horde allein!", sourceObjective = "Tötet 16 Oger der Gordunni in der Oberen Wildnis.", completion = "Ihr habt Euch als vertrauenswürdig und verlässlich herausgestellt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25210] = { id = 25210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Wandels", description = "Eine üble Krankheit hat die Kreaturen unseres Waldes heimgesucht. Zuerst dachte ich, es wäre einfach eine der Tücken der Natur, aber der Krankheit scheint kein Heilungsprozess zu folgen.\n\nDie Hirsche des Waldes, die normalerweise sehr stark und friedlich sind, haben am meisten gelitten. Einige finden in ihrer Schwäche ihr Ende. Andere sind tollwütig und sehr gefährlich. Um die Geister zu befragen und mehr über die Krankheit in Erfahrung zu bringen, benötige ich die Geweihe der Hirsche.", sourceObjective = "Sammelt 8 infizierte Hirschgeweihe.", progress = "Es ist keine schöne Aufgabe, aber es muss getan werden, {name}.", completion = "Ich danke Euch, {name}. Ich werde die Geweihe untersuchen. Seitdem Ihr Euch auf den Weg gemacht habt, hat sich die Lage verschlimmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[25211] = { id = 25211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Behausung säubern", description = "Hört nicht auf Rharen. Er ist so verwirrt, wie man nur sein kann. Es ist sein Fehler, dass das gesamte Bier erbeutet wurde!\n\nAußerdem bin ich davon überzeugt, dass es hier noch ein größeres Problem als nur gestohlenes Bier gibt. Die Tatsache, dass nach all den Jahren hier eine Gruppe Orcs um Dun Algaz herumrennt ist lächerlich!\n\nIch sag' Euch was, {class}. Ihr geht dort hinein und vertreibt so viele Orcs wie Ihr könnt aus diesen Ruinen. Dun Algaz taugt nicht mehr zu viel, aber ich will verflucht sein, wenn wir sie dort einfach sitzen lassen.", sourceObjective = "Tötet 5 Orcs des Drachenmals in Dun Algaz.", progress = "Na kommt schon, strengt Euch ein wenig an! Ich kann sie immer noch von hier aus riechen!", completion = "Das wird ihnen eine Lehre sein! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25212] = { id = 25212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Rande der Schächte", description = "Wir dachten, wir könnten warten, bis die Strahlung um Gnomeregan nachlässt, aber es scheint nicht besser zu werden.\n\nWenn wir unsere Stadt zurückerobern wollen, müssen wir sicherstellen, dass unsere Truppen sie unbeschadet betreten können.\n\nNehmt diese Radiageigatrons, schnappt Euch die Donnerschlag hier und werft sie auf die Lüftungsschächte außerhalb von Gnomeregan. Sie werden die Strahlenbelastung direkt an mich übermitteln.", sourceObjective = "Benutzt Pilot Sprossmündungs Flugmaschine, um Radiageigatrons auf die Luftschächte um Gnomeregan herum zu werfen.", completion = "Großartige Arbeit!\n\nDie Daten, die ich bekommen habe, zeigen, dass die Strahlenwerte völlig im Sicherheitsbereich unserer Anzüge liegen. Das sind exzellente Neuigkeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25213] = { id = 25213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sklavengruben", description = "Der Trainer hat uns gesagt, dass Sassy sich drüben bei den Sklavengruben aufhält. Es sind ein paar Orcs bei ihr, die sich auf einen Angriff auf den Handelsprinzen vorbereiten.\n\n{name}, Ihr solltet die Straße entlang nach Südwesten gehen und sie suchen. Sie möchte ganz sicher, dass Ihr den Angriff leitet!", sourceObjective = "Sprecht mit Sassy Hartzang bei den Sklavengruben.", completion = "Ich habe mich schon gefragt, wo Ihr bleibt!\n\nKeine Sorge. Hobart wird dieses Fußbombentrikot in das ultimativste Fußbombentrikot aller Zeiten verwandeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[25214] = { id = 25214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht nach oben", description = "Wir haben wirklich keine Zeit, um all die zu retten, die so dumm sind, sich immer und immer wieder einfangen zu lassen. Ich habe jedoch noch ein paar Raketen übrig, sodass wir dieses Problem ganz leicht aus der Welt schaffen können.\n\nBringt diese einstufigen Trägerraketen zu den Sklavengruben im Norden und befestigt sie an den Käfigen.\n\nDer Käfig wird abheben, und so können wir diese Idioten im Handumdrehen befreien.", sourceObjective = "Benutzt die einstufigen Trägerraketen, um die Käfige von 8 Bürgern von Kezan oder überlebenden Goblins in die Luft zu schießen.", completion = "Ups. Nun ja, runter kommen sie alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25215] = { id = 25215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ablenkender Geruch", description = "Raubtiere riechen diese toten Naga schon fast aus einer Meile Entfernung. Bald werden wir kämpfen müssen, nur um in die Höhle hinein oder hinaus zu kommen. Wollt Ihr mir nicht helfen, aufzuräumen?\n\nDirekt jenseits des Riffs im Süden findet Ihr die Glimmertiefenschlucht. Wenn Ihr die Leichen dorthin schleift und sie im Wasser loslasst, werden die Wildtiere sie beseitigen, noch bevor sie am Meeresgrund angelangt sind. Versucht nur, den Haien so gut wie möglich auszuweichen.", sourceObjective = "Zerrt 3 tote Räuber des Zin'jatar in das offene Meer über der Glimmertiefenschlucht im Süden.", completion = "Es sollte nicht lange dauern, das Wasser zu reinigen. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25216] = { id = 25216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Sambino", description = "Falls Ihr Euch auf den Weg hinab in den Graben macht, könntet Ihr mir einen Gefallen tun und nach einem unserer neueren Mitglieder sehen.\n\nSein Name ist Sam, aber er hat die Angewohnheit, seinen Namen ein wenig auszuschmücken. Er hat noch nicht so recht verstanden, was die Mitglieder des Irdenen Rings ausmacht, aber er gibt sich viel Mühe, daher sehen wir es ihm nach.\n\nLasst Euch nicht zu sehr einwickeln, ihm bei seinen verrückten Plänen zu helfen. Schaut einfach nur nach, ob er unversehrt ist und lasst es mich wissen, damit ich beruhigt bin.", sourceObjective = "Sucht nach \"Sam\" am westlichen Ende des Silberflutgrabens.", completion = "Ein weiterer Bewunderer des großen Sambinos! Seid Ihr den ganzen weiten Weg gekommen, damit ich Euch ein Autogramm gebe? Ich bin viel zu beschäftigt, um irgendetwas zu unterschreiben. Hinfort mit Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[25217] = { id = 25217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemmodifikation", description = "Na gut, weil Ihr mich so verzweifelt anschaut, lasse ich Euch an meiner echten Arbeit teilhaben.\n\nDieser Fels ist noch völlig unerschlossen! Wahrscheinlich schlummern hier größere Reichtümer als in der Schatzkammer eines Handelsprinzen während eines großen Krieges! Ich brauche Proben. Mehr Proben. Proben von überall!\n\nIch habe meine Erdtotems so modifiziert, dass die sich durch den Sand graben und Felsproben aus dem Boden darunter aufnehmen. Geht und sucht einen geeigneten Ort, um eines davon aufzustellen.\n\nDas Zittern und Rumpeln lockt sicher all die süßen, neugierigen Wildtiere an. Da könnt Ihr gleich noch neue Freundschaften schließen!", sourceObjective = "Stellt eines von Sambinos modifizierten Totems im Sand des Silberflutgrabens auf.", progress = "Bah! Ich habe Sand im Helm. Das juckt!", completion = "Eine weitere Probe. Ausgezeichnet! Die felsigen Reichtümer des Meeres werden bald mir gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25218] = { id = 25218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwasserinflation", description = "Na gut! Na gut. Ihr habt mich überredet. Ihr dürft mir helfen.\n\nIch verliere mehr Luft als ein mit Stachelebern gefüllter Zeppelin. Mein Luftventil muss sich irgendwo im Graben gelöst haben.\n\nIch habe ein paar Ersatzballons dabei. Macht Euch nützlich und füllt einen auf, ja? Und findet mein Ventil! Das brauche ich natürlich auch.\n\nIch wette, die Krebse haben es gestohlen... Kneifende, gierige kleine Biester...", sourceObjective = "Füllt einen von Sambinos Luftballons und findet das verloren gegangene Luftventil.", progress = "Wenn Luft nur nicht so… luftig wäre! Oder wenn es für diese Wasseratmungszauber wenigstens schicke Helme gäbe! Eines von beidem würde mir schon reichen.", completion = "Wisst Ihr, ich hätte Euch einen Gürtel mit Gewichten geben sollen, damit Ihr nicht einfach mit dem Ballon und allem davontreibt. Zum Glück hattet Ihr ja Eure Rüstung und so an. Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[25219] = { id = 25219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht verschnecken", description = "Ich untersuche Schnecken.\n\nJa. Schnecken. Wenn Ihr mit Lachen fertig seid, könnt Ihr mir ja vielleicht helfen.\n\nSicher ist Euch die gigantische Schnecke am Riff aufgefallen. Nun, ich bin mir sicher, dass etwas darin steckt. Es gibt dort mehrere Punkte, die eigentlich nur Einmündungen oder Eingänge sein können. Außerdem habe ich gesehen, wie diese Knochenwühler sich dort hinein und hinaus quetschen.\n\nIch dachte, wir können diese Schnecken vielleicht benutzen, um uns selbst Zugang zu verschaffen. Zumindest ist das die Theorie.", sourceObjective = "Sammelt 10 Spiralmuschelknochenwühler.", progress = "Ich weiß, das ist nicht gerade die erstrebenswerteste Aufgabe, aber seid Ihr nicht auch neugierig, was es mit dieser Schnecke auf sich hat? Sie ist so riesig! Da muss doch mehr dahinter stecken.", completion = "Danke. Ehrlich. Wenn noch ein Gestrandeter mich ausgelacht hätte, hätte ich vor lauter Zorn sicher jemanden gemeuchelt.\n\nIch lasse es Euch wissen, sobald mir etwas einfällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25220] = { id = 25220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glitschige Bedrohung", description = "Wurdet Ihr schon von den Aalen an den Riffen angegriffen? Wenn nicht, dann wird es noch passieren, so viel steht fest. Das sind bösartige, blutdurstige kleine Monster. Und es scheint ihnen auch ganz egal zu sein, wen oder was sie beißen.\n\nWenn Ihr hinaus in das Tal geht, wäre ich Euch sehr dankbar, wenn Ihr ihre Zahl etwas dezimieren würdet. Nicht alle hier sind so gut ausgerüstet wie Ihr. Uns könnten sie vielleicht mehr als nur Kratzer zufügen.", sourceObjective = "Tötet 12 Spitzzahnaale.", completion = "Vielen Dank, {class}. Es gibt immer noch viele größere Raubtiere, auf die wir achten müssen, aber wenigstens sind wir jetzt um die Höhle herum etwas sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25221] = { id = 25221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsjagd", description = "Sie entkommen!\n\nDas sind die gleichen Naga, die die Boote angegriffen und unsere Freunde verschleppt haben. Wir dürfen sie nicht entwischen lassen!\n\nNehmt diese Speere und verfolgt sie auf Eurem Seepferdchen. Verschwendet keine Zeit mit Absteigen. Heftet Euch einfach an ihre Fersen und tötet alle, die Ihr erwischen könnt, mit den Speeren.\n\nIch versuche inzwischen, den Tiefenlord zu stellen. Wenn Ihr fertig seid, sucht mich am Ende des Riffs auf.", sourceObjective = "Benutzt Toshes Jagdspeer, um 20 fliehende Naga des Zin'jatar zu töten.", progress = "Unsere anderen Verbündeten sind alle in der Höhle unter uns. Von hier aus gesehen scheint alles sicher zu sein, aber genau kann man das nie sagen.\n\nHabt Ihr getan, worum ich Euch gebeten habe?", completion = "Schnelle Arbeit. Sehr beeindruckend.\n\nDieser Tiefenlord ist entkommen. Ich sehe ihn nirgends. Ganz gewiss finden wir über ihn unsere gefangenen Freunde.\n\nIch werde ihn verfolgen. Lange kann er sich nicht verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25222] = { id = 25222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Silberfluthöhle", description = "Ein Großteil des Irdenen Rings, der dem Massaker auf den Booten entkommen ist, hat in einer Höhle nahe dem Riff Zuflucht gefunden. Sie ist gut versteckt in einer riesigen Felsformation westlich von Nespirah, der riesigen Schnecke am Horizont. Bitte geht für mich dorthin und seht nach, ob es ihnen gut geht. Zudem kann es gut sein, dass auch sie unter den Nagaangriffen leiden.\n\nIch werde diesen Tiefenlord jagen. Wenn ich herausgefunden habe, hinter welchem Felsen er sich versteckt, lasse ich es Euch wissen.", sourceObjective = "Sucht nach Felora Feuerkranz in der Silberfluthöhle.", completion = "Ein freundliches Gesicht! Willkommen!\n\nSehr nett von Euch, dass Ihr nach uns seht. Uns geht es gut. Ein Spähtrupp der Naga hat uns gefunden, aber ich bin mir ziemlich sicher, dass keiner entkommen konnte. Wir sollten vorerst in Sicherheit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25223] = { id = 25223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerprobe", description = "Ich würde ja gerne sagen, dass wir angesichts des wachsenden Widerstands gegen uns auf dem Hyjal für jeden Rekruten dankbar sind, der uns bei unserer Sache unterstützt und so weiter… aber um ganz ehrlich zu sein, sind die meisten von Euch einfach nur eine Last.\n\nWenn ich eine Kupfermünze für jedes Landei bekommen hätte, das vom Kataklysmus so verängstigt wurde, dass es sich uns jetzt unbedingt anschließen möchte... nun, sagen wir einfach, ich wäre eine reiche Frau.\n\nZum Glück haben wir ein paar Prüfungen vorbereitet, mit denen wir die Spreu vom Weizen trennen können. Geht und beweist Euren Wert an den feurigen Instrukteuren da unten. Hoffentlich schlagt Ihr Euch besser als die anderen.", sourceObjective = "Besiegt 8 feurige Instrukteure.", completion = "Ich schätze, Eure Fähigkeiten sind… geeignet. Ich bin beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25224] = { id = 25224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In voller Blüte", description = "Es ist Brauch, dass neue Rekruten schwierige oder manchmal sogar unmögliche Aufgaben erhalten. Ich wurde losgeschickt, um die Schuppe eines schwarzen Drachen zu beschaffen, der Instrukteur letztes Jahr forderte die Feder eines Phönix'.\n\nIhr habt es dieses Mal vergleichsweise einfach. Besorgt mir eine Handvoll Flammenblüten.\n\nSie wachsen hier in der Gegend relativ zahlreich. Oh, fast hätte ich es vergessen. Damit die Sache interessant bleibt, streift ein gigantischer Kernhund über die Felder. Gebt Euer Bestes, um ihm auszuweichen.", sourceObjective = "Besorgt 5 Flammenblüten.", progress = "Ja, Kunrebidamus?", completion = "Also habt Ihr es geschafft, diesen Teil des Tests zu bestehen, ohne von Loderos gefressen oder von den Feuerelementaren in Brand gesetzt zu werden?\n\nIch schätze, dann sollte ich Euch zum Aufstieg in den niedrigsten Rang unserer Hierarchie gratulieren.\n\nAlso: Herzlichen Glückwunsch, Rekrut!", sourceObjectiveStatus = "unverified-source-field" }
quests[25227] = { id = 25227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thonk", description = "<Hey Süßer, mir ist gerade noch was eingefallen!/Entschuldigt mein Verhalten. Ich werde manchmal zickig> wenn neue Frauen in die Stadt kommen, weil ich nicht sehr selbstsicher bin, was mein Äußeres betrifft.; Ich habe einen SEHR guten Freund, Thonk; er arbeitet im Wachturm nordwestlich von Klingenhügel. Er meinte, dass der Fluss über die Ufer getreten sei und dass es viel Arbeit gäbe. Ich hab ihm nicht wirklich zugehört... seine tiefbraunen Augen lenken mich immer ab.\n\n<Wie, eifersüchtig? Ich soll mich nicht mit anderen treffen?/Danke.>", sourceObjective = "Meldet Euch bei Thonk im Wachturm nordwestlich von Klingenhügel.", completion = "Gail hat Euch geschickt? Hat sie... hat sie etwas über mich gesagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[25229] = { id = 25229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Gnomenehre", description = "Unsere Ingenieure haben daran gearbeitet, unsere Kampfmaschinen für den Sturm auf Gnomeregan vorzubereiten, aber uns fehlen Piloten!\n\nUnsere Ingenieure haben ein Gerät namens Motivieratron entwickelt, das Ablenkungen verhindert und dem Gnom den Mut verleiht, sich einzuschreiben.\n\nWenn Ihr ein paar Gnomenbürger motiviert habt, führt sie zu Hauptmann Tret Funkdüse, draußen bei Stahlrosts Depot südlich von Eisenschmiede.\n\nOh, und seid vorsichtig. Das Gerät ist noch ein wenig experimentell.", sourceObjective = "Werbt mit Hilfe des Motivieratron Gnome aus Tüftlerstadt an und führt sie zu Hauptmann Tret Funkdüse bei Stahlrosts Depot.", completion = "Das sind die besten zukünftigen Piloten, die Ihr finden konntet?\n\nNa gut, mal sehen, was ich tun kann. Man sagt mir nach, ich könne auch den größten Klumpen verbogener Zahnräder in eine schnurrende Kampfmaschine verwandeln, und ich erwarte von diesem Haufen nicht weniger.\n\nTja, schätze, es ist Zeit, an die Arbeit zu gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25230] = { id = 25230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als Krankheit", description = "Wir haben ein paar Drachenwelpen in der Nähe der Straße gefunden, die nach Norden führt. Die Welpen leiden an der gleichen Krankheit wie die Hirsche.\n\nGründrachen sind nicht einfache Bestien der Natur, sondern magische Kreaturen und die Wächter der Wildnis. Ihre Krankheit stellt für uns eine Bedrohung dar.\n\nWir müssen dafür sorgen, dass sich die Krankheit auf keinen Fall weiter ausbreitet. Tötet die erkrankten Welpen, {name}, und kehrt dann zu mir zurück.", sourceObjective = "Tötet 10 giftige Welpen.", completion = "Die neuesten Entwicklungen besorgen mich sehr. Die Geweihe, die ich in Eurer Abwesenheit untersucht habe, haben ein paar Erkenntnisse zu Tage gebracht.\n\nWir müssen einen Weg finden, dieses Problem zu lösen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25232] = { id = 25232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brennende Klinge", description = "Ich wurde geschickt, um die Anwesenheit der Anhänger der Brennenden Klinge in Durotar zu untersuchen. Nordöstlich von hier ist eine Höhle, in der die Klinge ihre neuen Mitglieder ausbildet. Ich möchte wissen, was genau diese Ausbildung der Neophyten beinhaltet.\n\nIch erzähle Euch das eigentlich nur, weil ich das Gefühl habe, Ihr seid auf der Suche nach Arbeit. Wenn Ihr ein wenig verdienen wollt, so begebt Euch zur Höhle und bringt mir ihre Schriftrollen.\n\nDie Höhle ist etwas versteckt: Verlasst Klingenhügel in Richtung Osten und folgt dann dem östlichen Kamm der Schlucht.", sourceObjective = "Erhaltet 6 Zauberschriftrollen von den Mitgliedern der Brennenden Klinge in der Staubwindhöhle.", progress = "Die Schriftrollen, {name}, die Schriftrollen!", completion = "Das ist wirklich interessant. Diese Rituale sind nicht wirklich anders als die, die den Hexenmeistern der Horde beigebracht werden. Ich muss auf jeden Fall weitere Untersuchungen anstellen!", sourceObjectiveStatus = "unverified-source-field" }
